"use client";

import { useEffect, useId, useRef, useState } from "react";
import { createThemeSwitch, type EffectName, type ThemeName, type ThemeSwitchEngine } from "./theme-switch-engine";
import "./theme-switch.css";

/**
 * Theme Switch — a theme toggle with three ways to change the theme.
 *
 * A square button with a moon on the light face and a sun on the dark one,
 * and a segmented control under it that picks how the switch happens:
 *
 *   Droplet — a drop of the next theme falls onto the icon, splashes, and
 *             floods the scene from where it landed
 *   Rain    — a shower of the next theme leaves puddles that spread, merge and
 *             fill the scene, the controls changing as the rain reaches them
 *   Diwali  — rockets of the next theme fly out from behind the toggle, burst,
 *             and the stars bloom into dots until they cover everything, with
 *             a whistle, a boom and a crackle
 *
 * All of it happens inside the component's own box; the physics and the
 * guaranteed-coverage maths live in theme-switch-engine.ts. When a switch
 * lands, `onThemeChange` is called with the new theme, so the button can
 * drive a real theme. A change to `theme` from outside — the page's own switch
 * — lands at once, with no effect.
 */

export type ThemeSwitchProps = {
  /** The theme the scene shows. A change from outside lands at once. */
  theme?: ThemeName;
  /** Called with the new theme once a switch has covered the scene. */
  onThemeChange?: (theme: ThemeName) => void;
  /** Which effect is chosen to begin with. */
  defaultEffect?: EffectName;
  /** Called when another effect is picked. */
  onEffectChange?: (effect: EffectName) => void;
  /** Diwali's whistle, boom and crackle — synthesised, and only ever after a press. */
  sound?: boolean;
  /** Take the container's whole box. Without it the scene is 480px tall with rounded corners. */
  fill?: boolean;
};

const EFFECTS: { value: EffectName; label: string }[] = [
  { value: "droplet", label: "Droplet" },
  { value: "rain", label: "Rain" },
  { value: "diwali", label: "Diwali" },
];

export default function ThemeSwitch({
  theme = "light",
  onThemeChange,
  defaultEffect = "droplet",
  onEffectChange,
  sound = true,
  fill = false,
}: ThemeSwitchProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const fxRef = useRef<HTMLDivElement>(null);
  const engineRef = useRef<ThemeSwitchEngine | null>(null);
  const [effect, setEffect] = useState<EffectName>(defaultEffect);
  const name = useId();

  /* the engine reads these when it needs them, so they never rebuild it */
  const effectRef = useRef(effect);
  const soundRef = useRef(sound);
  const onThemeChangeRef = useRef(onThemeChange);
  useEffect(() => {
    effectRef.current = effect;
    soundRef.current = sound;
    onThemeChangeRef.current = onThemeChange;
  }, [effect, sound, onThemeChange]);

  useEffect(() => {
    const root = rootRef.current;
    const button = buttonRef.current;
    const fx = fxRef.current;
    if (!root || !button || !fx) return;
    const engine = createThemeSwitch({
      root,
      button,
      fx,
      effect: () => effectRef.current,
      sound: () => soundRef.current,
      onCommit: (next) => onThemeChangeRef.current?.(next),
    });
    engineRef.current = engine;
    return () => {
      engine.destroy();
      engineRef.current = null;
    };
  }, []);

  /*
   * The scene's theme lives on its root as data-theme, which the engine flips
   * the moment a switch covers it. A theme handed in from outside is written
   * there directly, unless a switch is under way — that one lands on its own.
   */
  useEffect(() => {
    const root = rootRef.current;
    if (!root || engineRef.current?.busy()) return;
    root.dataset.theme = theme;
    buttonRef.current?.setAttribute("aria-label", `Switch to ${theme === "dark" ? "light" : "dark"} theme`);
  }, [theme]);

  /* choosing Diwali warms its plan and the audio device while idle, so the first rocket never stutters */
  useEffect(() => {
    if (effect !== "diwali") return;
    const run = () => engineRef.current?.prepare();
    if (window.requestIdleCallback) {
      const idle = window.requestIdleCallback(run, { timeout: 1500 });
      return () => window.cancelIdleCallback(idle);
    }
    const timer = window.setTimeout(run, 200);
    return () => window.clearTimeout(timer);
  }, [effect]);

  const pick = (value: EffectName) => {
    setEffect(value);
    onEffectChange?.(value);
  };

  return (
    <div
      ref={rootRef}
      className="pts"
      data-theme={theme}
      data-effect={effect}
      data-fill={fill || undefined}
    >
      <div className="pts__stage">
        <button ref={buttonRef} type="button" className="pts__toggle" aria-label={`Switch to ${theme === "dark" ? "light" : "dark"} theme`}>
          {/* the moon, on the light face: press it for dark */}
          <svg className="pts__icon pts__icon--moon" width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path
              d="M20.985 12.486C20.8913 14.2221 20.2967 15.894 19.2731 17.2994C18.2495 18.7048 16.8407 19.7837 15.217 20.4055C13.5934 21.0274 11.8243 21.1656 10.1238 20.8035C8.42322 20.4414 6.86395 19.5945 5.63446 18.3652C4.40497 17.1358 3.55789 15.5766 3.19562 13.8761C2.83334 12.1756 2.97139 10.4065 3.59308 8.78282C4.21476 7.15909 5.29346 5.75019 6.69877 4.72644C8.10409 3.70268 9.77586 3.1079 11.512 3.014C11.917 2.992 12.129 3.474 11.914 3.817C11.1949 4.96755 10.887 6.32787 11.0405 7.67595C11.194 9.02403 11.7999 10.2803 12.7593 11.2397C13.7187 12.1991 14.975 12.805 16.323 12.9585C17.6711 13.112 19.0314 12.8041 20.182 12.085C20.526 11.87 21.007 12.081 20.985 12.486Z"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
          {/* the sun, on the dark face: press it for light */}
          <svg className="pts__icon pts__icon--sun" width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <g stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="12" cy="12" r="4" />
              <path d="M12 2V4M12 20V22M4.93 4.93L6.34 6.34M17.66 17.66L19.07 19.07M2 12H4M20 12H22M6.34 17.66L4.93 19.07M19.07 4.93L17.66 6.34" />
            </g>
          </svg>
        </button>

        {/* how the switch happens; it takes the new theme when the flood reaches it */}
        <fieldset className="pts__effects" data-pts-target="">
          <legend className="pts__sr">Theme switch effect</legend>
          <span className="pts__thumb" aria-hidden="true" />
          {EFFECTS.map((option) => (
            <label key={option.value} className="pts__option">
              <input
                type="radio"
                name={name}
                value={option.value}
                checked={effect === option.value}
                onChange={() => pick(option.value)}
              />
              <span>{option.label}</span>
            </label>
          ))}
        </fieldset>
      </div>

      {/* the drop, its ripples and the rain: over the controls, taking no pointer events */}
      <div ref={fxRef} className="pts__fx" aria-hidden="true" />
    </div>
  );
}

/**
 * The Theme Switch's engine — three ways to switch a theme.
 *
 * DROPLET
 *   A drop of the next theme's colour falls from the top of the scene onto the
 *   icon on real kinematics (s = v0·t + ½·g·t²), stretching with its speed
 *   while keeping its volume. It squashes on impact, the button dips and
 *   springs back, ripples spread, and the next theme floods out from the point
 *   of impact as a circle.
 *
 * RAIN
 *   Rain of the next theme's colour falls at terminal velocity, slanted by
 *   wind, with depth: near drops faster, longer and brighter. Every drop
 *   splashes (a crown of droplets under gravity, a ripple on dry ground), and
 *   near drops leave a puddle that spreads like liquid wetting a surface. The
 *   shower builds, the puddles merge, and the last merge is computed rather
 *   than guessed: the puddles are scaled by exactly what closes the largest
 *   dry gap left.
 *
 * DIWALI
 *   Rockets of the next theme's colour fly out from behind the toggle in every
 *   direction with spark trails and a whistle, burst into peonies and tilted
 *   rings under air drag and gravity (solved in closed form, so frame-rate
 *   independent), and the stars settle and bloom into dots that fill the
 *   scene. Every dot's final place is known at click time, so full coverage is
 *   a guarantee. Whistle, boom (a beat after the flash) and crackle are
 *   synthesised with Web Audio and panned to where each shell bursts.
 *
 * Everything happens inside the component's own box. The next theme is
 * painted under the controls, and each control (the toggle, and anything
 * marked data-pts-target) takes the new theme the moment the flood reaches its
 * centre — so it changes "when the rain hits it". When the scene is covered,
 * the scene itself commits. Reduced motion switches at once; a watchdog
 * finishes any run that stalls (a tab put in the background), so a switch can
 * never hang half done.
 */

export type ThemeName = "light" | "dark";
export type EffectName = "droplet" | "rain" | "diwali";

export type ThemeSwitchEngine = {
  /** Switch with the current effect; resolves once the scene has taken the next theme. */
  toggle: () => void;
  /** Warm the Diwali plan and the audio device before the click that needs them. */
  prepare: () => void;
  busy: () => boolean;
  destroy: () => void;
};

type Options = {
  root: HTMLElement;
  button: HTMLButtonElement;
  fx: HTMLElement;
  effect: () => EffectName;
  sound: () => boolean;
  /** The moment the scene is fully covered by the next theme. */
  onCommit: (theme: ThemeName) => void;
};

const THEMES: Record<ThemeName, { bg: string; ring: string }> = {
  light: { bg: "#ffffff", ring: "rgba(0, 0, 0, 0.10)" },
  dark: { bg: "#141414", ring: "rgba(255, 255, 255, 0.10)" },
};

const EASE_OUT = "cubic-bezier(0.23, 1, 0.32, 1)";
const EASE_DRAWER = "cubic-bezier(0.32, 0.72, 0, 1)";
/* the longest real run is ~2.4s (Diwali in a large scene) */
const WATCHDOG_MS = 5000;

/* ── utils ─────────────────────────────────────────────────────────────── */

const noop = () => {};
const wait = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));
const finished = (anim: Animation) => anim.finished.then(noop, noop);
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));
const rand = (a: number, b: number) => a + Math.random() * (b - a);
const easeInOutCubic = (p: number) => (p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2);
const easeOutCubic = (p: number) => 1 - Math.pow(1 - p, 3);

/* "#rrggbb" at zero alpha: fading to "transparent" fades through black in some engines */
function transparentOf(hex: string) {
  const n = parseInt(hex.slice(1), 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, 0)`;
}

/* a damped harmonic oscillator sampled into a CSS linear() easing */
function springLinear(durationS: number, bounce: number) {
  const zeta = 1 - bounce;
  const omega = (2 * Math.PI) / durationS;
  const wd = omega * Math.sqrt(1 - zeta * zeta);
  const pts: string[] = [];
  for (let i = 0, n = 48; i <= n; i++) {
    const t = (durationS * i) / n;
    const x = 1 - Math.exp(-zeta * omega * t) * (Math.cos(wd * t) + ((zeta * omega) / wd) * Math.sin(wd * t));
    pts.push(i === n ? "1" : x.toFixed(4));
  }
  return `linear(${pts.join(", ")})`;
}

const SPRING_MS = 520;

/* ── shared puddle maths (Rain and Diwali) ─────────────────────────────── */

type Lobe = { dx: number; dy: number; s: number };
type Spot = { x: number; y: number; born: number; r0: number; rmax: number; lobes: Lobe[]; tau?: number; creep?: number };
type Target = { el: HTMLElement; x: number; y: number; done: boolean };

const RAIN = {
  spawnMs: 900, // how long new drops keep entering
  windDeg: 9, // slant from vertical
  puddleArea: 85 * 85, // about one surface-wetting drop per this many px²
  minPuddles: 30,
  maxPuddles: 170,
  ambientRatio: 1.4, // far drops per wetting drop
  spreadTauMs: 260, // how fast a wet spot spreads
  creepPxPerS: 14, // the slow spread after the splash
  mergeMs: 460,
  splashGravity: 2400,
  rippleMs: 420,
  tailMs: 380, // the last splashes settle after the switch
};

function puddleBase(p: Spot, t: number) {
  const age = Math.max(0, t - p.born);
  const tau = p.tau || RAIN.spreadTauMs;
  const creep = p.creep != null ? p.creep : RAIN.creepPxPerS;
  return p.r0 + (p.rmax - p.r0) * (1 - Math.exp(-age / tau)) + (creep * age) / 1000;
}

/*
 * The smallest uniform scale k at which the spots' main circles cover every
 * pixel. Cell centres are sampled with half a cell's diagonal added to each
 * distance, which makes it a bound for every pixel in the cell rather than an
 * estimate. Spots are bucketed and the search stops once no farther bucket
 * could do better, so it is exact without being slow.
 */
function coverageScale(spots: Spot[], t: number, w: number, h: number) {
  const n = spots.length;
  if (!n) return 1;
  const cell = Math.max(40, Math.max(w, h) / 48);
  const cols = Math.ceil(w / cell);
  const rows = Math.ceil(h / cell);
  const half = Math.hypot(w / cols, h / rows) / 2;
  const bases = new Array<number>(n);
  let maxBase = 0;
  for (let i = 0; i < n; i++) {
    bases[i] = puddleBase(spots[i], t);
    if (bases[i] > maxBase) maxBase = bases[i];
  }
  const B = cell * 2;
  const nx = Math.max(1, Math.ceil(w / B));
  const ny = Math.max(1, Math.ceil(h / B));
  const buckets: number[][] = Array.from({ length: nx * ny }, () => []);
  for (let i = 0; i < n; i++) {
    /* a spot outside the scene joins the edge bucket: it is only ever farther than that */
    const bx = clamp(Math.floor(spots[i].x / B), 0, nx - 1);
    const by = clamp(Math.floor(spots[i].y / B), 0, ny - 1);
    buckets[by * nx + bx].push(i);
  }
  const maxRing = Math.max(nx, ny);
  let worst = 1;
  for (let iy = 0; iy < rows; iy++) {
    for (let ix = 0; ix < cols; ix++) {
      const x = ((ix + 0.5) * w) / cols;
      const y = ((iy + 0.5) * h) / rows;
      const cbx = clamp(Math.floor(x / B), 0, nx - 1);
      const cby = clamp(Math.floor(y / B), 0, ny - 1);
      let best = Infinity;
      for (let r = 0; r <= maxRing; r++) {
        if (r >= 1 && ((r - 1) * B + half) / maxBase >= best) break;
        for (let gy = cby - r; gy <= cby + r; gy++) {
          if (gy < 0 || gy >= ny) continue;
          for (let gx = cbx - r; gx <= cbx + r; gx++) {
            if (gx < 0 || gx >= nx) continue;
            if (Math.max(Math.abs(gx - cbx), Math.abs(gy - cby)) !== r) continue;
            for (const q of buckets[gy * nx + gx]) {
              const need = (Math.hypot(x - spots[q].x, y - spots[q].y) + half) / bases[q];
              if (need < best) best = need;
            }
          }
        }
      }
      if (best > worst) worst = best;
    }
  }
  return worst * 1.01;
}

/* ── Diwali's closed-form stars ────────────────────────────────────────── */

const DIWALI = {
  launchGapMs: 45,
  minBurstDist: 110, // no shell bursts right on top of the toggle
  dragK: 2.4, // 1/s air drag
  gravity: 40, // a gentle droop as stars slow
  bloomTauMs: 420,
  settleMs: 300,
  mergeMs: 440,
  trailSparksPerS: 110,
};

type Star = { x0: number; y0: number; vx: number; vy: number; born: number; r0: number; rmax: number };
type Shell = {
  x0: number;
  y0: number;
  tx: number;
  ty: number;
  launch: number;
  flight: number;
  burst: number;
  kind: "ring" | "peony";
  crackle: boolean;
  speed: number;
  curve: number;
  launched: boolean;
  burstDone: boolean;
  stars: Star[];
  sparkDebt: number;
  prevPos: { x: number; y: number } | null;
};
type DiwaliPlan = { shells: Shell[]; stars: Star[]; ignition: Spot; scale: number; mergeStart: number; mergeK: number };

/*
 * Under air drag (dv/dt = −k·v + g) a star's path has a closed form:
 *   v(t) = g/k + (v0 − g/k)·e^(−kt)
 *   s(t) = (g/k)·t + (v0 − g/k)·(1 − e^(−kt))/k
 * so where every star is at any moment is known exactly.
 */
function starPos(d: Star, t: number) {
  const age = Math.max(0, (t - d.born) / 1000);
  const k = DIWALI.dragK;
  const g = DIWALI.gravity;
  const e = 1 - Math.exp(-k * age);
  return { x: d.x0 + (d.vx / k) * e, y: d.y0 + (g / k) * age + ((d.vy - g / k) * e) / k };
}

function dotRadius(d: Star, t: number) {
  const age = Math.max(0, t - d.born);
  return d.r0 + (d.rmax - d.r0) * (1 - Math.exp(-age / DIWALI.bloomTauMs));
}

function makeStars(s: Shell, scale: number, cellR: number): Star[] {
  const stars: Star[] = [];
  const count = Math.round((s.kind === "ring" ? 110 : 140) * Math.sqrt(scale));
  const tilt = rand(0, Math.PI);
  const squash = rand(0.45, 0.8);
  for (let i = 0; i < count; i++) {
    const a = (i / count) * Math.PI * 2 + rand(-0.06, 0.06);
    let v: number;
    if (s.kind === "ring") {
      v = s.speed * (i % 3 ? rand(0.96, 1.04) : Math.sqrt(Math.random()));
    } else if (i % 2) {
      /* a spherical shell seen head-on: stars bunch toward the rim, like the real thing */
      const c = rand(-1, 1);
      v = s.speed * Math.sqrt(1 - c * c) * rand(0.9, 1.05);
    } else {
      /* the other half fills the disc evenly, so a shell leaves a solid patch, not a hollow ring */
      v = s.speed * Math.sqrt(Math.random()) * rand(0.95, 1.05);
    }
    let vx = Math.cos(a) * v;
    let vy = Math.sin(a) * v;
    if (s.kind === "ring" && i % 3) {
      /* most of a ring shell forms the tilted ring; a third fills inside it */
      const rx = vx;
      const ry = vy * squash;
      vx = rx * Math.cos(tilt) - ry * Math.sin(tilt);
      vy = rx * Math.sin(tilt) + ry * Math.cos(tilt);
    }
    stars.push({
      x0: s.tx,
      y0: s.ty,
      vx,
      vy,
      born: s.burst,
      r0: 1.4 * Math.min(1.3, scale + 0.2),
      /* settled stars bloom into dots big enough to overlap their neighbours */
      rmax: cellR * 0.17 * rand(0.75, 1.25),
    });
  }
  return stars;
}

function planDiwali(w: number, h: number, origin: { x: number; y: number }): DiwaliPlan {
  const scale = clamp(Math.sqrt((w * h) / (1280 * 800)), 0.7, 1.3);
  /* one shell per cell of a full grid: no empty cells, so no bare regions */
  const target = clamp(Math.round((w * h) / 110000), 6, 14);
  const cols = Math.max(2, Math.round(Math.sqrt((target * w) / h)));
  const rows = Math.max(2, Math.round(target / cols));
  const cw = w / cols;
  const ch = h / rows;
  const cellR = Math.sqrt(cw * ch) / 2;
  /* past the cell's corners, so neighbouring shells overlap even with jitter */
  const reach = (1.25 * Math.hypot(cw, ch)) / 2;
  const minDist = DIWALI.minBurstDist * scale;

  const pts: { x: number; y: number; d: number }[] = [];
  for (let gy = 0; gy < rows; gy++) {
    for (let gx = 0; gx < cols; gx++) {
      let x = (gx + 0.5 + rand(-0.28, 0.28)) * cw;
      let y = (gy + 0.5 + rand(-0.28, 0.28)) * ch;
      let d = Math.hypot(x - origin.x, y - origin.y);
      if (d < minDist) {
        const a = d > 0.001 ? Math.atan2(y - origin.y, x - origin.x) : rand(0, Math.PI * 2);
        x = origin.x + Math.cos(a) * minDist;
        y = origin.y + Math.sin(a) * minDist;
        d = minDist;
      }
      pts.push({ x, y, d });
    }
  }
  /* nearest first: the show radiates out from the toggle like a wave */
  pts.sort((a, b) => a.d - b.d);

  const shells: Shell[] = pts.map((p, i) => {
    const launch = i * DIWALI.launchGapMs + rand(0, 25);
    const flight = clamp(240 + p.d * 0.5, 300, 640);
    return {
      x0: origin.x,
      y0: origin.y,
      tx: p.x,
      ty: p.y,
      launch,
      flight,
      burst: launch + flight,
      kind: i % 4 === 3 ? "ring" : "peony",
      crackle: Math.random() < 0.3,
      speed: reach * DIWALI.dragK * rand(0.92, 1.08), // a star's reach is v/k
      curve: rand(-0.12, 0.12) * p.d, // rockets arc a little, never ruler-straight
      launched: false,
      burstDone: false,
      stars: [],
      sparkDebt: 0,
      prevPos: null,
    };
  });

  const stars: Star[] = [];
  for (const s of shells) {
    s.stars = makeStars(s, scale, cellR);
    stars.push(...s.stars);
  }

  /* the launcher's own ignition: a ring of the new theme round the 54px toggle, so it switches as it fires */
  const ignition: Spot = { x: origin.x, y: origin.y, born: 0, r0: 28, rmax: 52 * Math.max(1, scale), tau: 160, creep: 0, lobes: [] };

  const lastBurst = shells.reduce((m, s) => Math.max(m, s.burst), 0);
  const mergeStart = lastBurst + DIWALI.settleMs;
  const tEnd = mergeStart + DIWALI.mergeMs;

  /* where every dot ends, and how big: exact, so the merge is a guarantee */
  const final: Spot[] = stars.map((d) => {
    const p = starPos(d, tEnd);
    const r = dotRadius(d, tEnd);
    return { x: p.x, y: p.y, born: 0, r0: r, rmax: r, tau: 1, creep: 0, lobes: [] };
  });
  final.push(ignition);
  const mergeK = Math.max(1, coverageScale(final, tEnd, w, h));
  return { shells, stars, ignition, scale, mergeStart, mergeK };
}

/* one anti-aliased disc, drawn once and stamped per star: ~1,000 quads are far cheaper than ~1,000 arcs */
function makeDotSprite(color: string) {
  const size = 256;
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const x = c.getContext("2d")!;
  x.fillStyle = color;
  x.beginPath();
  x.arc(size / 2, size / 2, size / 2 - 1, 0, Math.PI * 2);
  x.fill();
  return c;
}

/* ── sound: Web Audio, no files ────────────────────────────────────────── */

function createSound(enabled: () => boolean) {
  let ac: AudioContext | null = null;
  let master: GainNode | null = null;
  let noise: AudioBuffer | null = null;

  function ensure(): AudioContext | null {
    if (!enabled()) return null;
    try {
      if (!ac) {
        const AC =
          window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
        if (!AC) return null;
        ac = new AC();
        master = ac.createGain();
        master.gain.value = 0.5;
        const comp = ac.createDynamicsCompressor();
        comp.threshold.value = -16;
        comp.knee.value = 12;
        comp.ratio.value = 5;
        master.connect(comp);
        comp.connect(ac.destination);
        const len = ac.sampleRate * 2;
        noise = ac.createBuffer(1, len, ac.sampleRate);
        const data = noise.getChannelData(0);
        for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
      }
      if (ac.state === "suspended") void ac.resume();
      return ac;
    } catch {
      return null;
    }
  }

  function out(pan: number): AudioNode {
    /* the types say every engine has a panner; older Safari did not */
    if (typeof (ac as AudioContext & { createStereoPanner?: unknown }).createStereoPanner === "function") {
      const p = ac!.createStereoPanner();
      p.pan.value = clamp(pan, -1, 1);
      p.connect(master!);
      return p;
    }
    return master!;
  }

  function noiseSource(when: number, offset: number, dur: number) {
    const s = ac!.createBufferSource();
    s.buffer = noise;
    s.start(when, offset);
    s.stop(when + dur);
    return s;
  }

  function env(param: AudioParam, when: number, peak: number, attack: number, release: number) {
    param.setValueAtTime(0.0001, when);
    param.linearRampToValueAtTime(peak, when + attack);
    param.exponentialRampToValueAtTime(0.0001, when + attack + release);
  }

  return {
    unlock: ensure,
    /* a rising whistle and hiss for the flight */
    launch(durS: number, pan: number) {
      const a = ensure();
      if (!a) return;
      try {
        const now = a.currentTime;
        const o = out(pan * 0.5);
        const osc = a.createOscillator();
        osc.type = "sine";
        osc.frequency.setValueAtTime(650, now);
        osc.frequency.exponentialRampToValueAtTime(2400, now + durS);
        const g = a.createGain();
        env(g.gain, now, 0.035, 0.06, durS);
        osc.connect(g).connect(o);
        osc.start(now);
        osc.stop(now + durS + 0.1);
        const hiss = noiseSource(now, Math.random(), durS + 0.1);
        const bp = a.createBiquadFilter();
        bp.type = "bandpass";
        bp.frequency.value = 3000;
        bp.Q.value = 0.8;
        const hg = a.createGain();
        env(hg.gain, now, 0.05, 0.03, durS);
        hiss.connect(bp).connect(hg).connect(o);
      } catch {
        /* a sound that cannot play is no reason to stop the show */
      }
    },
    /* the boom: a noise body and a low thump, a beat after the flash, as sound is slower than light */
    boom(pan: number, size: number, delayS: number) {
      const a = ensure();
      if (!a) return;
      try {
        const when = a.currentTime + delayS;
        const o = out(pan);
        const body = noiseSource(when, Math.random() * 0.6, 1.3);
        const lp = a.createBiquadFilter();
        lp.type = "lowpass";
        lp.frequency.setValueAtTime(2600, when);
        lp.frequency.exponentialRampToValueAtTime(160, when + 0.9);
        const bg = a.createGain();
        env(bg.gain, when, 0.75 * size, 0.004, 1.1);
        body.connect(lp).connect(bg).connect(o);
        const thump = a.createOscillator();
        thump.type = "sine";
        thump.frequency.setValueAtTime(120, when);
        thump.frequency.exponentialRampToValueAtTime(38, when + 0.3);
        const tg = a.createGain();
        env(tg.gain, when, 0.8 * size, 0.003, 0.35);
        thump.connect(tg).connect(o);
        thump.start(when);
        thump.stop(when + 0.45);
      } catch {
        /* as above */
      }
    },
    /* crackle: a scatter of tiny high-passed clicks as stars pop */
    crackle(pan: number, delayS: number, count: number) {
      const a = ensure();
      if (!a) return;
      try {
        const hp = a.createBiquadFilter();
        hp.type = "highpass";
        hp.frequency.value = 2200;
        hp.connect(out(pan));
        for (let i = 0; i < count; i++) {
          const when = a.currentTime + delayS + rand(0.35, 0.95);
          const s = noiseSource(when, Math.random() * 1.8, 0.03);
          const g = a.createGain();
          env(g.gain, when, rand(0.12, 0.3), 0.002, 0.018);
          s.connect(g).connect(hp);
        }
      } catch {
        /* as above */
      }
    },
    dispose() {
      void ac?.close().catch(noop);
      ac = null;
    },
  };
}

/* ── the engine ────────────────────────────────────────────────────────── */

export function createThemeSwitch({ root, button, fx, effect, sound: soundOn, onCommit }: Options): ThemeSwitchEngine {
  const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");
  const supportsLinear = CSS.supports("transition-timing-function", "linear(0, 1)");
  const springEase = supportsLinear ? springLinear(SPRING_MS / 1000, 0.3) : EASE_OUT;
  const Sound = createSound(soundOn);

  let busy = false;
  let runId = 0;
  let destroyed = false;
  /* effect-specific teardown, run when a switch ends or is cut short */
  const cleanups: (() => void)[] = [];
  /* the layers an effect paints under the controls */
  const layers = new Set<HTMLElement>();

  const currentTheme = (): ThemeName => (root.dataset.theme === "dark" ? "dark" : "light");
  const size = () => ({ w: root.clientWidth, h: root.clientHeight });

  /* a point in the scene's own coordinates */
  function centreOf(el: Element) {
    const o = root.getBoundingClientRect();
    const r = el.getBoundingClientRect();
    return { x: r.left - o.left + r.width / 2, y: r.top - o.top + r.height / 2 };
  }

  function commit(next: ThemeName) {
    root.dataset.theme = next;
    updateLabel();
    onCommit(next);
  }

  function updateLabel() {
    button.setAttribute("aria-label", `Switch to ${currentTheme() === "dark" ? "light" : "dark"} theme`);
  }

  function pressButton(depth: number) {
    const s = 1 - depth;
    const down = button.animate([{ transform: "scale(1)" }, { transform: `scale(${s})` }], {
      duration: 90,
      easing: EASE_OUT,
      fill: "forwards",
    });
    return finished(down).then(() => {
      const up = button.animate([{ transform: `scale(${s})` }, { transform: "scale(1)" }], {
        duration: SPRING_MS,
        easing: springEase,
        fill: "forwards",
      });
      down.cancel();
      return finished(up).then(() => up.cancel());
    });
  }

  /* a canvas the size of the scene; under the controls unless it is put in the fx layer */
  function makeCanvas(className: string, over = false) {
    const { w, h } = size();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const canvas = document.createElement("canvas");
    canvas.className = className;
    canvas.width = Math.max(1, Math.round(w * dpr));
    canvas.height = Math.max(1, Math.round(h * dpr));
    if (over) fx.appendChild(canvas);
    else {
      root.insertBefore(canvas, root.firstChild);
      layers.add(canvas);
    }
    const ctx = canvas.getContext("2d")!;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return { canvas, ctx, w, h };
  }

  /* the controls that take the next theme when the flood reaches them */
  function floodTargets(): Target[] {
    const els = [button, ...root.querySelectorAll<HTMLElement>("[data-pts-target]")];
    return els.map((el) => ({ el, ...centreOf(el), done: false }));
  }

  function releaseTargets(targets: Target[]) {
    for (const tg of targets) tg.el.removeAttribute("data-theme");
  }

  /* ─ droplet ─ */

  const DROP = {
    gravity: 4000, // px/s²: a ~350px fall reads in about 0.35s
    entryVelocity: 250, // already falling as it enters
    maxStretch: 0.2,
    stretchPerVelocity: 1 / 10000,
    w: 22,
    h: 30,
    squashMs: 220,
    floodDelayMs: 50,
    floodMs: 800,
    rippleMs: 900,
    rippleStaggerMs: 120,
  };

  let dropId = 0;
  function createDrop(color: string) {
    const el = document.createElement("div");
    el.className = "pts__drop";
    const body = "M12 0.5C12 0.5 2 12.6 2 21a10 10 0 0 0 20 0C22 12.6 12 0.5 12 0.5Z";
    const shade = `pts-drop-shade-${++dropId}`;
    el.innerHTML =
      '<svg viewBox="0 0 24 32" aria-hidden="true">' +
      `<defs><linearGradient id="${shade}" x1="0" y1="0" x2="1" y2="1">` +
      '<stop offset="0.45" stop-color="#000" stop-opacity="0"/>' +
      '<stop offset="1" stop-color="#000" stop-opacity="0.25"/>' +
      "</linearGradient></defs>" +
      `<path d="${body}" fill="${color}"/>` +
      `<path d="${body}" fill="url(#${shade})" opacity="0.5"/>` +
      '<ellipse cx="8.2" cy="20" rx="2" ry="3.6" transform="rotate(18 8.2 20)" fill="#fff" opacity="0.35"/>' +
      "</svg>";
    return el;
  }

  function fallKeyframes(cy: number) {
    const distance = cy + 8;
    const g = DROP.gravity;
    const v0 = DROP.entryVelocity;
    const T = (-v0 + Math.sqrt(v0 * v0 + 2 * g * distance)) / g; // s(T) = distance
    const frames: Keyframe[] = [];
    let lastSy = 1;
    for (let i = 0, steps = 30; i <= steps; i++) {
      const t = (T * i) / steps;
      const s = v0 * t + 0.5 * g * t * t;
      const sy = 1 + Math.min(DROP.maxStretch, (v0 + g * t) * DROP.stretchPerVelocity);
      const sx = 1 / Math.sqrt(sy);
      lastSy = sy;
      frames.push({ offset: i / steps, transform: `translateY(${(s - distance).toFixed(2)}px) scale(${sx.toFixed(4)}, ${sy.toFixed(4)})` });
    }
    return { frames, durationMs: T * 1000, impactScaleY: lastSy };
  }

  function squash(drop: HTMLElement, sy: number) {
    return drop.animate(
      [
        { transform: `translateY(0) scale(${1 / Math.sqrt(sy)}, ${sy})`, opacity: 1 },
        { transform: "translateY(0) scale(1.55, 0.5)", opacity: 1, offset: 0.3 },
        { transform: "translateY(0) scale(2.4, 0.12)", opacity: 0 },
      ],
      { duration: DROP.squashMs, easing: EASE_OUT, fill: "forwards" },
    );
  }

  function ripples(cx: number, cy: number, color: string) {
    const all: Promise<void>[] = [];
    for (let i = 0; i < 2; i++) {
      const ring = document.createElement("div");
      ring.className = "pts__ripple";
      ring.style.left = `${cx}px`;
      ring.style.top = `${cy}px`;
      ring.style.color = color;
      fx.appendChild(ring);
      all.push(
        finished(
          ring.animate([{ transform: "scale(1.1)", opacity: 1 }, { transform: `scale(${5 + i * 2.5})`, opacity: 0 }], {
            duration: DROP.rippleMs,
            delay: i * DROP.rippleStaggerMs,
            easing: EASE_OUT,
            fill: "both",
          }),
        ),
      );
    }
    return Promise.all(all);
  }

  /*
   * The flood: a circle of the next theme opening from the impact under the
   * controls, on the drawer curve. The compositor runs the clip; each frame
   * the circle's actual radius is read back from the animation, and a control
   * takes the new theme the moment the circle reaches its centre.
   */
  function circleFlood(next: ThemeName, cx: number, cy: number, id: number) {
    const { w, h } = size();
    const R = Math.ceil(Math.hypot(Math.max(cx, w - cx), Math.max(cy, h - cy))) + 2;
    const overlay = document.createElement("div");
    overlay.className = "pts__flood";
    overlay.style.background = THEMES[next].bg;
    root.insertBefore(overlay, root.firstChild);
    layers.add(overlay);
    const targets = floodTargets();
    cleanups.push(() => releaseTargets(targets));
    const anim = overlay.animate(
      { clipPath: [`circle(0px at ${cx}px ${cy}px)`, `circle(${R}px at ${cx}px ${cy}px)`] },
      { duration: DROP.floodMs, easing: EASE_DRAWER, fill: "forwards" },
    );
    const watch = () => {
      if (id !== runId) return;
      const p = Number(anim.effect?.getComputedTiming().progress ?? 1);
      const r = p * R;
      for (const tg of targets) {
        if (!tg.done && Math.hypot(tg.x - cx, tg.y - cy) < r) {
          tg.done = true;
          tg.el.dataset.theme = next;
        }
      }
      if (anim.playState === "running") requestAnimationFrame(watch);
    };
    requestAnimationFrame(watch);
    return finished(anim).then(() => {
      if (id !== runId) return;
      commit(next);
      releaseTargets(targets);
    });
  }

  function effectDroplet(next: ThemeName, id: number) {
    const c = centreOf(button);
    const drop = createDrop(THEMES[next].bg);
    drop.style.left = `${c.x - DROP.w / 2}px`;
    drop.style.top = `${c.y - DROP.h}px`; // the belly's tip lands on the icon's centre
    fx.appendChild(drop);
    const k = fallKeyframes(c.y);
    const fall = drop.animate(k.frames, { duration: k.durationMs, easing: "linear", fill: "forwards" });
    return finished(fall).then(() => {
      if (id !== runId) return;
      const effects = Promise.all([finished(squash(drop, k.impactScaleY)), pressButton(0.08), ripples(c.x, c.y, THEMES[next].ring)]);
      const flood = wait(DROP.floodDelayMs).then(() => (id === runId ? circleFlood(next, c.x, c.y, id) : undefined));
      return Promise.all([effects, flood]).then(noop);
    });
  }

  /* ─ rain ─ */

  type Drop = {
    z: number;
    speed: number;
    len: number;
    width: number;
    alpha: number;
    x0: number;
    y0: number;
    landX: number;
    landY: number;
    spawn: number;
    land: number;
    puddle: boolean;
    landed: boolean;
    hero?: boolean;
    spot?: Spot;
  };

  /* a jittered grid: random-looking, with no large dry holes */
  function stratified(n: number, w: number, h: number) {
    const cols = Math.max(1, Math.round(Math.sqrt((n * w) / h)));
    const rows = Math.max(1, Math.ceil(n / cols));
    const cells: [number, number][] = [];
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) cells.push([c, r]);
    for (let i = cells.length - 1; i > 0; i--) {
      const j = (Math.random() * (i + 1)) | 0;
      [cells[i], cells[j]] = [cells[j], cells[i]];
    }
    const cw = w / cols;
    const ch = h / rows;
    return cells.slice(0, n).map(([c, r]) => ({ x: (c + Math.random()) * cw, y: (r + Math.random()) * ch }));
  }

  /* a wet spot is not a perfect disc: bumps where the splash spread further, and specks flung past its edge */
  function makeSpot(d: Drop, scale: number): Spot {
    const lobes: Lobe[] = [];
    const nl = 3 + ((Math.random() * 3) | 0);
    for (let l = 0; l < nl; l++) {
      const a = rand(0, Math.PI * 2);
      const off = rand(0.55, 0.85);
      lobes.push({ dx: Math.cos(a) * off, dy: Math.sin(a) * off, s: rand(0.28, 0.46) });
    }
    const ns = 2 + ((Math.random() * 4) | 0);
    for (let m = 0; m < ns; m++) {
      const a = rand(0, Math.PI * 2);
      const off = rand(1.2, 1.9);
      lobes.push({ dx: Math.cos(a) * off, dy: Math.sin(a) * off, s: rand(0.06, 0.14) });
    }
    return {
      x: d.landX,
      y: d.landY,
      born: d.land,
      lobes,
      r0: 1.5 + 2.5 * d.z,
      /* the toggle's spot spills well past the 54px button, so it reads */
      rmax: (d.hero ? 64 : 10 + 38 * d.z) * scale * rand(0.9, 1.15),
    };
  }

  function planRain(w: number, h: number) {
    const tan = Math.tan((RAIN.windDeg * Math.PI) / 180);
    const nP = clamp(Math.round((w * h) / RAIN.puddleArea), RAIN.minPuddles, RAIN.maxPuddles);
    const nA = Math.round(nP * RAIN.ambientRatio);
    const scale = clamp(Math.sqrt((w * h) / (1280 * 800)), 0.75, 1.35);
    const drops: Drop[] = [];

    const makeDrop = (z: number, landX: number, landY: number, puddle: boolean): Drop => {
      const speed = 1300 + 1500 * z; // terminal velocity: near drops read faster
      const len = (16 + 40 * z) * scale;
      const y0 = -len - rand(0, 80);
      /* the shower builds: spawn density rises linearly */
      const spawn = RAIN.spawnMs * Math.sqrt(Math.random());
      return {
        z,
        speed,
        len,
        width: 0.8 + 1.4 * z,
        alpha: 0.3 + 0.6 * z,
        x0: landX - tan * (landY - y0),
        y0,
        landX,
        landY,
        spawn,
        land: spawn + ((landY - y0) / speed) * 1000,
        puddle,
        landed: false,
      };
    };

    for (const p of stratified(nP, w, h)) drops.push(makeDrop(rand(0.55, 1), p.x, p.y, true));
    for (let i = 0; i < nA; i++) drops.push(makeDrop(rand(0.1, 0.5), rand(-0.05, 1.05) * w, rand(0.05, 1.02) * h, false));
    /* a near drop lands on the toggle mid-shower, so the button changes with the rain, not in the final merge */
    const c = centreOf(button);
    const hero = makeDrop(1, c.x, c.y, true);
    const travel = ((c.y - hero.y0) / hero.speed) * 1000;
    hero.land = Math.max(travel + 40, RAIN.spawnMs * 0.55 + travel * 0.5);
    hero.spawn = hero.land - travel;
    hero.hero = true;
    drops.push(hero);

    /* every wet spot is decided now, while nothing moves, so the final merge costs no frame mid-shower */
    let lastLand = 0;
    const spots: Spot[] = [];
    for (const d of drops) {
      if (!d.puddle) continue;
      if (d.land > lastLand) lastLand = d.land;
      d.spot = makeSpot(d, scale);
      spots.push(d.spot);
    }
    const mergeStart = lastLand + 40;
    const mergeK = Math.max(1, coverageScale(spots, mergeStart + RAIN.mergeMs, w, h));
    return { drops, tan, scale, mergeStart, mergeK };
  }

  /* paint the spots (body and lobes) of the next theme, and flip any control a spot reaches */
  function paintSpots(c: CanvasRenderingContext2D, w: number, h: number, spots: Spot[], t: number, k: number, color: string, targets: Target[], next: ThemeName) {
    c.clearRect(0, 0, w, h);
    c.fillStyle = color;
    c.beginPath();
    for (const p of spots) {
      const r = puddleBase(p, t) * k;
      c.moveTo(p.x + r, p.y);
      c.arc(p.x, p.y, r, 0, Math.PI * 2);
      for (const lb of p.lobes) {
        const lx = p.x + lb.dx * r;
        const ly = p.y + lb.dy * r;
        const lr = r * lb.s;
        c.moveTo(lx + lr, ly);
        c.arc(lx, ly, lr, 0, Math.PI * 2);
      }
      for (const tg of targets) {
        if (!tg.done && Math.hypot(tg.x - p.x, tg.y - p.y) < r) {
          tg.done = true;
          tg.el.dataset.theme = next;
        }
      }
    }
    c.fill("nonzero");
  }

  function effectRain(next: ThemeName, id: number) {
    const color = THEMES[next].bg;
    /* puddles of the next theme under the controls; the rain over them */
    const wet = makeCanvas("pts__layer");
    const sky = makeCanvas("pts__layer", true);
    const { w, h, ctx } = sky;
    const wctx = wet.ctx;
    const plan = planRain(w, h);
    const targets = floodTargets();
    const puddles: Spot[] = [];
    const splashes: { x: number; y: number; vx: number; vy: number; r: number; born: number; life: number }[] = [];
    const rings: { x: number; y: number; born: number; rmax: number; z: number }[] = [];
    const tilt = -Math.atan(plan.tan);
    /* one shared streak gradient in unit space, placed per drop by a transform */
    const streak = ctx.createLinearGradient(0, -1, 0, 0);
    streak.addColorStop(0, transparentOf(color));
    streak.addColorStop(1, color);
    let revealed = false;
    let revealedAt = 0;
    const t0 = performance.now();
    cleanups.push(() => releaseTargets(targets));

    return new Promise<void>((resolve) => {
      const land = (d: Drop) => {
        const { landX: x, landY: y } = d;
        if (d.puddle && d.spot) {
          puddles.push(d.spot);
          if (d.hero) void pressButton(0.05);
        }
        /* a crown splash: droplets thrown up and out, more for near drops */
        const n = Math.round(2 + d.z * 4);
        for (let j = 0; j < n; j++) {
          const ang = rand(-Math.PI * 0.92, -Math.PI * 0.08);
          const v = rand(60, 210) * (0.5 + d.z);
          splashes.push({ x, y, vx: Math.cos(ang) * v, vy: Math.sin(ang) * v, r: rand(0.6, 1.2) * (0.6 + d.z), born: d.land, life: rand(200, 340) });
        }
        /* a ripple only on dry ground: inside a fresh puddle a ring reads as a target, not water */
        if (!d.puddle) rings.push({ x, y, born: d.land, rmax: (5 + 16 * d.z) * plan.scale, z: d.z });
      };

      const drawSky = (t: number) => {
        ctx.fillStyle = streak;
        for (const d of plan.drops) {
          if (d.landed || t < d.spawn) continue;
          const y = d.y0 + (d.speed * (t - d.spawn)) / 1000;
          const x = d.x0 + plan.tan * (y - d.y0);
          ctx.save();
          ctx.translate(x, y);
          ctx.rotate(tilt);
          ctx.scale(1, d.len);
          ctx.globalAlpha = d.alpha;
          ctx.fillRect(-d.width / 2, -1, d.width, 1);
          ctx.restore();
        }
        /* ripple rings, a little flattened, as seen at an angle */
        ctx.lineWidth = 1;
        ctx.strokeStyle = color;
        for (let r = rings.length - 1; r >= 0; r--) {
          const g = rings[r];
          const p = (t - g.born) / RAIN.rippleMs;
          if (p >= 1) {
            rings.splice(r, 1);
            continue;
          }
          const rad = 1 + g.rmax * easeOutCubic(p);
          ctx.globalAlpha = (1 - p) * (0.3 + 0.4 * g.z);
          ctx.beginPath();
          ctx.ellipse(g.x, g.y, rad, rad * 0.85, 0, 0, Math.PI * 2);
          ctx.stroke();
        }
        /* crown droplets under gravity */
        ctx.fillStyle = color;
        for (let s = splashes.length - 1; s >= 0; s--) {
          const sp = splashes[s];
          const age = t - sp.born;
          if (age >= sp.life) {
            splashes.splice(s, 1);
            continue;
          }
          const at = age / 1000;
          ctx.globalAlpha = 1 - age / sp.life;
          ctx.beginPath();
          ctx.arc(sp.x + sp.vx * at, sp.y + sp.vy * at + 0.5 * RAIN.splashGravity * at * at, sp.r, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.globalAlpha = 1;
      };

      const frame = (now: number) => {
        if (id !== runId) {
          resolve();
          return;
        }
        const t = now - t0;
        for (const d of plan.drops) {
          if (!d.landed && t >= d.land) {
            d.landed = true;
            land(d);
          }
        }
        let k = 1;
        if (t >= plan.mergeStart && !revealed) {
          const p = clamp((t - plan.mergeStart) / RAIN.mergeMs, 0, 1);
          k = 1 + (plan.mergeK - 1) * easeInOutCubic(p);
          if (p >= 1) {
            /* the scene's background now equals the puddles' colour: seamless */
            revealed = true;
            revealedAt = t;
            commit(next);
            wet.canvas.remove();
            layers.delete(wet.canvas);
            releaseTargets(targets);
          }
        }
        if (!revealed) paintSpots(wctx, w, h, puddles, t, k, color, targets, next);
        ctx.clearRect(0, 0, w, h);
        drawSky(t);
        if (revealed && t - revealedAt > RAIN.tailMs) {
          resolve();
          return;
        }
        requestAnimationFrame(frame);
      };
      requestAnimationFrame(frame);
    });
  }

  /* ─ diwali ─ */

  /*
   * Planning ~1,000 stars and proving coverage costs a few ms (tens on a cold
   * JIT), so it is done before the click — on pointer-down, or when idle once
   * Diwali is chosen — and the click only starts the show. A plan is reused
   * only for the same scene size and toggle position.
   */
  let preplanned: { w: number; h: number; x: number; y: number; plan: DiwaliPlan } | null = null;

  function prepare() {
    if (busy || destroyed || effect() !== "diwali" || reducedMotion.matches) return;
    Sound.unlock();
    try {
      const { w, h } = size();
      const o = centreOf(button);
      preplanned = { w, h, x: o.x, y: o.y, plan: planDiwali(w, h, o) };
    } catch {
      preplanned = null;
    }
  }

  function takePlan(w: number, h: number, origin: { x: number; y: number }) {
    const pre = preplanned;
    preplanned = null;
    if (pre && pre.w === w && pre.h === h && Math.abs(pre.x - origin.x) < 0.5 && Math.abs(pre.y - origin.y) < 0.5) return pre.plan;
    return planDiwali(w, h, origin);
  }

  function effectDiwali(next: ThemeName, id: number) {
    Sound.unlock(); // inside the click: audio is only allowed from a gesture
    const color = THEMES[next].bg; // everything is made of the next theme
    /* the stars' dots under the controls, the rockets just above them and still under the controls */
    const sky = makeCanvas("pts__layer");
    const wet = makeCanvas("pts__layer");
    const { w, h, ctx } = sky;
    const wctx = wet.ctx;
    const origin = centreOf(button);
    const plan = takePlan(w, h, origin);
    const dot = makeDotSprite(color);
    const targets = floodTargets();
    const live: Star[] = [];
    const sparks: { x: number; y: number; vx: number; vy: number; born: number; life: number; size: number }[] = [];
    const rings: { x: number; y: number; born: number; r: number }[] = [];
    const t0 = performance.now();
    let last = 0;
    cleanups.push(() => releaseTargets(targets));
    void pressButton(0.06); // the launcher kicks as it fires

    const flip = (x: number, y: number, r: number) => {
      for (const tg of targets) {
        if (tg.done) continue;
        const dx = tg.x - x;
        const dy = tg.y - y;
        if (dx * dx + dy * dy < r * r) {
          tg.done = true;
          tg.el.dataset.theme = next;
        }
      }
    };

    const rocketPos = (s: Shell, t: number) => {
      const p = clamp((t - s.launch) / s.flight, 0, 1);
      const e = 1 - (1 - p) * (1 - p); // decelerating to the burst, like a coasting shell
      const dx = s.tx - s.x0;
      const dy = s.ty - s.y0;
      const len = Math.hypot(dx, dy) || 1;
      const bow = Math.sin(Math.PI * e) * s.curve;
      return { x: s.x0 + dx * e - (dy / len) * bow, y: s.y0 + dy * e + (dx / len) * bow };
    };

    return new Promise<void>((resolve) => {
      const burst = (s: Shell) => {
        live.push(...s.stars);
        rings.push({ x: s.tx, y: s.ty, born: s.burst, r: 46 * plan.scale });
        const pan = (s.tx / w) * 2 - 1;
        const delay = 0.04 + rand(0, 0.06); // the sound lags the flash
        Sound.boom(pan, s.kind === "ring" ? 0.8 : 1, delay);
        if (s.crackle) Sound.crackle(pan, delay, 18);
      };

      /* the dots bloom where stars settle (stamped from the sprite); fast stars also streak */
      const paintParticles = (t: number, k: number) => {
        wctx.clearRect(0, 0, w, h);
        wctx.fillStyle = color;
        wctx.beginPath();
        const ig = plan.ignition;
        const ir = puddleBase(ig, t) * k;
        wctx.moveTo(ig.x + ir, ig.y);
        wctx.arc(ig.x, ig.y, ir, 0, Math.PI * 2);
        flip(ig.x, ig.y, ir);
        wctx.fill();
        /* one allocation-free pass, so no collection pauses mid-show */
        const K = DIWALI.dragK;
        const gk = DIWALI.gravity / K;
        const tau = DIWALI.bloomTauMs;
        const streaks = k === 1;
        if (streaks) {
          wctx.strokeStyle = color;
          wctx.lineCap = "round";
          wctx.lineWidth = 2 * Math.min(1.3, plan.scale + 0.2);
          wctx.beginPath();
        }
        for (const d of live) {
          const ageMs = t - d.born;
          if (ageMs < 0) continue;
          const age = ageMs / 1000;
          const f = Math.exp(-K * age);
          const e = 1 - f;
          const x = d.x0 + (d.vx / K) * e;
          const y = d.y0 + gk * age + ((d.vy - gk) * e) / K;
          const r = (d.r0 + (d.rmax - d.r0) * (1 - Math.exp(-ageMs / tau))) * k;
          wctx.drawImage(dot, x - r, y - r, r * 2, r * 2);
          flip(x, y, r);
          if (streaks) {
            const vx = d.vx * f;
            const vy = gk + (d.vy - gk) * f;
            if (vx * vx + vy * vy >= 6400) {
              wctx.moveTo(x - vx * 0.04, y - vy * 0.04);
              wctx.lineTo(x, y);
            }
          }
        }
        if (streaks) wctx.stroke();
      };

      const drawRockets = (t: number, dt: number) => {
        ctx.fillStyle = color;
        for (const s of plan.shells) {
          if (!s.launched || s.burstDone) continue;
          const r = rocketPos(s, t);
          /* trail sparks at a fixed rate a second, the same at 60Hz or 144Hz */
          s.sparkDebt += DIWALI.trailSparksPerS * dt;
          const prev = s.prevPos ?? r;
          while (s.sparkDebt >= 1) {
            s.sparkDebt -= 1;
            const f = Math.random();
            sparks.push({
              x: prev.x + (r.x - prev.x) * f + rand(-1, 1),
              y: prev.y + (r.y - prev.y) * f + rand(-1, 1),
              vx: rand(-25, 25),
              vy: rand(15, 60),
              born: t,
              life: rand(200, 380),
              size: rand(1, 2),
            });
          }
          s.prevPos = r;
          ctx.globalAlpha = 1;
          ctx.beginPath();
          ctx.arc(r.x, r.y, 2.6 * plan.scale, 0, Math.PI * 2);
          ctx.fill();
        }
      };

      /* the burst's shock ring marks the pop */
      const drawRings = (t: number) => {
        ctx.strokeStyle = color;
        ctx.lineWidth = 1.5;
        for (let i = rings.length - 1; i >= 0; i--) {
          const g = rings[i];
          const p = (t - g.born) / 260;
          if (p >= 1) {
            rings.splice(i, 1);
            continue;
          }
          ctx.globalAlpha = 1 - p;
          ctx.beginPath();
          ctx.arc(g.x, g.y, g.r * (0.3 + 0.7 * easeOutCubic(p)), 0, Math.PI * 2);
          ctx.stroke();
        }
        ctx.globalAlpha = 1;
      };

      const drawSparks = (t: number, dt: number) => {
        ctx.fillStyle = color;
        for (let i = sparks.length - 1; i >= 0; i--) {
          const sp = sparks[i];
          const age = t - sp.born;
          if (age >= sp.life) {
            sparks.splice(i, 1);
            continue;
          }
          sp.vy += 220 * dt;
          sp.x += sp.vx * dt;
          sp.y += sp.vy * dt;
          ctx.globalAlpha = 1 - age / sp.life;
          ctx.fillRect(sp.x - sp.size / 2, sp.y - sp.size / 2, sp.size, sp.size);
        }
        ctx.globalAlpha = 1;
      };

      const frame = (now: number) => {
        if (id !== runId) {
          resolve();
          return;
        }
        const t = now - t0;
        const dt = clamp((t - last) / 1000, 0, 0.05);
        last = t;
        for (const s of plan.shells) {
          if (!s.launched && t >= s.launch) {
            s.launched = true;
            Sound.launch(s.flight / 1000, (s.tx / w) * 2 - 1);
          }
          if (s.launched && !s.burstDone && t >= s.burst) {
            s.burstDone = true;
            burst(s);
          }
        }
        let k = 1;
        if (t >= plan.mergeStart) {
          const p = clamp((t - plan.mergeStart) / DIWALI.mergeMs, 0, 1);
          k = 1 + (plan.mergeK - 1) * easeInOutCubic(p);
          if (p >= 1) {
            /* the dots cover every pixel in the next theme's colour: commit */
            commit(next);
            releaseTargets(targets);
            resolve();
            return;
          }
        }
        paintParticles(t, k);
        ctx.clearRect(0, 0, w, h);
        drawRockets(t, dt);
        drawRings(t);
        drawSparks(t, dt);
        requestAnimationFrame(frame);
      };
      requestAnimationFrame(frame);
    });
  }

  /* ─ core ─ */

  const EFFECTS: Record<EffectName, (next: ThemeName, id: number) => Promise<void>> = {
    droplet: effectDroplet,
    rain: effectRain,
    diwali: effectDiwali,
  };

  function cleanup() {
    cleanups.splice(0).forEach((fn) => {
      try {
        fn();
      } catch {
        /* one teardown failing must not keep the rest from running */
      }
    });
    fx.replaceChildren();
    layers.forEach((el) => el.remove());
    layers.clear();
    root.classList.remove("is-switching");
    button.getAnimations().forEach((a) => a.cancel());
    button.removeAttribute("data-theme");
    button.removeAttribute("aria-busy");
  }

  function toggle() {
    if (busy || destroyed) return;
    busy = true;
    const id = ++runId;
    const next: ThemeName = currentTheme() === "dark" ? "light" : "dark";
    root.classList.add("is-switching");
    button.setAttribute("aria-busy", "true");

    const instant = reducedMotion.matches || document.visibilityState !== "visible";
    let run: Promise<void>;
    try {
      run = instant ? Promise.resolve(commit(next)) : EFFECTS[effect()](next, id);
    } catch (err) {
      run = Promise.reject(err);
    }

    let watchdog = 0;
    const guard = new Promise<void>((resolve) => {
      watchdog = window.setTimeout(() => {
        runId++; // stops any effect still in flight
        fx.getAnimations({ subtree: true }).forEach((a) => {
          try {
            a.finish();
          } catch {
            a.cancel();
          }
        });
        resolve();
      }, WATCHDOG_MS);
    });

    Promise.race([run, guard])
      .catch((err) => console.error("[ThemeSwitch]", err))
      .then(() => {
        window.clearTimeout(watchdog);
        if (destroyed) return;
        /* never leave the scene on the old theme, whatever happened above */
        if (currentTheme() !== next) commit(next);
        cleanup();
        busy = false;
      });
  }

  const onPointerDown = () => prepare();
  button.addEventListener("pointerdown", onPointerDown);
  button.addEventListener("click", toggle);
  updateLabel();

  return {
    toggle,
    prepare,
    busy: () => busy,
    destroy() {
      destroyed = true;
      runId++;
      button.removeEventListener("pointerdown", onPointerDown);
      button.removeEventListener("click", toggle);
      cleanup();
      Sound.dispose();
    },
  };
}

/* ===========================================================================
   Theme Switch.

   A scene in the theme it shows, with the toggle in the middle and the
   effect picker at its foot. The tokens hang on any [data-theme] inside the
   scene, not only on the scene itself, so a single control can take the next
   theme on its own the moment the flood reaches it — the nearest
   data-theme wins. The layers an effect paints go under the controls
   (.pts__layer, .pts__flood); the drop, its ripples and the rain go over them
   in .pts__fx. Every one of them is inside the scene's box.
=========================================================================== */

.pts {
  --pts-ease-out: cubic-bezier(0.23, 1, 0.32, 1);

  position: relative;
  width: 100%;
  height: 480px;
  overflow: hidden;
  isolation: isolate;
  border-radius: 24px;
  background: var(--pts-bg);
  -webkit-tap-highlight-color: transparent;
}

.pts[data-fill] {
  height: 100%;
  border-radius: 0;
}

.pts[data-theme="light"],
.pts [data-theme="light"] {
  --pts-bg: #ffffff;
  --pts-btn: #efefef;
  --pts-btn-hover: #e7e7e7;
  --pts-btn-border: #efefef;
  --pts-icon: #4c4c4c;
  --pts-focus: rgb(0 0 0 / 0.35);
  --pts-seg-bg: #f5f5f5;
  --pts-seg-thumb: #ffffff;
  --pts-seg-shadow: 0 1px 2px rgb(0 0 0 / 0.08), 0 0 0 1px rgb(0 0 0 / 0.04);
  --pts-seg-text: #8a8a8a;
  --pts-seg-text-active: #1f1f1f;
  /* the icons: the moon shows, the sun waits turned a quarter and shrunk */
  --pts-moon-o: 1;
  --pts-moon-t: none;
  --pts-sun-o: 0;
  --pts-sun-t: rotate(90deg) scale(0.6);
  color-scheme: light;
}

.pts[data-theme="dark"],
.pts [data-theme="dark"] {
  --pts-bg: #141414;
  --pts-btn: #1f1f1f;
  --pts-btn-hover: #262626;
  --pts-btn-border: #141414;
  --pts-icon: #ffffff;
  --pts-focus: rgb(255 255 255 / 0.45);
  --pts-seg-bg: #1a1a1a;
  --pts-seg-thumb: #2a2a2a;
  --pts-seg-shadow: 0 1px 2px rgb(0 0 0 / 0.4), 0 0 0 1px rgb(255 255 255 / 0.04);
  --pts-seg-text: #7a7a7a;
  --pts-seg-text-active: #f2f2f2;
  /* both icons leave and arrive turning the same way for a given switch */
  --pts-moon-o: 0;
  --pts-moon-t: rotate(-90deg) scale(0.6);
  --pts-sun-o: 1;
  --pts-sun-t: none;
  color-scheme: dark;
}

.pts *,
.pts *::before,
.pts *::after {
  box-sizing: border-box;
}

.pts__stage {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: grid;
  place-items: center;
}

/* ── the toggle ────────────────────────────────────────────────────────── */

.pts__toggle {
  position: relative;
  display: grid;
  place-items: center;
  width: 54px;
  height: 54px;
  margin: 0;
  padding: 0;
  border: 1px solid var(--pts-btn-border);
  border-radius: 12px;
  background: var(--pts-btn);
  color: var(--pts-icon);
  font: inherit;
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  touch-action: manipulation;
  transition: background-color 150ms ease;
}

.pts__toggle:focus-visible {
  outline: 2px solid var(--pts-focus);
  outline-offset: 3px;
}

@media (hover: hover) and (pointer: fine) {
  .pts__toggle:hover {
    background: var(--pts-btn-hover);
  }
}

.pts__icon {
  display: block;
  grid-area: 1 / 1;
  transition:
    transform 450ms var(--pts-ease-out),
    opacity 220ms var(--pts-ease-out);
}

.pts__icon--moon {
  opacity: var(--pts-moon-o);
  transform: var(--pts-moon-t);
}

.pts__icon--sun {
  opacity: var(--pts-sun-o);
  transform: var(--pts-sun-t);
}

/* ── the effect picker ─────────────────────────────────────────────────── */

.pts__effects {
  --pts-seg-w: 76px;

  position: absolute;
  left: 50%;
  /* a host with something floating at the foot (a toolbar, a dock) raises this */
  bottom: calc(var(--pts-inset-bottom, 0px) + 28px);
  display: flex;
  margin: 0;
  padding: 3px;
  min-inline-size: 0;
  border: 0;
  border-radius: 10px;
  background: var(--pts-seg-bg);
  font: 500 13px/1 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  translate: -50% 0;
  user-select: none;
  -webkit-user-select: none;
}

.pts__thumb {
  position: absolute;
  top: 3px;
  left: 3px;
  width: var(--pts-seg-w);
  height: calc(100% - 6px);
  border-radius: 7px;
  background: var(--pts-seg-thumb);
  box-shadow: var(--pts-seg-shadow);
  transition: transform 220ms var(--pts-ease-out);
}

.pts[data-effect="rain"] .pts__thumb {
  transform: translateX(100%);
}

.pts[data-effect="diwali"] .pts__thumb {
  transform: translateX(200%);
}

.pts__option {
  position: relative;
  display: grid;
  place-items: center;
  width: var(--pts-seg-w);
  height: 28px;
  border-radius: 7px;
  color: var(--pts-seg-text);
  cursor: pointer;
  touch-action: manipulation;
  transition: color 150ms ease;
}

.pts__option input {
  position: absolute;
  inset: 0;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.pts__option:has(input:checked) {
  color: var(--pts-seg-text-active);
}

.pts__option:has(input:focus-visible) {
  outline: 2px solid var(--pts-focus);
  outline-offset: 1px;
}

@media (hover: hover) and (pointer: fine) {
  .pts__option:hover {
    color: var(--pts-seg-text-active);
  }
}

/* colours are revealed by the flood, never cross-faded */
.pts.is-switching .pts__toggle,
.pts.is-switching .pts__option,
.pts.is-switching .pts__thumb {
  transition: none;
}

.pts__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* ── the effects' layers ───────────────────────────────────────────────── */

/* under the controls: the flood, the puddles, the fireworks */
.pts__flood,
.pts__layer {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.pts__layer {
  display: block;
}

/* over the controls: the drop, its ripples, the rain */
.pts__fx {
  position: absolute;
  inset: 0;
  z-index: 3;
  overflow: hidden;
  pointer-events: none;
}

.pts__fx .pts__layer {
  z-index: auto;
}

.pts__drop {
  position: absolute;
  width: 22px;
  height: 30px;
  transform-origin: 50% 100%;
  will-change: transform;
}

.pts__drop svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.pts__ripple {
  position: absolute;
  width: 54px;
  height: 54px;
  margin: -27px 0 0 -27px;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  opacity: 0;
}

@media (prefers-reduced-motion: reduce) {
  .pts__icon {
    transform: none !important;
    transition: opacity 200ms ease;
  }
}

"use client";

import { useEffect, useRef } from "react";
import { animate, type AnimationPlaybackControlsWithThen } from "motion/react";
import { glassSheet, liquidGlass, type Glass } from "./reader-card-glass";
import "./reader-card.css";

/**
 * Reader Card — a story card that scrolls in place and morphs into a
 * liquid-glass reader.
 *
 * The card is a small page of a story you can scroll with the wheel, under a
 * progressive blur at both edges. Open it and the card's own surface grows
 * into the reader, already on the passage the card was showing, and the
 * lines it was on flash once in the text. The reader is real liquid glass
 * over a drifting ambient light: the close button and the toolbar refract
 * what is behind them, and the panel itself is frosted with a baked rim
 * light. Type size steps up and down without losing your place, a bar keeps
 * your progress, and Escape, the scrim or the close button fold it back into
 * the card.
 *
 * The morph never relayouts: the reader always sits at its final size and only
 * a clip-path moves, between the card's box and the panel's, so the text never
 * re-wraps mid-flight and every frame stays on the compositor. The glass
 * filters are off while anything moves and are switched on only once it is
 * still, under an opaque sheet, so their first paint is never seen.
 */

export type ReaderCardProps = {
  theme?: "light" | "dark";
  /** Take the container's whole box. Without it the scene is 640px tall with rounded corners. */
  fill?: boolean;
  /** Called when the reader has opened, and when it starts to close. */
  onOpenChange?: (open: boolean) => void;
};

/* ── motion ────────────────────────────────────────────────────────────── */
const snappy = { type: "spring", stiffness: 520, damping: 32, mass: 0.7 } as const;
const soft = { type: "spring", stiffness: 240, damping: 26, mass: 0.9 } as const;
const bouncy = { type: "spring", stiffness: 420, damping: 18, mass: 0.8 } as const;
/* visualDuration fixes the spring's perceived length; bounce adds the settle */
const morphOpen = { type: "spring", visualDuration: 0.52, bounce: 0.16 } as const;
const morphClose = { type: "spring", visualDuration: 0.4, bounce: 0 } as const;
const outQuint = [0.22, 1, 0.36, 1] as const;

/* ── the card's excerpt geometry, from the design ─────────────────────── */
/** where the first visible line sits in the card */
const EXCERPT_TOP = 72.5;
const EXCERPT_PAD_BOTTOM = 118;
const EXCERPT_LINE = 23;
const CARD_RADIUS = 40;

/** the reader's type sizes, smallest to largest; it opens on the middle one */
const SIZES = [16, 17.5, 19, 21, 23];
const START_SIZE = 2;

type Rect = { left: number; top: number; width: number; height: number };
type Panel = Rect & { radius: number };
type State = "closed" | "opening" | "open" | "closing";

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const clamp01 = (v: number) => Math.min(1, Math.max(0, v));

/* the lines the card's excerpt is set in: hand-broken in the design, so they read the same everywhere */
const CARD_LINES = [
  "soon be racing along the beach in",
  "search of treasure the storm had",
  "thrown ashore, and how they would",
  "tease her for spending the bright",
  "morning indoors with dusty glass",
  "and old brass. She reached the lamp",
  "room and wiped the lenses one by",
  "one. In the third pane she found a",
  "crack no wider than a hair, and in",
  "the crack, caught like a pressed",
];

function ProgressiveBlur({ edge, className = "" }: { edge: "top" | "bottom"; className?: string }) {
  return (
    <div className={`prc__pblur prc__pblur--${edge} ${className}`} aria-hidden="true">
      <i />
      <i />
      <i />
      <i />
    </div>
  );
}

export default function ReaderCard({ theme = "light", fill = false, onOpenChange }: ReaderCardProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const onOpenChangeRef = useRef(onOpenChange);
  useEffect(() => {
    onOpenChangeRef.current = onOpenChange;
  }, [onOpenChange]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const q = <T extends HTMLElement = HTMLElement>(sel: string) => root.querySelector(sel) as T;

    const stage = q(".prc__stage");
    const card = q(".prc__card");
    const cardContent = q(".prc__content");
    const excerpt = q(".prc__excerpt");
    const excerptAnchor = q(".prc__lines");
    const openPill = q<HTMLButtonElement>(".prc__open");
    const bounds = q(".prc__bounds");
    const scrim = q(".prc__scrim");
    const shadow = q(".prc__shadow");
    const reader = q(".prc__reader");
    const glassEl = q(".prc__glass");
    const solid = q(".prc__solid");
    const previewHost = q(".prc__previewHost");
    const inner = q(".prc__inner");
    const scroller = q(".prc__scroll");
    const prose = q(".prc__prose");
    const exStart = q("[data-ex-start]");
    const exEnd = q("[data-resume]");
    const resumeMark = q(".prc__resume");
    const closeBtn = q<HTMLButtonElement>(".prc__close");
    const toolbar = q(".prc__toolbar");
    const fontBtns = [...root.querySelectorAll<HTMLButtonElement>("[data-font]")];
    const progressFill = q(".prc__progressFill");
    const progressText = q(".prc__progressText");

    const reduce = () => matchMedia("(prefers-reduced-motion: reduce)").matches;
    let disposed = false;
    const cleanups: (() => void)[] = [];
    const listen = <K extends keyof HTMLElementEventMap>(
      el: HTMLElement,
      type: K,
      fn: (e: HTMLElementEventMap[K]) => void,
      opts?: AddEventListenerOptions,
    ) => {
      el.addEventListener(type, fn, opts);
      cleanups.push(() => el.removeEventListener(type, fn, opts));
    };

    /* ── liquid glass ──────────────────────────────────────────────────── */
    const glasses: Glass[] = [liquidGlass(openPill, { thickness: 14, refraction: 14, blur: 0.6, glareRange: 5 })];
    let panelGlass = false;
    /* the reader's glass is baked while the page is idle, never on the click that opens it */
    function ensureReaderGlass() {
      if (panelGlass || disposed) return;
      panelGlass = true;
      glasses.push(
        glassSheet(glassEl, {
          thickness: 28,
          refraction: 26,
          ior: 1.45,
          blur: 22,
          saturate: 1.6,
          fresnel: 0.22,
          fresnelRange: 10,
          glare: 0.55,
          glareRange: 8,
        }),
        liquidGlass(closeBtn, { thickness: 13, refraction: 12, blur: 1.2, glare: 0.9 }),
        liquidGlass(toolbar, { thickness: 14, refraction: 14, blur: 1.5, glare: 0.75 }),
      );
    }
    const idle = window.requestIdleCallback
      ? window.requestIdleCallback(ensureReaderGlass, { timeout: 1500 })
      : window.setTimeout(ensureReaderGlass, 200);
    cleanups.push(() =>
      window.cancelIdleCallback ? window.cancelIdleCallback(idle) : window.clearTimeout(idle),
    );

    /* ── a liquid press: the glass squashes, then springs back ─────────── */
    function liquidPress(el: HTMLElement) {
      let down = false;
      const release = () => {
        if (!down) return;
        down = false;
        if (!reduce()) animate(el, { scaleX: 1, scaleY: 1 }, bouncy);
      };
      listen(el, "pointerdown", (e) => {
        if (e.button !== 0) return;
        down = true;
        if (!reduce()) animate(el, { scaleX: 1.06, scaleY: 0.92 }, snappy);
      });
      listen(el, "pointerup", release);
      listen(el, "pointerleave", release);
      listen(el, "pointercancel", release);
    }

    /* ── entrance ──────────────────────────────────────────────────────── */
    const fontsReady = Promise.race([document.fonts.ready, new Promise((r) => setTimeout(r, 1200))]);
    fontsReady.then(() => {
      if (disposed) return;
      resetExcerpt();
      if (reduce()) {
        card.style.opacity = "1";
        return;
      }
      animate(
        card,
        { opacity: [0, 1], y: [16, 0], scale: [0.97, 1], filter: ["blur(8px)", "blur(0px)"] },
        soft,
      ).then(() => {
        /* a resting filter, even blur(0), would make the card its own compositing layer for nothing */
        if (!disposed) card.style.filter = "";
      });
      animate(openPill, { opacity: [0, 1], scale: [0.6, 1] }, { ...bouncy, delay: 0.25 });
    });

    /* ── the card's excerpt: scrollable, starting on the passage in the design ── */
    function resetExcerpt() {
      excerpt.scrollTop = excerptAnchor.offsetTop - EXCERPT_TOP;
    }
    resetExcerpt();

    /* ── geometry ──────────────────────────────────────────────────────
       Everything is measured in the scene's own coordinates, so the reader
       grows out of the card wherever the scene sits on the page. The panel's
       room is drawn by .prc__bounds in CSS: a margin all round, more at the
       foot when something floats there.                               */
    let rt: Panel = { left: 0, top: 0, width: 0, height: 0, radius: CARD_RADIUS };
    function local(r: DOMRect): Rect {
      const o = root!.getBoundingClientRect();
      return { left: r.left - o.left, top: r.top - o.top, width: r.width, height: r.height };
    }
    function targetRect(): Panel {
      const b = local(bounds.getBoundingClientRect());
      const width = Math.min(680, b.width);
      const height = Math.min(860, b.height);
      return {
        left: b.left + (b.width - width) / 2,
        top: b.top + (b.height - height) / 2,
        width,
        height,
        radius: root!.clientWidth < 560 ? 32 : CARD_RADIUS,
      };
    }
    function layoutReader() {
      rt = targetRect();
      for (const el of [reader, shadow]) {
        el.style.left = `${rt.left}px`;
        el.style.top = `${rt.top}px`;
        el.style.width = `${rt.width}px`;
        el.style.height = `${rt.height}px`;
        el.style.borderRadius = `${rt.radius}px`;
      }
    }
    layoutReader();

    /* inset() of rect r inside the panel: p = 0 is r, p = 1 the whole panel */
    function clipAt(r: Rect, p: number) {
      const top = lerp(r.top - rt.top, 0, p);
      const left = lerp(r.left - rt.left, 0, p);
      const right = lerp(rt.left + rt.width - (r.left + r.width), 0, p);
      const bottom = lerp(rt.top + rt.height - (r.top + r.height), 0, p);
      const radius = lerp(CARD_RADIUS, rt.radius, clamp01(p));
      return `inset(${top}px ${right}px ${bottom}px ${left}px round ${radius}px)`;
    }

    /* ── reading progress and type size ────────────────────────────────── */
    function updateProgress() {
      const max = scroller.scrollHeight - scroller.clientHeight;
      const p = max > 0 ? clamp01(scroller.scrollTop / max) : 0;
      progressFill.style.transform = `scaleX(${p})`;
      progressText.textContent = `${Math.round(p * 100)}%`;
    }
    listen(scroller, "scroll", updateProgress, { passive: true });

    let sizeIdx = START_SIZE;
    let holdRaf = 0;
    function setSize(idx: number) {
      sizeIdx = Math.max(0, Math.min(SIZES.length - 1, idx));
      const max = scroller.scrollHeight - scroller.clientHeight;
      const ratio = max > 0 ? scroller.scrollTop / max : 0;
      prose.style.setProperty("--prc-size", `${SIZES[sizeIdx]}px`);
      /* hold the reading position while the type size eases */
      const t0 = performance.now();
      cancelAnimationFrame(holdRaf);
      const hold = () => {
        scroller.scrollTop = ratio * (scroller.scrollHeight - scroller.clientHeight);
        if (performance.now() - t0 < 320) holdRaf = requestAnimationFrame(hold);
        else updateProgress();
      };
      holdRaf = requestAnimationFrame(hold);
      fontBtns[0].disabled = sizeIdx === 0;
      fontBtns[1].disabled = sizeIdx === SIZES.length - 1;
    }
    cleanups.push(() => cancelAnimationFrame(holdRaf));
    fontBtns.forEach((b) => listen(b, "click", () => setSize(sizeIdx + Number(b.dataset.font))));

    /* open the reader on the same passage the card is scrolled to */
    function syncReaderToCard() {
      const contentH = excerpt.scrollHeight - EXCERPT_TOP - EXCERPT_PAD_BOTTOM;
      const readLine = excerpt.scrollTop + 2 * EXCERPT_LINE; // the second visible line
      const f = clamp01(readLine / contentH);
      const start = exStart.offsetTop;
      const end = exEnd.offsetTop + exEnd.offsetHeight;
      scroller.scrollTop = Math.max(0, lerp(start, end, f) - rt.height * 0.3);
      updateProgress();
    }

    /* the card's face, cloned into the panel so the morph starts from exactly what was on screen */
    function makePreview(r: Rect) {
      const preview = cardContent.cloneNode(true) as HTMLElement;
      preview.className = "prc__preview";
      preview.setAttribute("aria-hidden", "true");
      preview.querySelectorAll(".prc__pblur").forEach((n) => n.remove()); // no backdrop filters mid-morph
      preview.querySelectorAll("[tabindex]").forEach((n) => n.removeAttribute("tabindex"));
      preview.style.left = `${r.left - rt.left}px`;
      preview.style.top = `${r.top - rt.top}px`;
      previewHost.appendChild(preview);
      (preview.querySelector(".prc__excerpt") as HTMLElement).scrollTop = excerpt.scrollTop;
      return preview;
    }

    /* ── open and close ────────────────────────────────────────────────
       Everything that moves is clip-path, opacity or transform, which
       Motion hands to the compositor, so the morph holds its frame rate
       even while the main thread is busy. Open and close can interrupt
       each other mid-flight.                                         */
    let state: State = "closed";
    let token = 0;
    let cardRect: Rect = { left: 0, top: 0, width: 0, height: 0 };
    let preview: HTMLElement | null = null;
    const running = new Set<AnimationPlaybackControlsWithThen>();
    const run = (anim: AnimationPlaybackControlsWithThen) => {
      running.add(anim);
      anim.then(
        () => running.delete(anim),
        () => running.delete(anim),
      );
      return anim;
    };
    const nextFrame = () => new Promise<void>((r) => requestAnimationFrame(() => requestAnimationFrame(() => r())));

    const ensurePreview = (opacity: number) => {
      if (!preview) {
        preview = makePreview(cardRect);
        preview.style.opacity = String(opacity);
      }
      return preview;
    };
    const dropPreview = () => {
      preview?.remove();
      preview = null;
    };
    const pblurs = [...inner.querySelectorAll<HTMLElement>(".prc__pblur")];

    async function openReader() {
      if (state === "open" || state === "opening") return;
      const t = ++token;
      const fromClosed = state === "closed";
      const still = reduce();
      state = "opening";

      if (fromClosed) {
        ensureReaderGlass();
        layoutReader();
        cardRect = local(card.getBoundingClientRect());
        reader.classList.add("is-morphing");
        reader.style.clipPath = clipAt(cardRect, 0);
        solid.style.opacity = "1";
        inner.style.opacity = "0";
        shadow.style.opacity = "0";
        scrim.style.opacity = "0";
        ensurePreview(1);
        reader.dataset.state = "open";
        reader.inert = false;
        scrim.hidden = false;
        syncReaderToCard();
        card.style.visibility = "hidden";
        stage.inert = true;
        root!.dataset.open = "";
      } else {
        /* reversing a close: it is already a solid, clipped sheet */
        reader.classList.add("is-morphing");
        ensurePreview(1);
      }

      if (still) {
        reader.style.clipPath = "";
        inner.style.opacity = "1";
        scrim.style.opacity = "1";
      } else {
        run(animate(scrim, { opacity: 1 }, { duration: 0.3, ease: "easeOut" }));
        run(animate(preview!, { opacity: 0 }, { duration: 0.2, ease: "easeOut" }));
        run(
          animate(
            inner,
            { opacity: 1, transform: ["translateY(14px)", "translateY(0px)"] },
            { duration: 0.42, delay: fromClosed ? 0.1 : 0, ease: outQuint },
          ),
        );
        await run(animate(reader, { clipPath: clipAt(cardRect, 1) }, morphOpen));
        if (t !== token) return;
      }

      dropPreview();
      /* still now: switch the glass on under the opaque sheet, let it paint, then reveal it */
      reader.classList.remove("is-morphing");
      if (!still) {
        pblurs.forEach((p) => {
          p.style.opacity = "0";
          p.style.visibility = "hidden";
        });
        await nextFrame();
        if (t !== token) return;
        reader.style.clipPath = "";
        /* the glass first; the blur bands sample what is behind them, so they join once the sheet has gone */
        run(animate(shadow, { opacity: 1 }, { duration: 0.25 }));
        await run(animate(solid, { opacity: 0 }, { duration: 0.26, ease: "easeOut" }));
        if (t !== token) return;
        pblurs.forEach((p) => (p.style.visibility = "visible"));
        run(animate(pblurs, { opacity: 1 }, { duration: 0.22, ease: "easeOut" }));
      } else {
        reader.style.clipPath = "";
        solid.style.opacity = "0";
        shadow.style.opacity = "1";
      }
      /* the lines the card was showing flash once, so the eye finds its place */
      resumeMark.classList.remove("is-flash");
      void resumeMark.offsetWidth;
      resumeMark.classList.add("is-flash");
      state = "open";
      closeBtn.focus({ preventScroll: true });
      onOpenChangeRef.current?.(true);
    }

    async function closeReader() {
      if (state === "closed" || state === "closing") return;
      const t = ++token;
      const fromOpen = state === "open";
      const still = reduce();
      state = "closing";
      if (fromOpen) onOpenChangeRef.current?.(false);

      if (!still) {
        run(animate(inner, { opacity: 0, transform: "translateY(8px)" }, { duration: 0.16, ease: "easeIn" }));
        run(animate(shadow, { opacity: 0 }, { duration: 0.16 }));
        if (fromOpen) {
          /* cover the glass before it is switched off */
          await run(animate(solid, { opacity: 1 }, { duration: 0.12, ease: "easeOut" }));
          if (t !== token) return;
        }
      }
      solid.style.opacity = "1";
      reader.classList.add("is-morphing");
      pblurs.forEach((p) => {
        p.style.opacity = "";
        p.style.visibility = "";
      });
      ensurePreview(0);

      if (!still) {
        run(animate(scrim, { opacity: 0 }, { duration: 0.32, ease: "easeOut" }));
        run(animate(preview!, { opacity: 1 }, { duration: 0.2, delay: fromOpen ? 0.14 : 0, ease: "easeOut" }));
        await run(animate(reader, { clipPath: clipAt(cardRect, 0) }, morphClose));
        if (t !== token) return;
      }

      reader.dataset.state = "closed";
      reader.inert = true;
      scrim.hidden = true;
      dropPreview();
      reader.classList.remove("is-morphing");
      requestAnimationFrame(() => {
        if (state === "closed") reader.style.clipPath = "";
      });
      card.style.visibility = "";
      stage.inert = false;
      delete root!.dataset.open;
      state = "closed";
      openPill.focus({ preventScroll: true });
    }

    liquidPress(openPill);
    liquidPress(closeBtn);
    listen(openPill, "click", () => void openReader());
    listen(closeBtn, "click", () => void closeReader());
    listen(scrim, "click", () => void closeReader());

    listen(root, "keydown", (e) => {
      if (state === "closed") return;
      if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        void closeReader();
        return;
      }
      if (e.key === "Tab" && state === "open") {
        /* keep focus inside the dialog */
        const items: HTMLElement[] = [scroller, closeBtn, ...fontBtns.filter((b) => !b.disabled)];
        const i = items.indexOf(document.activeElement as HTMLElement);
        e.preventDefault();
        items[(i + (e.shiftKey ? -1 : 1) + items.length) % items.length].focus();
      }
    });

    /* the scene can change size under it (a shrinking stage, a rotating phone): re-lay the panel when nothing moves */
    let resizeRaf = 0;
    const ro = new ResizeObserver(() => {
      cancelAnimationFrame(resizeRaf);
      resizeRaf = requestAnimationFrame(() => {
        if (state === "opening" || state === "closing") return;
        layoutReader();
      });
    });
    ro.observe(root);

    return () => {
      disposed = true;
      token++;
      ro.disconnect();
      cancelAnimationFrame(resizeRaf);
      running.forEach((a) => a.stop());
      running.clear();
      cleanups.forEach((fn) => fn());
      glasses.forEach((g) => g.destroy());
      dropPreview();
      /* leave the markup as React rendered it, so a remount starts clean */
      reader.dataset.state = "closed";
      reader.inert = true;
      reader.classList.remove("is-morphing");
      reader.style.clipPath = "";
      scrim.hidden = true;
      card.style.visibility = "";
      stage.inert = false;
      delete root.dataset.open;
    };
  }, []);

  return (
    <div ref={rootRef} className="prc" data-theme={theme} data-fill={fill || undefined}>
      {/* ambient light for the glass to bend */}
      <div className="prc__ambient" aria-hidden="true">
        <span className="prc__orb prc__orb--a" />
        <span className="prc__orb prc__orb--b" />
        <span className="prc__orb prc__orb--c" />
      </div>

      <div className="prc__stage">
        <article className="prc__card" aria-label="The Keeper of Wren Point">
          <div className="prc__content">
            <div className="prc__excerpt" tabIndex={0} aria-label="Excerpt preview, scrollable">
              <p className="prc__wrap">
                Mara climbed the hill with a basket of bread on one arm and a coil of rope on the other. She
                had promised her grandfather she would check the lamp before noon, and she meant to keep that
                promise, though every step up the wet path made her boots slide. At the top she stopped to
                breathe and looked back at the village, small and crooked below her, smoke curling from every
                chimney.
              </p>
              <p className="prc__wrap">
                Inside, the tower smelled of salt and lamp oil. She began to climb the spiral stairs, counting
                them the way she always did. Somewhere above her a shutter banged in the wind, and she thought
                of the children in the village who would
              </p>
              <div className="prc__lines">
                {CARD_LINES.map((line) => (
                  <span key={line}>{line}</span>
