  if (start < 0) return flags[0] === want ? [Array.from({ length: count + 1 }, (_, i) => i % count)] : [];
  let run: number[] | null = null;
  for (let step = 0; step < count; step++) {
    const i = (start + step) % count;
    if (flags[i] === want) {
      if (!run) run = [i];
      run.push((i + 1) % count);
    } else if (run) {
