    crease.push(pathOf(run.map((i) => top[i])));
    if (height > 0) outline.push(pathOf(run.map((i) => bottom[i])));
  }
  if (height > 0) {
    for (let i = 0; i < count; i++) if (facing[(i + count - 1) % count] !== facing[i]) outline.push(pathOf([top[i], bottom[i]]));
