}
const slabOf = (plan: Plan, z: number, height: number, projection: Projection, steps = 8, bevel = 0) =>
  extrude(roundedPlan(plan, steps), z, height, projection, bevel);
const circleRing = (cx: number, cy: number, radius: number, steps = 40): Vec2[] =>
  Array.from({ length: steps }, (_, step) => {
    const angle = (step / steps) * Math.PI * 2;
    return [cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)];
  });
const onTop = (points: Vec2[], z: number, projection: Projection, closed = false) => pathOf(points.map(([x, y]) => iso([x, y, z], projection)), closed);
const planOutline = (plan: Plan, z: number, projection: Projection, steps = 8) => onTop(roundedPlan(plan, steps), z, projection, true);
const ring = (cx: number, cy: number, radius: number, z: number, projection: Projection, steps = 40) =>
  onTop(circleRing(cx, cy, radius, steps), z, projection, true);
function axisVector(projection: Projection, [dx, dy, dz]: Vec3): Vec2 {
  const origin = iso([0, 0, 0], projection);
  const moved = iso([dx, dy, dz], projection);
  return [moved[0] - origin[0], moved[1] - origin[1]];
}
const fine = (value: number) => Math.round(value * 100) / 100;
function translateAlong(projection: Projection, by: Vec3) {
  const [x, y] = axisVector(projection, by);
  return `translate(${fine(x)} ${fine(y)})`;
}
const thousandth = (value: number) => Math.round(value * 1000) / 1000;
function axesAt(at: Vec2, z: number, projection: Projection) {
  const origin = iso([at[0], at[1], z], projection);
  const along = (point: Vec3): Vec2 => {
    const [px, py] = iso(point, projection);
    return [px - origin[0], py - origin[1]];
  };
