    if (d) parts.push(`<path class="iso-shade" data-shade="${shade}" d="${d}"/>`);
  });
  parts.push(`<path class="iso-top" d="${paths.top}"/>`);
  if (paths.crease) parts.push(`<path class="iso-line iso-crease" data-tone="${crease}" d="${paths.crease}"/>`);
  if (paths.bevel) parts.push(`<path class="iso-line iso-bevel" data-tone="${crease}" d="${paths.bevel}"/>`);
