const lineSvg = (d: string, tone: string) => (d ? `<path class="iso-line" data-tone="${tone}" d="${d}"/>` : "");

/* ------------------------------------------------------------------------ */
/* sound                                                                     */
/* ------------------------------------------------------------------------ */

type ToneOpts = { type?: OscillatorType; f0?: number; f1?: number; gain?: number; attack?: number; filter?: number };
type NoiseOpts = { type?: BiquadFilterType; freq?: number; q?: number; gain?: number; attack?: number };
const HEAVY = new Set([" ", "Enter", "NumpadEnter", "Backspace", "Shift", "ShiftRight", "Tab", "CapsLock", "NumpadAdd", "Numpad0"]);

/* everything synthesised: no files. The context is made on the first gesture, as browsers require */
function makeSound(initiallyMuted: boolean) {
  let ctx: AudioContext | null = null;
  let master: GainNode | null = null;
  let noiseBuf: AudioBuffer | null = null;
  let muted = initiallyMuted;
  const ensure = () => {
    if (ctx) return ctx;
    const AC = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!AC) return null;
    ctx = new AC();
    master = ctx.createGain();
    master.gain.value = 0.8;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -16;
    comp.ratio.value = 4;
    master.connect(comp).connect(ctx.destination);
    noiseBuf = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
    const d = noiseBuf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    return ctx;
  };
  const ready = () => !muted && ensure() !== null && ctx!.state === "running";
  const jitter = (v: number, amount: number) => v * (1 - amount + Math.random() * amount * 2);
  /* a filtered noise burst with a fast attack and an exponential decay */
  const noise = (t: number, dur: number, { type = "bandpass", freq = 3000, q = 1, gain = 0.2, attack = 0.001 }: NoiseOpts = {}) => {
    const c = ctx!;
    const src = c.createBufferSource();
    src.buffer = noiseBuf;
    const f = c.createBiquadFilter();
    f.type = type;
    f.frequency.value = freq;
    f.Q.value = q;
    const g = c.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f).connect(g).connect(master!);
    src.start(t, Math.random() * 0.8, dur + 0.05);
  };
  /* an oscillator gliding from f0 to f1, enveloped the same way */
  const tone = (t: number, dur: number, { type = "sine", f0 = 200, f1 = f0, gain = 0.2, attack = 0.002, filter = 0 }: ToneOpts = {}) => {
    const c = ctx!;
    const o = c.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(f0, t);
    if (f1 !== f0) o.frequency.exponentialRampToValueAtTime(f1, t + dur);
    const g = c.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    let node: AudioNode = o;
    if (filter) {
      const lp = c.createBiquadFilter();
      lp.type = "lowpass";
      lp.frequency.value = filter;
      node = o.connect(lp);
    }
    node.connect(g).connect(master!);
    o.start(t);
    o.stop(t + dur + 0.05);
  };
  return {
    unlock() {
      if (muted || !ensure()) return;
      if (ctx!.state === "suspended") void ctx!.resume();
    },
    setMuted(next: boolean) {
      muted = next;
      if (!next) this.unlock();
    },
    /* a key going down (bottom-out click and case thock), then its lighter return click */
    key(code: string) {
      if (!ready()) return;
      const t = ctx!.currentTime + 0.002;
      const heavy = HEAVY.has(code);
      const v = jitter(1, 0.15);
      noise(t, heavy ? 0.03 : 0.02, { freq: jitter(heavy ? 2300 : 3500, 0.12), q: 1.3, gain: (heavy ? 0.42 : 0.34) * v });
      tone(t, heavy ? 0.1 : 0.055, { f0: jitter(heavy ? 150 : 230, 0.08), f1: heavy ? 70 : 115, gain: (heavy ? 0.42 : 0.2) * v });
      if (heavy) noise(t + 0.012, 0.05, { type: "highpass", freq: 5200, q: 0.7, gain: 0.05 * v });
      noise(t + jitter(0.085, 0.15), 0.014, { freq: jitter(4300, 0.1), q: 1.6, gain: 0.12 * v });
    },
    /* relay, degauss hum, static as the picture blooms, a fading flyback whine */
    powerOn() {
      if (!ready()) return;
      const c = ctx!;
      const t = c.currentTime + 0.01;
      noise(t, 0.012, { type: "highpass", freq: 1800, gain: 0.45 });
      tone(t, 0.09, { f0: 95, f1: 50, gain: 0.32 });
      const hum = c.createOscillator();
      const hum2 = c.createOscillator();
      const lp = c.createBiquadFilter();
      const g = c.createGain();
      hum.type = "sawtooth";
      hum.frequency.value = 60;
      hum2.type = "sine";
      hum2.frequency.value = 120;
      lp.type = "lowpass";
      lp.frequency.setValueAtTime(380, t);
      lp.frequency.exponentialRampToValueAtTime(140, t + 1.2);
      g.gain.setValueAtTime(0.0001, t + 0.04);
      g.gain.exponentialRampToValueAtTime(0.26, t + 0.14);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 1.25);
      hum.connect(lp);
      hum2.connect(lp);
      lp.connect(g).connect(master!);
      hum.start(t);
      hum2.start(t);
      hum.stop(t + 1.3);
      hum2.stop(t + 1.3);
      for (let i = 0; i < 9; i++) noise(t + 0.12 + Math.random() * 0.4, 0.02 + Math.random() * 0.03, { type: "highpass", freq: 2800, gain: 0.04 + Math.random() * 0.08 });
      tone(t + 0.2, 2.2, { f0: 15734, gain: 0.008, attack: 0.4 });
    },
    /* relay, then a falling zap as the picture collapses to a line and a dot */
    powerOff() {
      if (!ready()) return;
      const t = ctx!.currentTime + 0.005;
      noise(t, 0.012, { type: "highpass", freq: 1800, gain: 0.4 });
      tone(t, 0.26, { type: "triangle", f0: 900, f1: 45, gain: 0.16, attack: 0.004 });
      noise(t, 0.32, { freq: 1300, q: 0.8, gain: 0.1, attack: 0.004 });
      tone(t + 0.02, 0.16, { f0: 75, f1: 40, gain: 0.22 });
    },
    close() {
      void ctx?.close();
      ctx = null;
    },
  };
}

