export type DeskEngine = {
  /** The system assembles itself again — the figure does this on every theme change. */
  replayIntro: () => void;
  setMuted: (muted: boolean) => void;
  destroy: () => void;
};

const PHRASES = ["anatomy isometric", "windows 98 themes", "how does a crt work"];
const SHIFTED: Record<string, string> = { "~": "`", "!": "1", "@": "2", "#": "3", $: "4", "%": "5", "^": "6", "&": "7", "*": "8", "(": "9", ")": "0", _: "-", "+": "=", "{": "[", "}": "]", "|": "\\", ":": ";", '"': "'", "<": ",", ">": ".", "?": "/" };
const DOWN = 1.6;

type Vec = Vec3;
const add = (a: Vec, b: Vec): Vec => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const mul = (a: Vec, s: number): Vec => [a[0] * s, a[1] * s, a[2] * s];
const sub = (a: Vec, b: Vec): Vec => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const unit = (a: Vec): Vec => {
  const l = Math.hypot(a[0], a[1], a[2]) || 1;
  return [a[0] / l, a[1] / l, a[2] / l];
};
const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const ease = (t: number) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
const easeInOut = (t: number) => {
  t = clamp(t, 0, 1);
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
};

export function mountDeskComputer({
  stage,
  svg,
  readout,
  status,
  muted: initiallyMuted,
}: {
  /** The focusable element the figure sits in: it takes the keys and the pointer. */
  stage: HTMLElement;
  svg: SVGSVGElement;
  /** Where a running "on · 12 chars · key a" line is written, if you want one. */
  readout?: HTMLElement | null;
  /** A polite live region for what just happened. */
  status: HTMLElement;
  muted: boolean;
}): DeskEngine {
  const P = D.P;
  const KEYS = D.keys;
  const ac = new AbortController();
  const signal = ac.signal;
  const timers = new Set<number>();
  const later = (fn: () => void, ms: number) => {
    const t = window.setTimeout(() => {
      timers.delete(t);
      fn();
    }, ms);
    timers.add(t);
    return t;
  };
  const cancel = (t: number) => {
    clearTimeout(t);
    timers.delete(t);
  };

  const need = <T extends Element>(el: T | null, what: string): T => {
    if (!el) throw new Error(`DeskComputer: the figure has no ${what}`);
    return el;
  };
  const $ = <T extends Element = SVGGraphicsElement>(part: string) => need(svg.querySelector<T>(`[data-part="${part}"]`), part);
  const keyEls = KEYS.map((_, i) => need(svg.querySelector<SVGGElement>(`[data-key="${i}"]`), `key ${i}`));
  const query = $<SVGTextElement>("query");
  const caret = $<SVGGraphicsElement>("caret");
  const crt = $("crt");
  const beam = $("beam");
  const dot = $("dot");
  const glass = need(svg.querySelector<SVGGraphicsElement>(".pc-glass"), "glass");
  const monLed = $("mon-led");
  const hddLed = $("hdd-led");
  const cdLed = $("cd-led");
  const kbLeds = [0, 1, 2].map((i) => $("kb-led" + i));
  const mouseEl = $("mouse");
  const mouseHalo = $("mouse-halo");
  const mousePress = $("mouse-press");
  const cablePaths = Array.from($("mouse-cable").querySelectorAll<SVGPathElement>("path"));
  const cursorEl = $("cursor");
  const arrowEl = $("arrow");
  const ibeamEl = $("ibeam");
  const autoplayEl = $("autoplay");
  const trayEl = $("cd-tray");
  const flyEl = $("fly");
  const caseDisc = $("case-disc");
  const still = matchMedia("(prefers-reduced-motion: reduce)");
  const down = axisVector(P, [0, 0, -1]);
  const follow = (v: number, to: number, dt: number, tau: number) => (still.matches ? to : v + (to - v) * (1 - Math.exp(-dt / tau)));
  const pt = (p: Vec) => {
    const s = iso(p, P);
    return s[0].toFixed(2) + " " + s[1].toFixed(2);
  };

  /* ── state ── */
  const keyState = KEYS.map(() => ({ at: 0, held: 0 }));
  const active = new Set<number>();
  let line = "";
  let lastKey = "";
  let power = 0;
  let powerClock = 9;
  let searches = 0;
  let hdd = 0;
  let caps = false;
  let frame = 0;
  let previous = 0;
  let visible = false;
  let touring = false;
  let idleTimer = 0;
  let booted = false;
  let alive = true;
  let tour = { phrase: 0, step: "aim", index: 0, wait: 0.4 };
  const waiters: { test: () => boolean; done: () => void }[] = [];
  /* the mouse: its centre's offset on the pad (world units), its target, and what the cursor is over */
  const mouse = { x: 0, y: 0, tx: 0, ty: 0, tau: 0.32, press: 0, dragging: false, drawn: "" };
  let cursorOver = "";
  /* the CD: where the disc is, the tray's travel (0 shut, 1 out), the disc's flight, AutoPlay */
  const cd = {
    at: "case" as "case" | "drive",
    tray: 0,
    trayTo: 0,
    flight: null as null | { t: number; toDrive: boolean },
    spin: 0,
    busy: false,
    read: 0,
    autoplay: 0,
    autoplayTo: 0,
    autoplayTimer: 0,
    drawnTray: -1,
  };
  const until = (test: () => boolean) =>
    new Promise<void>((done) => {
      waiters.push({ test, done });
      run();
    });
  const sleep = (ms: number) => new Promise<void>((done) => later(done, still.matches ? 0 : ms));

  const sfx = makeSound(initiallyMuted);
  /* true while handling the visitor's own input, so the idle tour stays silent */
  let byUser = false;
  const asUser = (fn: () => void) => {
    byUser = true;
    try {
      fn();
    } finally {
      byUser = false;
    }
  };
  for (const type of ["pointerdown", "keydown"] as const) stage.addEventListener(type, () => sfx.unlock(), { capture: true, signal });

  /* ── keyboard and screen ── */
  const indexOf = (code: string) => KEYS.indexOf(code);
  let repeating = false;
  function press(code: string, hold = 0.09) {
    const i = indexOf(code);
    if (i < 0) return;
    keyState[i].held = hold;
    active.add(i);
    if (byUser && !repeating && code !== "Shift" && code !== "ShiftRight") sfx.key(code);
    else if (byUser && !repeating && keyState[i].at === 0) sfx.key(code);
    run();
  }
  function type(char: string) {
    if (!power) return;
    const lower = char.toLowerCase();
    const code = SHIFTED[char] || lower;
    if (indexOf(code) < 0) return;
    if (SHIFTED[char] || char !== lower) press("Shift", 0.14);
    press(code);
    lastKey = char === " " ? "space" : char;
    if (line.length < 60) line += char;
    write();
  }
  function erase() {
    if (!power) return;
    press("Backspace");
    lastKey = "backspace";
    line = line.slice(0, -1);
    write();
  }
  function enter() {
    if (!power) return;
    press("Enter");
    lastKey = "return";
    if (line.trim()) {
      searches++;
      hdd = 0.9;
      status.textContent = "Searching for " + line + ".";
    }
    line = "";
    write();
    run();
  }
  function write() {
    query.textContent = line;
    let shown = line;
    while (shown.length && query.getComputedTextLength() > D.queryMax) {
      shown = shown.slice(1);
      query.textContent = shown;
    }
    caret.setAttribute("x", String(D.queryX + (shown ? query.getComputedTextLength() + 0.3 : 0)));
    const parts = power ? ["on", line.length + " chars"] : ["off"];
    if (power && searches) parts.push(searches + (searches === 1 ? " search" : " searches"));
    if (cd.at === "drive") parts.push("CD in drive");
    if (power && lastKey) parts.push("key " + lastKey);
    const text = parts.join(" · ");
    if (readout && readout.textContent !== text) readout.textContent = text;
  }
  function setPower(next: number) {
    if (next === power) return;
    power = next;
    if (byUser) {
      if (power) sfx.powerOn();
      else sfx.powerOff();
    }
    powerClock = still.matches ? 9 : 0;
    monLed.style.opacity = power ? "" : "0.15";
    status.textContent = power ? "Screen on." : "Screen off.";
    write();
    run();
  }
  function crtFrame() {
    const t = powerClock;
    let sx = 1;
    let sy = 1;
    let beamAt = 0;
    let dotAt = 0;
    if (power) {
      if (t < 0.14) {
        sx = ease(t / 0.14);
        sy = 0.012;
        beamAt = 1;
      } else if (t < 0.36) {
        sy = 0.012 + 0.988 * ease((t - 0.14) / 0.22);
        beamAt = 1 - ease((t - 0.14) / 0.22);
      }
    } else if (t < 0.1) {
      sy = 1 - 0.988 * ease(t / 0.1);
      beamAt = ease(t / 0.1);
    } else if (t < 0.26) {
      sy = 0.012;
      sx = 1 - ease((t - 0.1) / 0.16);
      beamAt = 1;
    } else {
      sx = 0;
      sy = 0;
      dotAt = Math.max(0, 1 - (t - 0.26) / 0.5);
    }
    crt.setAttribute("transform", `translate(0 ${-D.crtMid}) scale(${Math.max(sx, 0.0001).toFixed(3)} ${Math.max(sy, 0.0001).toFixed(3)}) translate(0 ${D.crtMid})`);
    beam.setAttribute("transform", `translate(0 ${-D.crtMid}) scale(${Math.max(sx, 0.001).toFixed(3)} 1) translate(0 ${D.crtMid})`);
    beam.style.opacity = beamAt.toFixed(2);
    dot.style.opacity = dotAt.toFixed(2);
    glass.style.fill = power || t < 0.26 ? "" : "var(--pc-glass-off)";
    return t > 0.8;
  }

  /* ── the mouse, its cable and the cursor ── */
  const M = D.mouse;
  const ax = axisVector(P, [1, 0, 0]);
  const ay = axisVector(P, [0, 1, 0]);
  const det = ax[0] * ay[1] - ay[0] * ax[1];
  const toWorld = (dx: number, dy: number): Vec2 => [(dx * ay[1] - ay[0] * dy) / det, (ax[0] * dy - dx * ax[1]) / det];
  const svgPoint = (event: PointerEvent) => {
    const p = svg.createSVGPoint();
    p.x = event.clientX;
    p.y = event.clientY;
    const m = svg.getScreenCTM();
    return m ? p.matrixTransform(m.inverse()) : p;
  };
  function aimMouse(x: number, y: number, tau = 0.32) {
    mouse.tx = clamp(x, M.range.x[0], M.range.x[1]);
    mouse.ty = clamp(y, M.range.y[0], M.range.y[1]);
    mouse.tau = tau;
    run();
  }
  /* the cursor on the CRT moves with the mouse: forward (−x) is up, right (−y) is right */
  const cursorAt = (x: number, y: number): Vec2 => [clamp(D.cursor.u - y * 1.55, D.window.u0, D.window.u1), clamp(D.cursor.z - x * 1.4, D.window.z0, D.window.z1)];
  const mouseFor = (u: number, z: number): Vec2 => [(D.cursor.z - z) / 1.4, (D.cursor.u - u) / 1.55];
  function overOf(u: number, z: number) {
    const S = D.search;
    if (cd.autoplay > 0.5 && u > 6 && u < 18 && z > 52.4 && z < 57) return "open";
    if (u > S.u0 && u < S.u1 && z > S.z0 && z < S.z1) return "search";
    return "";
  }
  function drawMouse() {
    const shift = translateAlong(P, [mouse.x, mouse.y, 0]);
    mouseEl.setAttribute("transform", shift);
    mouseHalo.setAttribute("transform", shift);
    mousePress.setAttribute("transform", mouse.press > 0 ? translateAlong(P, [0, 0, -0.45 * Math.sin(Math.PI * clamp(mouse.press / 0.16, 0, 1))]) : "");
    /* the cable: from the strain relief over the pad, down its edge, into the static run on the floor */
    const tip: Vec = [M.tip[0] + mouse.x, M.tip[1] + mouse.y, M.tip[2]];
    const edge: Vec = [M.edge[0], clamp(lerp(M.edge[1], tip[1], 0.55), M.padY[0], M.padY[1]), M.edge[2]];
    const drop = unit([M.anchor[0] - edge[0], M.anchor[1] - edge[1], 0]);
    const reach = Math.max(4, 0.42 * Math.hypot(edge[0] - tip[0], edge[1] - tip[1]));
    const d =
      "M" + pt(tip) + "C" + pt(add(tip, mul(M.dir, reach))) + " " + pt(sub(edge, mul(drop, 4))) + " " + pt(edge) +
      "C" + pt(add(edge, mul(drop, 2.4))) + " " + pt(sub(M.anchor, mul(M.tangent, 2.4))) + " " + pt(M.anchor);
    if (d !== mouse.drawn) {
      mouse.drawn = d;
      const w = 2 * M.r * D.scale;
      cablePaths.forEach((path, i) => {
        path.setAttribute("d", d);
        path.style.strokeWidth = [w + 0.95, w - 0.95, w * 0.28][i].toFixed(2);
      });
      cablePaths[2]?.setAttribute("transform", `translate(${(-0.16 * w).toFixed(2)} ${(-0.22 * w).toFixed(2)})`);
    }
    const [u, z] = cursorAt(mouse.x, mouse.y);
    cursorEl.setAttribute("transform", `translate(${u.toFixed(2)} ${(-z).toFixed(2)})`);
    const over = overOf(u, z);
    if (over !== cursorOver) {
      cursorOver = over;
      arrowEl.style.display = over === "search" ? "none" : "";
      ibeamEl.style.display = over === "search" ? "" : "none";
    }
  }
  function mouseClick() {
    mouse.press = 0.16;
    run();
    if (!power) return;
    if (cursorOver === "search") {
      status.textContent = "Search box focused.";
      caret.style.animation = "none";
      void caret.getBBox();
      caret.style.animation = "";
    }
    if (cursorOver === "open") {
      cd.autoplayTo = 0;
      status.textContent = "AutoPlay closed.";
    }
  }

  /* ── the CD-ROM: tray, disc and AutoPlay ── */
  const T = D.tray;
  const discAtTray = (ext: number): Vec => [T.front + ext - T.plate.t - 21.5, (T.body.y0 + T.body.y1) / 2, T.body.z + T.body.h + 0.05];
  const frontPlane = (x: number) => sideMatrix([x, 0], 0, P, "right");
  const faceRect = (u0: number, z0: number, u1: number, z1: number, r: number) =>
    pathOf(roundedPlan({ x: u0, y: z0, w: u1 - u0, d: z1 - z0, r }, 3).map(([u, z]): Vec2 => [u, -z]), true);
  function discMarkup(c: Vec, spin: number) {
    const R = D.disc.r;
    const [x, y, z] = c;
    const circle = (r: number, n: number) => planOutline({ x: x - r, y: y - r, w: 2 * r, d: 2 * r, r }, z, P, n);
    const sheen: Vec[] = [[x, y, z]];
    for (let i = 0; i <= 12; i++) {
      const a = spin - 0.3 + (i / 12) * 0.9;
      sheen.push([x + 18.4 * Math.cos(a), y + 18.4 * Math.sin(a), z]);
    }
    return (
      `<path class="pc-disc" fill-rule="evenodd" d="${circle(R, 24)}${circle(2, 10)}"/>` +
      `<path class="pc-disc-sheen" d="${pathOf(sheen.map((p) => iso(p, P)), true)}"/>` +
      lineSvg(ring(x, y, R, z, P, 96), "hi") +
      lineSvg(ring(x, y, 7.6, z, P, 48), "mid") +
      lineSvg(ring(x, y, 4.4, z, P, 32), "lo") +
      lineSvg(ring(x, y, 2, z, P, 20), "hi")
    );
  }
  function plateMarkup(ext: number) {
    const x = T.front + ext;
    const plate = { x: x - T.plate.t, y: T.y0, w: T.plate.t, d: T.y1 - T.y0, r: 0.4 };
    const u0 = -T.y1;
    const u1 = -T.y0;
    const reading = cd.read > 0 && Math.sin(performance.now() / 45) > 0;
    const face =
      `<g transform="${frontPlane(x)}">` +
      `<path class="iso-line" data-tone="lo" d="${faceRect(u0 + 3, 132.2, u1 - 12, 136.6, 0.6)}"/>` +
      `<path class="iso-line" data-tone="hi" d="${faceRect(u1 - 9, 130.4, u1 - 3, 132.4, 0.6)}"/>` +
      `<circle class="pc-led-cd"${reading ? " data-on" : ""} cx="${u0 + 4}" cy="-130.6" r="0.6"/></g>`;
    return solidSvg(slabOf(plate, T.plate.z0, T.plate.z1 - T.plate.z0, P, 2, 0.3)) + face;
  }
  function trayMarkup() {
    const ext = cd.tray * T.travel;
    if (ext < 0.02) return "";
    const out: string[] = [];
    /* the bay behind the tray is a dark opening while the tray is out */
    out.push(`<g transform="${frontPlane(T.front)}"><path class="pc-slot" d="${faceRect(T.bay.u0, T.bay.z0, T.bay.u1, T.bay.z1, 0.8)}"/></g>`);
    const bodyW = ext - T.plate.t;
    if (bodyW > 0.2) {
      const body = { x: T.front, y: T.body.y0, w: bodyW, d: T.body.y1 - T.body.y0, r: 0.5 };
      const top = T.body.z + T.body.h;
      out.push(solidSvg(slabOf(body, T.body.z, T.body.h, P, 2, 0.3)));
      const c = discAtTray(ext);
      const well = planOutline({ x: c[0] - 20.2, y: c[1] - 20.2, w: 40.4, d: 40.4, r: 20.2 }, top, P, 24);
      out.push(`<clipPath id="${clipId}"><path d="${planOutline(body, top, P, 2)}"/></clipPath><g clip-path="url(#${clipId})">`);
      out.push(`<path class="iso-line" data-tone="faint" d="${well}"/>`);
      if (cd.at === "drive" && !cd.flight) out.push(discMarkup(c, cd.spin));
      out.push("</g>");
    }
    out.push(plateMarkup(ext));
    return out.join("");
  }
  const clipId = `pdesk-tray-${Math.random().toString(36).slice(2, 8)}`;
  function flightPoint(t: number, toDrive: boolean): Vec {
    const home = D.disc.home;
    const end = discAtTray(T.travel);
    const [a, b] = toDrive ? [home, end] : [end, home];
    const c1 = add(a, [0, 0, toDrive ? 85 : 70]);
    const c2 = add(b, [0, 0, toDrive ? 70 : 85]);
    const u = 1 - t;
    return [0, 1, 2].map((i) => u * u * u * a[i] + 3 * u * u * t * c1[i] + 3 * u * t * t * c2[i] + t * t * t * b[i]) as Vec;
  }
  function drawCd(now: number) {
    if (cd.drawnTray !== cd.tray || cd.flight || cd.read > 0) {
      cd.drawnTray = cd.tray;
      trayEl.innerHTML = trayMarkup();
    }
    if (cd.flight) {
      const t = easeInOut(cd.flight.t);
      const p = flightPoint(t, cd.flight.toDrive);
      /* near the tray the disc passes behind the tray's front plate: draw the plate over it there */
      const nearTray = cd.flight.toDrive ? t > 0.82 : t < 0.18;
      flyEl.innerHTML = discMarkup(p, cd.spin) + (nearTray ? plateMarkup(cd.tray * T.travel) : "");
    } else if (flyEl.firstChild) flyEl.innerHTML = "";
    if (cd.read > 0) cdLed.toggleAttribute("data-on", Math.sin(now / 45) > 0);
    else cdLed.removeAttribute("data-on");
    const a = cd.autoplay;
    autoplayEl.style.opacity = a.toFixed(3);
    autoplayEl.setAttribute("transform", `translate(0 -66.5) scale(${(0.92 + 0.08 * ease(a)).toFixed(3)}) translate(0 66.5)`);
  }
  const trayTo = (to: number) => {
    cd.trayTo = to;
    run();
    return until(() => cd.tray === to);
  };
  const fly = (toDrive: boolean) => {
    cd.flight = { t: 0, toDrive };
    run();
    return until(() => !cd.flight);
  };
  async function loadCd() {
    if (cd.busy || cd.at !== "case") return;
    cd.busy = true;
    status.textContent = "Loading the CD.";
    cd.read = 0.6;
    await trayTo(1);
    caseDisc.style.display = "none";
    await fly(true);
    cd.at = "drive";
    write();
    await sleep(250);
    await trayTo(0);
    cd.read = 2.2;
    await sleep(700);
    if (power) {
      cd.autoplayTo = 1;
      status.textContent = "AutoPlay: CD-R in drive D.";
      cancel(cd.autoplayTimer);
      cd.autoplayTimer = later(() => {
        cd.autoplayTo = 0;
        run();
      }, 5200);
    }
    run();
    cd.busy = false;
  }
  async function ejectCd() {
    if (cd.busy) return;
    cd.busy = true;
    cd.autoplayTo = 0;
    cancel(cd.autoplayTimer);
    if (cd.at === "drive") {
      status.textContent = "Ejecting the CD.";
      cd.read = 0.5;
      await trayTo(1);
      await sleep(200);
      await fly(false);
      cd.at = "case";
      caseDisc.style.display = "";
      write();
      await sleep(200);
      await trayTo(0);
    } else {
      /* an empty drive just opens and shuts */
      await trayTo(cd.trayTo ? 0 : 1);
    }
    cd.busy = false;
  }

  /* ── the idle tour ── */
  function tourStep(dt: number) {
    tour.wait -= dt;
    if (tour.wait > 0) return;
    const phrase = PHRASES[tour.phrase];
    const S = D.search;
    switch (tour.step) {
      case "aim": {
        const [x, y] = mouseFor(S.u0 + 6 + Math.random() * 6, (S.z0 + S.z1) / 2);
        aimMouse(x, y);
        tour.step = "click";
        tour.wait = 1.1;
        break;
      }
      case "click":
        mouseClick();
        tour.step = "type";
        tour.index = 0;
        tour.wait = 0.45;
        break;
      case "type":
        if (tour.index < phrase.length) {
          type(phrase[tour.index++]);
          tour.wait = 0.08 + Math.random() * 0.12 + (phrase[tour.index - 1] === " " ? 0.08 : 0);
        } else {
          tour.step = "enter";
          tour.wait = 0.8;
        }
        break;
      case "enter":
        enter();
        tour.step = "drift";
        tour.wait = 0.9;
        break;
      case "drift":
        aimMouse(lerp(M.range.x[0], M.range.x[1], Math.random()), lerp(M.range.y[0], M.range.y[1], Math.random()), 0.5);
        if (tour.phrase === PHRASES.length - 1) {
          tour.step = "cd";
          tour.wait = 1.6;
        } else {
          tour.phrase++;
          tour.step = "aim";
          tour.wait = 1.4;
        }
        break;
      case "cd":
        void loadCd();
        tour.step = "eject";
        tour.wait = 8.5;
        break;
      case "eject":
        void ejectCd();
        tour.step = "off";
        tour.wait = 5.5;
        break;
      case "off":
        setPower(0);
        tour.step = "on";
        tour.wait = 1.8;
        break;
      case "on":
        setPower(1);
        tour = { phrase: 0, step: "aim", index: 0, wait: 1.4 };
        break;
    }
  }

  /* ── the frame loop: it runs only while something is moving and the figure can be seen ── */
  function tick(now: number) {
    if (!alive) return;
    const dt = previous ? Math.min((now - previous) / 1000, 0.1) : 1 / 60;
    previous = now;
    const calm = still.matches;
    if (touring) tourStep(dt);
    powerClock += dt;
    const settledCrt = crtFrame();
    if (hdd > 0) {
      hdd = Math.max(0, hdd - dt);
      hddLed.toggleAttribute("data-on", hdd > 0 && Math.sin(now / 37) + Math.sin(now / 23) > 0.2);
    } else hddLed.removeAttribute("data-on");
    for (const i of active) {
      const s = keyState[i];
      s.held = Math.max(0, s.held - dt);
      const want = s.held > 0 ? DOWN : 0;
      s.at = calm ? want : s.at + (want - s.at) * (1 - Math.exp(-dt / (want ? 0.022 : 0.06)));
      if (Math.abs(want - s.at) < 0.01) s.at = want;
      keyEls[i].setAttribute("transform", `translate(${(down[0] * s.at).toFixed(2)} ${(down[1] * s.at).toFixed(2)})`);
      keyEls[i].toggleAttribute("data-down", s.at > 0.5);
      if (!s.held && s.at === 0) active.delete(i);
    }
    mouse.x = follow(mouse.x, mouse.tx, dt, mouse.tau);
    mouse.y = follow(mouse.y, mouse.ty, dt, mouse.tau);
    if (Math.abs(mouse.x - mouse.tx) < 0.005) mouse.x = mouse.tx;
    if (Math.abs(mouse.y - mouse.ty) < 0.005) mouse.y = mouse.ty;
    mouse.press = Math.max(0, mouse.press - dt);
    drawMouse();
    /* the tray runs on a motor (eased toward its stop); the disc flies on a timed arc */
    if (cd.tray !== cd.trayTo) {
      cd.tray = calm ? cd.trayTo : follow(cd.tray, cd.trayTo, dt, 0.17);
      if (Math.abs(cd.tray - cd.trayTo) < 0.004) cd.tray = cd.trayTo;
    }
    if (cd.flight) {
      cd.flight.t = calm ? 1 : cd.flight.t + dt / 1.15;
      cd.spin += dt * 9;
      if (cd.flight.t >= 1) cd.flight = null;
    }
    cd.read = Math.max(0, cd.read - dt);
    cd.autoplay = follow(cd.autoplay, cd.autoplayTo, dt, 0.12);
    if (Math.abs(cd.autoplay - cd.autoplayTo) < 0.004) cd.autoplay = cd.autoplayTo;
    drawCd(now);
    for (let i = waiters.length - 1; i >= 0; i--) {
      if (waiters[i].test()) {
        waiters[i].done();
        waiters.splice(i, 1);
      }
    }
    const busy =
      touring || active.size > 0 || hdd > 0 || !settledCrt || mouse.x !== mouse.tx || mouse.y !== mouse.ty || mouse.press > 0 || mouse.dragging ||
      cd.tray !== cd.trayTo || cd.flight !== null || cd.read > 0 || cd.autoplay !== cd.autoplayTo || waiters.length > 0;
    frame = visible && busy ? requestAnimationFrame(tick) : 0;
  }
  function run() {
    if (!frame && visible && alive) {
      previous = 0;
      frame = requestAnimationFrame(tick);
    }
  }
  /* the visitor takes over from the tour; it resumes after nine quiet seconds */
  function takeOver() {
    if (touring) {
      touring = false;
      tour = { phrase: 0, step: "aim", index: 0, wait: 0.4 };
      line = "";
      if (booted) setPower(1);
      write();
    }
    cancel(idleTimer);
    idleTimer = later(() => {
      if (still.matches) return;
      touring = true;
      line = "";
      setPower(1);
      write();
      run();
    }, 9000);
  }
  const io = new IntersectionObserver(
    (entries) => {
      visible = entries[entries.length - 1].isIntersecting;
      if (visible) run();
    },
    { rootMargin: "120px 0px" },
  );
  io.observe(stage);

  /* ── input ── */
  function onKey(event: KeyboardEvent) {
    if (event.metaKey || event.ctrlKey || event.altKey) return;
    const key = event.key;
    if (key === "Tab") return;
    takeOver();
    if (key === "Escape") {
      event.preventDefault();
      setPower(power ? 0 : 1);
      return;
    }
    if (key === "Backspace") {
      event.preventDefault();
      erase();
      return;
    }
    if (key === "Enter") {
      event.preventDefault();
      enter();
      return;
    }
    if (key === "CapsLock") {
      caps = !caps;
      kbLeds[1].style.opacity = caps ? "" : "0.25";
      press("CapsLock");
      return;
    }
    if (key === "Shift") {
      press(event.code === "ShiftRight" ? "ShiftRight" : "Shift", 0.14);
      return;
    }
    if (key.length === 1) {
      event.preventDefault();
      type(key);
      return;
    }
    if (indexOf(key) >= 0) press(key);
  }
  stage.addEventListener(
    "keydown",
    (event) => {
      repeating = event.repeat;
      asUser(() => onKey(event));
      repeating = false;
    },
    { signal },
  );
  let drag: null | { id: number; sx: number; sy: number; mx: number; my: number; moved: number } = null;
  mouseEl.addEventListener(
    "pointerdown",
    (event) => {
      if (event.button > 0) return;
      event.preventDefault();
      takeOver();
      const p = svgPoint(event);
      drag = { id: event.pointerId, sx: p.x, sy: p.y, mx: mouse.tx, my: mouse.ty, moved: 0 };
      mouse.dragging = true;
      stage.setAttribute("data-dragging", "");
      stage.setPointerCapture(event.pointerId);
      run();
    },
    { signal },
  );
  stage.addEventListener(
    "pointermove",
    (event) => {
      if (!drag || event.pointerId !== drag.id) return;
      const p = svgPoint(event);
      drag.moved = Math.max(drag.moved, Math.hypot(p.x - drag.sx, p.y - drag.sy));
      const [wx, wy] = toWorld(p.x - drag.sx, p.y - drag.sy);
      aimMouse(drag.mx + wx, drag.my + wy, 0.05);
    },
    { signal },
  );
  const endDrag = (event: PointerEvent) => {
    if (!drag || event.pointerId !== drag.id) return;
    const click = drag.moved < 2.5;
    drag = null;
    mouse.dragging = false;
    stage.removeAttribute("data-dragging");
    if (stage.hasPointerCapture(event.pointerId)) stage.releasePointerCapture(event.pointerId);
    if (click) mouseClick();
    run();
  };
  stage.addEventListener("pointerup", endDrag, { signal });
  stage.addEventListener("pointercancel", endDrag, { signal });
  function onClick(event: MouseEvent) {
    stage.focus({ preventScroll: true });
    const target = event.target as Element | null;
    if (!target || target.closest('[data-part="mouse"]')) return;
    const key = target.closest<SVGElement>("[data-key]");
    if (key) {
      takeOver();
      const code = KEYS[Number(key.dataset.key)];
      if (code.length === 1) type(code);
      else if (code === "Backspace") erase();
      else if (code === "Enter" || code === "NumpadEnter") enter();
      else press(code);
      return;
    }
    if (target.closest('[data-part="cd-case"]')) {
      takeOver();
      if (cd.at === "case") void loadCd();
      return;
    }
    if (target.closest('[data-part="cd-bay"]') || target.closest('[data-part="cd-tray"]')) {
      takeOver();
      void ejectCd();
      return;
    }
    if (target.closest('[data-part="mon-power"]')) {
      takeOver();
      setPower(power ? 0 : 1);
    }
  }
  svg.addEventListener("click", (event) => asUser(() => onClick(event)), { signal });
  /* the focus ring is for keyboard users: hide it once the figure has been used with a pointer */
  stage.addEventListener("pointerdown", () => stage.setAttribute("data-pointer", ""), { signal });
  stage.addEventListener("blur", () => stage.removeAttribute("data-pointer"), { signal });
  /* double-clicks and drags never select the drawing's text */
  stage.addEventListener("selectstart", (event) => event.preventDefault(), { signal });

  /* ── the assembly: shadows first, then each piece drops in, a wave across the keys, the cables last ── */
  let introTimer = 0;
  function playIntro() {
    stage.classList.remove("pdesk--intro");
    if (still.matches) return 0;
    void stage.getBoundingClientRect();
    stage.classList.add("pdesk--intro");
    let last = 0;
    stage.querySelectorAll<HTMLElement>(".it").forEach((el) => {
      last = Math.max(last, parseFloat(el.style.getPropertyValue("--d")) || 0);
    });
    cancel(introTimer);
    introTimer = later(() => stage.classList.remove("pdesk--intro"), last + 800);
    return last;
  }

  /* ── boot: assemble, then the CRT warms up and the tour begins ── */
  kbLeds[1].style.opacity = "0.25";
  kbLeds[2].style.opacity = "0.25";
  write();
  crtFrame();
  drawMouse();
  const assembled = playIntro();
  later(
    () => {
      booted = true;
      setPower(1);
      if (!still.matches) {
        touring = true;
        tour.wait = 1.4;
      }
      run();
    },
    still.matches ? 0 : assembled + 450,
  );

  return {
    replayIntro: () => void playIntro(),
    setMuted: (next) => sfx.setMuted(next),
    destroy() {
      alive = false;
      ac.abort();
      io.disconnect();
      if (frame) cancelAnimationFrame(frame);
      frame = 0;
      timers.forEach((t) => clearTimeout(t));
      timers.clear();
      waiters.length = 0;
      stage.classList.remove("pdesk--intro");
      sfx.close();
    },
  };
}

/* ===========================================================================
   Desk Computer.

   An isometric late-90s desk computer drawn as one SVG, fitted to its box by
   width and height. The component's own layout comes first; after it, the
   figure's rules — the Anatomy kit's isometric styles (MIT, © 2026 Ryan) and
   the figure's materials, live parts and assembly — every one scoped to
   .pdesk. Every colour is a token with a value for each theme, set on
   data-theme.
=========================================================================== */

.pdesk {
  position: relative;
  isolation: isolate;
  display: grid;
  place-items: center;
  width: 100%;
  aspect-ratio: 1000 / 760;
  max-height: 80vh;
  overflow: hidden;
  /* the figure sizes itself to the largest box of its own shape that fits */
  container-type: size;
  background: var(--anatomy-page);
  color: var(--anatomy-text);
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.35s ease;
}

/* filling its container: the field is the whole box and the figure centres in it */
.pdesk[data-fill] {
  height: 100%;
  aspect-ratio: auto;
  max-height: none;
}

.pdesk__stage {
  position: relative;
  width: min(1120px, 100cqw - 32px, (100cqh - 88px) * 1000 / 760);
  aspect-ratio: 1000 / 760;
  outline: none;
  touch-action: pan-y;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.pdesk[data-ready] .pdesk__stage {
  opacity: 1;
}

.pdesk__error {
  margin: 0;
  padding: 24px;
  max-width: 34em;
  color: var(--anatomy-text);
  font: 13px/1.5 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  text-align: center;
}

.pdesk__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .pdesk,
  .pdesk__stage {
    transition: none;
  }
}

