/* ── the demo file ───────────────────────────────────────────────────────── */

const NAME = "hund vill ha";

type Carry = "rest" | "dragging" | "flying" | "gone";

/*
 * A file to pick up and drop on the zone, so it can be tried without hunting
 * for something on the desktop. Dragging is pointer-driven — mouse, pen and
 * touch — and draws its own drag image: the file chip, an arrow cursor and a
 * green "copy" badge.
 */
function DemoFile({ zone, available }: { zone: RefObject<ZoneHandle | null>; available: boolean }) {
  const [mode, setMode] = useState<Carry>("rest");
  const [overZone, setOverZone] = useState(false);
  const restRef = useRef<HTMLButtonElement>(null);
  const start = useRef<{ x: number; y: number; id: number } | null>(null);
  const flights = useRef<AnimationPlaybackControls[]>([]);

  /* the drag image's anchor is the cursor tip */
  const gx = useMotionValue(0);
  const gy = useMotionValue(0);
  const gScale = useMotionValue(1);
  const gOpacity = useMotionValue(1);

  /* the file comes back once the upload has finished and the zone is ready */
  useEffect(() => {
    if (mode === "gone" && available) setMode("rest");
  }, [mode, available]);

  useEffect(
    () => () => {
      flights.current.forEach((f) => f.stop());
      document.documentElement.classList.remove("pdz-carrying");
    },
    [],
  );

  const restCenter = () => {
    const r = restRef.current?.getBoundingClientRect();
    return r ? { x: r.left + r.width / 2, y: r.top + r.height / 2 } : { x: 0, y: 0 };
  };

  const pickUp = (x: number, y: number) => {
    flights.current.forEach((f) => f.stop());
    gx.set(x);
    gy.set(y);
    gScale.set(1);
    gOpacity.set(1);
    setMode("dragging");
  };

  const move = (x: number, y: number) => {
    gx.set(x);
    gy.set(y);
    setOverZone(zone.current?.dragMove(x, y) ?? false);
  };

  const putDown = (x: number, y: number) => {
    document.documentElement.classList.remove("pdz-carrying");
    setOverZone(false);
    const taken = zone.current?.dragEnd(x, y) ?? false;
    setMode("flying");
    if (taken) {
      /* swallowed: the drag image is pulled into the hole */
      const c = zone.current?.center() ?? { x, y };
      const ease = [0.55, 0, 0.9, 0.45] as const;
      flights.current = [
        animate(gx, c.x, { duration: 0.34, ease }),
        animate(gy, c.y, { duration: 0.34, ease }),
        animate(gScale, 0.15, { duration: 0.34, ease }),
        animate(gOpacity, 0, { duration: 0.34, ease: "easeIn", onComplete: () => setMode("gone") }),
      ];
    } else {
      /* missed: it slides back to where it was picked up */
      const home = restCenter();
      flights.current = [
        animate(gx, home.x, { type: "spring", visualDuration: 0.4, bounce: 0.2 }),
        animate(gy, home.y, { type: "spring", visualDuration: 0.4, bounce: 0.2 }),
        animate(gOpacity, 0, { duration: 0.3, delay: 0.15, onComplete: () => setMode("rest") }),
      ];
    }
  };

  const onPointerDown = (e: ReactPointerEvent<HTMLButtonElement>) => {
    if (mode !== "rest" || !available || e.button !== 0) return;
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    start.current = { x: e.clientX, y: e.clientY, id: e.pointerId };
  };

  const onPointerMove = (e: ReactPointerEvent<HTMLButtonElement>) => {
    const s = start.current;
    if (!s || s.id !== e.pointerId) return;
    if (mode === "rest") {
      /* a few pixels of travel before it counts as a drag, so a stray click does nothing */
      if (Math.hypot(e.clientX - s.x, e.clientY - s.y) < 4) return;
      document.documentElement.classList.add("pdz-carrying");
      pickUp(e.clientX, e.clientY);
    }
    move(e.clientX, e.clientY);
  };

  const onPointerUp = (e: ReactPointerEvent<HTMLButtonElement>) => {
    const s = start.current;
    if (!s || s.id !== e.pointerId) return;
    start.current = null;
    if (mode === "dragging") putDown(e.clientX, e.clientY);
  };

  /* keyboard: Enter or Space plays the drag for you */
  const autoplay = () => {
    const c = zone.current?.center();
    if (!c || mode !== "rest" || !available) return;
    const from = restCenter();
    const xs = [from.x, c.x - 210, c.x - 40, c.x + 120, c.x + 135, c.x - 90, c.x + 30, c.x + 10];
    const ys = [from.y, c.y - 40, c.y + 10, c.y + 60, c.y - 70, c.y - 30, c.y + 75, c.y + 5];
    pickUp(from.x, from.y);
    const opts = { duration: 4.2, ease: "easeInOut" as const };
    flights.current = [
      animate(gx, xs, { ...opts, onUpdate: () => move(gx.get(), gy.get()) }),
      animate(gy, ys, { ...opts, onComplete: () => putDown(gx.get(), gy.get()) }),
    ];
  };

  const onKeyDown = (e: ReactKeyboardEvent<HTMLButtonElement>) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      autoplay();
    }
  };

  const carrying = mode === "dragging" || mode === "flying";

  return (
    <>
      <div className="pdz__file">
        <motion.button
          ref={restRef}
          type="button"
          aria-label={`Demo file "${NAME}". Drag it onto the drop zone, or press Enter to play the drag.`}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={onPointerUp}
          onPointerCancel={onPointerUp}
          onKeyDown={onKeyDown}
          onDragStart={(e) => e.preventDefault()}
          initial={false}
          animate={mode === "gone" ? { opacity: 0, scale: 0.6 } : carrying ? { opacity: 0.45, scale: 1 } : { opacity: 1, scale: 1 }}
          whileHover={mode === "rest" ? { y: -2 } : undefined}
          transition={{ type: "spring", visualDuration: 0.35, bounce: 0.3 }}
          className="pdz__fileButton"
        >
          <FileThumb size="lg" />
          <span className="pdz__fileName">{NAME}</span>
        </motion.button>
        <AnimatePresence initial={false}>
          {mode === "rest" && (
            <motion.p
              key="hint"
              initial={{ opacity: 0, x: -4 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -4 }}
              className="pdz__hint"
            >
              Drag this file onto the drop zone
            </motion.p>
          )}
        </AnimatePresence>
      </div>

      {carrying &&
        createPortal(
          <motion.div aria-hidden="true" className="pdz-ghost" style={{ x: gx, y: gy, scale: gScale, opacity: gOpacity }}>
            {/* the chip sits up and to the left of the cursor tip */}
            <div className="pdz-ghost__chip">
              <FileThumb size="sm" />
              <span className="pdz__fileName">{NAME}</span>
            </div>
            <svg className="pdz-ghost__cursor" width="17" height="25" viewBox="0 0 17 25">
              <path d="M1 1v19.5l4.6-4.4 3.1 7.2 3.2-1.4-3.1-7.1h6.4L1 1z" fill="#111" stroke="#fff" strokeWidth={1.4} strokeLinejoin="round" />
            </svg>
            <motion.span
              className="pdz-ghost__copy"
              animate={{ scale: overZone ? 1 : 0.85 }}
              transition={{ type: "spring", visualDuration: 0.25, bounce: 0.5 }}
            >
              <svg viewBox="0 0 12 12" aria-hidden="true">
                <path d="M6 1.5v9M1.5 6h9" stroke="white" strokeWidth={2.4} strokeLinecap="round" />
              </svg>
            </motion.span>
          </motion.div>,
          document.body,
        )}
    </>
  );
}

function FileThumb({ size }: { size: "lg" | "sm" }) {
  return (
    <span className={`pdz__thumb pdz__thumb--${size}`}>
      {/* lucide: dog */}
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={size === "sm" ? 2.5 : 2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
        <path d="M11.25 16.25h1.5L12 17z" />
        <path d="M16 14v.5" />
        <path d="M4.42 11.247A13.152 13.152 0 0 0 4 14.556C4 18.728 7.582 21 12 21s8-2.272 8-6.444a11.702 11.702 0 0 0-.493-3.309" />
        <path d="M8 14v.5" />
        <path d="M8.5 8.5c-.384 1.05-1.083 2.028-2.344 2.5-1.931.722-3.576-.297-3.656-1-.113-.994 1.177-6.53 4-7 1.923-.321 3.651.845 3.651 2.235A7.497 7.497 0 0 1 14 5.277c0-1.39 1.844-2.598 3.767-2.277 2.823.47 4.113 6.006 4 7-.08.703-1.725 1.722-3.656 1-1.261-.472-1.855-1.45-2.239-2.5" />
      </svg>
    </span>
  );
}

/* ===========================================================================
   Dynamic Drop Zone.

   The zone and a demo file centred under it, with no panel of their own: they
   sit on whatever field they are placed on. The text around the zone is
   themed through the tokens below; the zone itself animates between literal
   colours set in the component, since Motion tweens those directly.
=========================================================================== */

.pdz {
  --pdz-hint: #71717a;
  --pdz-focus: rgb(24 24 27 / 0.55);

  display: flex;
  justify-content: center;
  width: 100%;
  font-family: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

.pdz[data-theme="dark"] {
  --pdz-hint: rgb(244 244 245 / 0.5);
  --pdz-focus: rgb(244 244 245 / 0.6);
}

.pdz *,
.pdz *::before,
.pdz *::after {
  box-sizing: border-box;
}

.pdz__body {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  min-width: 0;
  max-width: 380px;
}

/* the zone is drawn at 380 × 280 and scaled as one to fit a narrow panel */
.pdz__fit {
  position: relative;
  width: 100%;
  max-width: 380px;
  flex: none;
}

.pdz__scaled {
  position: absolute;
  top: 0;
  left: 50%;
  width: 380px;
  height: 280px;
  margin-left: -190px;
  transform-origin: 50% 0;
}

/* the demo file sits centred under the zone, the way a file waits to be picked up */
.pdz__tray {
  display: flex;
  justify-content: center;
  width: 100%;
  padding-top: 28px;
}

/* --- the zone ------------------------------------------------------------- */

.pdz__zone {
  position: relative;
}

.pdz__card {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.pdz__layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.pdz__ring {
  position: absolute;
  border: 1px dashed transparent;
}

.pdz__fade {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 96px;
  pointer-events: none;
}

.pdz__labels {
  display: grid;
  place-items: center;
}

.pdz__label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
  white-space: nowrap;
}

.pdz__label--busy {
  position: relative;
  z-index: 10;
  gap: 10px;
}

.pdz__label--hole {
  gap: 10px;
  color: #ffffff;
  font-size: 17px;
}

.pdz__clip {
  width: 17px;
  height: 17px;
}

.pdz__arrow {
  display: grid;
  color: rgb(255 255 255 / 0.7);
}

.pdz__arrow svg {
  width: 22px;
  height: 22px;
}

.pdz__status {
  position: relative;
  display: grid;
  place-items: center;
  width: 16px;
  height: 16px;
}

.pdz__spinner {
  display: block;
  width: 16px;
  height: 16px;
  animation: pdz-spin 0.9s linear infinite;
}

@keyframes pdz-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .pdz__spinner {
    animation-duration: 2.4s;
  }
}

.pdz__statusIcon {
  position: absolute;
  inset: 0;
}

.pdz__icon16 {
  display: block;
  width: 16px;
  height: 16px;
}

.pdz__core {
  position: absolute;
  top: 50%;
  left: 50%;
}

.pdz__bit {
  position: absolute;
  display: block;
}

.pdz__bit--sq {
  border-radius: 5px;
  background: #3f3f46;
}

.pdz__bit--dot {
  border-radius: 999px;
  background: rgb(113 113 122 / 0.8);
}

.pdz__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* --- the demo file ---------------------------------------------------------- */

.pdz__file {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  /* the hint coming and going never moves the file */
  min-height: 112px;
}

.pdz__fileButton {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 6px;
  border: 0;
  border-radius: 8px;
  background: none;
  font: inherit;
  cursor: grab;
  outline: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

.pdz__fileButton:active {
  cursor: grabbing;
}

.pdz__fileButton:focus-visible {
  box-shadow: 0 0 0 2px var(--pdz-focus);
}

.pdz__thumb {
  display: grid;
  place-items: center;
  background: linear-gradient(to bottom right, #f6c27a, #e39a52, #a8603a);
  color: #ffffff;
  box-shadow: 0 2px 6px rgb(0 0 0 / 0.35);
}

.pdz__thumb--lg {
  width: 52px;
  height: 44px;
  border: 2px solid #ffffff;
  border-radius: 4px;
}

.pdz__thumb--lg svg {
  width: 22px;
  height: 22px;
}

.pdz__thumb--sm {
  width: 17px;
  height: 14px;
  border: 1px solid #ffffff;
  border-radius: 2px;
}

.pdz__thumb--sm svg {
  width: 9px;
  height: 9px;
}

.pdz__fileName {
  padding: 1px 6px;
  border-radius: 4px;
  background: #1d5be0;
  color: #ffffff;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.35;
  white-space: nowrap;
}

.pdz__hint {
  margin: 0;
  text-align: center;
  color: var(--pdz-hint);
  font-size: 12px;
  line-height: 1.375;
}

/* --- the drag image, portalled to the body ---------------------------------- */

.pdz-ghost {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 100;
  font-family: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  pointer-events: none;
}

.pdz-ghost__chip {
  position: absolute;
  top: -14px;
  right: 3px;
  display: flex;
  align-items: center;
  gap: 4px;
}

.pdz-ghost__cursor {
  position: absolute;
  top: -1px;
  left: -1px;
  filter: drop-shadow(0 1px 1.5px rgb(0 0 0 / 0.45));
}

.pdz-ghost__copy {
  position: absolute;
  top: 15px;
  left: 9px;
  display: grid;
  place-items: center;
  width: 21px;
  height: 21px;
  border: 1.5px solid #ffffff;
  border-radius: 999px;
  background: #29c246;
  box-shadow: 0 1px 3px rgb(0 0 0 / 0.4);
}

.pdz-ghost__copy svg {
  width: 11px;
  height: 11px;
}

/* while the demo file is carried, its drag image is the cursor */
.pdz-carrying,
.pdz-carrying * {
  cursor: none !important;
}

"use client";

import { useEffect, useId, useRef, useState, type PointerEvent as ReactPointerEvent, type ReactNode } from "react";
import {
  AnimatePresence,
  LayoutGroup,
  motion,
  useAnimate,
  useMotionTemplate,
  useMotionValue,
  useReducedMotion,
  type Transition,
  type Variants,
} from "motion/react";
import "./swap-card.css";

/**
 * Swap Card — a token swap card where every number moves.
 *
 * Swap, Buy and Stake share one card; the tab pill slides between them. Type
 * an amount and the quote rolls in an odometer, a digit at a time; flip the
 * pair and the two token pills glide past each other to trade panels while the
 * arrow turns. The token list opens out of its pill through a blur, the rate
 * line rolls over when the pair changes, and the details drawer unfolds on the
 * same spring as everything else. The button is liquid: light pools drift
 * across it, it ripples where it is pressed, shakes "no" when it cannot swap,
 * sweeps while the swap is in flight and throws a ring of specks when it lands.
 */

export type SwapCardToken = {
  symbol: string;
  name: string;
  /** USD price, used to quote every pair. */
  price: number;
  /** 24h change, shown beside the dollar value. */
  change: number;
  /** The coin mark's colour. */
  color: string;
};

export type SwapCardProps = {
  theme?: "light" | "dark";
  /** Fired when a swap, buy or stake lands. */
  onSwap?: (trade: { mode: "Swap" | "Buy" | "Stake"; pay: string; receive: string; amount: number; received: number }) => void;
};

type Mode = "Swap" | "Buy" | "Stake";
type Side = "pay" | "receive";
type Status = "idle" | "pending" | "done";

/* one spring drives every morph so all the pieces land together, plus a short eased fade */
const morph: Transition = { type: "spring", visualDuration: 0.42, bounce: 0.16 };
const fade = (delay = 0): Transition => ({ duration: 0.22, ease: [0.25, 0.1, 0.25, 1], delay });

export const SWAP_CARD_TOKENS: SwapCardToken[] = [
  { symbol: "USDT", name: "Tether USD", price: 1, change: -0.45, color: "#26a17b" },
  { symbol: "ETH", name: "Ethereum", price: 3260.2, change: -0.45, color: "#627eea" },
  { symbol: "USDC", name: "USD Coin", price: 1, change: 0.01, color: "#2775ca" },
  { symbol: "BTC", name: "Bitcoin", price: 67420, change: 1.12, color: "#f7931a" },
  { symbol: "DAI", name: "Dai", price: 1, change: -0.02, color: "#f5ac37" },
  { symbol: "USD", name: "US Dollar", price: 1, change: 0, color: "#1f9d55" },
  { symbol: "stETH", name: "Lido Staked ETH", price: 3255.4, change: -0.51, color: "#00a3ff" },
];

const tokens = SWAP_CARD_TOKENS;
const bySymbol = (symbol: string) => tokens.find((t) => t.symbol === symbol)!;

const initialBalances: Record<string, number> = {
  USDT: 4537.5,
  ETH: 0,
  USDC: 1250,
  BTC: 0,
  DAI: 0,
  USD: 10000,
  stETH: 0,
};

const modes: Record<Mode, { pay: string; receive: string; amount: string; doing: string; done: string }> = {
  Swap: { pay: "USDT", receive: "ETH", amount: "164.23", doing: "Swapping", done: "Swapped" },
  Buy: { pay: "USD", receive: "ETH", amount: "250", doing: "Buying", done: "Bought" },
  Stake: { pay: "ETH", receive: "stETH", amount: "", doing: "Staking", done: "Staked" },
};

/* entrance: each block rises out of a soft blur, one after another */
const stagger: Variants = { hidden: {}, shown: { transition: { staggerChildren: 0.07, delayChildren: 0.05 } } };
const rise: Variants = {
  hidden: { opacity: 0, y: 16, filter: "blur(6px)" },
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { ...morph, opacity: fade(), filter: fade() } },
};

const usd = (v: number) => "$" + v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

function fmtOut(v: number) {
  if (v === 0) return "0";
  if (v >= 1000) return v.toLocaleString("en-US", { maximumFractionDigits: 2 });
  if (v >= 1) return v.toLocaleString("en-US", { maximumFractionDigits: 4 });
  return v.toLocaleString("en-US", { maximumSignificantDigits: 3 });
}

function fmtRate(r: number) {
  if (r >= 1000) return r.toLocaleString("en-US", { maximumFractionDigits: 2 });
  if (r >= 1) return r.toLocaleString("en-US", { maximumFractionDigits: 4 });
  return r.toLocaleString("en-US", { maximumSignificantDigits: 5 });
}

function fmtBalance(v: number) {
  if (v === 0) return "none";
  return v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: v < 1 ? 6 : 2 });
}

/* a plain decimal string for the input: no grouping, no trailing zeros */
const toInput = (v: number) => (v > 0 ? String(Number(v.toFixed(8))) : "");

function sanitize(raw: string) {
  let s = raw.replace(",", ".").replace(/[^\d.]/g, "");
  const dot = s.indexOf(".");
  if (dot !== -1) s = s.slice(0, dot + 1) + s.slice(dot + 1).replace(/\./g, "").slice(0, 8);
  if (s.startsWith(".")) s = "0" + s;
  return s.replace(/^0+(?=\d)/, "");
}

const amountSize = (text: string) => (text.length <= 7 ? 38 : text.length <= 9 ? 32 : text.length <= 11 ? 27 : 22);

export default function SwapCard({ theme = "light", onSwap }: SwapCardProps) {
  const [mode, setMode] = useState<Mode>("Swap");
  const [pay, setPay] = useState(modes.Swap.pay);
  const [receive, setReceive] = useState(modes.Swap.receive);
  const [amount, setAmount] = useState(modes.Swap.amount);
  const [balances, setBalances] = useState(initialBalances);
  const [flips, setFlips] = useState(0);
  const [picker, setPicker] = useState<Side | null>(null);
  const [details, setDetails] = useState(false);
  const [status, setStatus] = useState<Status>("idle");
  const timers = useRef<number[]>([]);
  /* its own layout group, so two cards on a page never trade pills */
  const group = useId();
  /* flipping back and forth restores the typed amount instead of compounding rounding */
  const lastFlip = useRef<{ shown: string; typed: string } | null>(null);
  const clearTimers = () => {
    timers.current.forEach(clearTimeout);
    timers.current = [];
  };
  useEffect(() => clearTimers, []);

  const payT = bySymbol(pay);
  const receiveT = bySymbol(receive);
  const value = parseFloat(amount) || 0;
  const rate = payT.price / receiveT.price;
  const out = value * rate;
  /* the opening quote shows the reference design's figures exactly; any edit switches to live quoting */
  const preset = mode === "Swap" && pay === "USDT" && receive === "ETH" && amount === modes.Swap.amount;
  const outText = preset ? "0.0505" : fmtOut(out);
  const payUsd = preset ? 64.23 : value * payT.price;
  const receiveUsd = preset ? 64.23 : out * receiveT.price;
  const insufficient = value > balances[pay] + 1e-9;
  const ready = value > 0 && !insufficient && status === "idle";

  const label =
    status === "pending"
      ? `${modes[mode].doing}…`
      : status === "done"
        ? modes[mode].done
        : value === 0
          ? "Enter an amount"
          : insufficient
            ? `Insufficient ${pay}`
            : mode;

  const switchMode = (next: Mode) => {
    if (next === mode || status === "pending") return;
    clearTimers();
    setStatus("idle");
    setMode(next);
    setPay(modes[next].pay);
    setReceive(modes[next].receive);
    setAmount(modes[next].amount);
    setPicker(null);
  };

  const flip = () => {
    if (status === "pending") return;
    setPay(receive);
    setReceive(pay);
    const next = lastFlip.current?.shown === amount ? lastFlip.current.typed : toInput(out);
    lastFlip.current = { shown: next, typed: amount };
    setAmount(next);
    setFlips((n) => n + 1);
    setPicker(null);
  };

  const pick = (side: Side, symbol: string) => {
    setPicker(null);
    const other = side === "pay" ? receive : pay;
    if (symbol === other) return flip();
    if (side === "pay") setPay(symbol);
    else setReceive(symbol);
  };

  const submit = () => {
    if (!ready) return;
    setStatus("pending");
    timers.current.push(
      window.setTimeout(() => {
        setBalances((b) => ({ ...b, [pay]: Math.max(0, b[pay] - value), [receive]: b[receive] + out }));
        setStatus("done");
        onSwap?.({ mode, pay, receive, amount: value, received: out });
      }, 1200),
      window.setTimeout(() => setStatus("idle"), 2600),
    );
  };

  return (
    <div className="pswap" data-theme={theme}>
      <LayoutGroup id={`pswap-${group}`}>
        <motion.div variants={stagger} initial="hidden" animate="shown" className="pswap__card">
          <motion.div variants={rise} className="pswap__tabsRow">
            <Tabs mode={mode} onChange={switchMode} />
          </motion.div>

          <motion.div variants={rise} className="pswap__slot" data-raised={picker === "pay" || undefined}>
            <Panel label="Pay">
              <div className="pswap__row">
                <motion.input
                  key={`pay-${flips}-${mode}`}
                  initial={{ opacity: 0, y: 14 }}
                  animate={{ opacity: 1, y: 0, transition: { ...morph, opacity: fade() } }}
                  aria-label="Pay amount"
                  inputMode="decimal"
                  autoComplete="off"
                  placeholder="0"
                  value={amount}
                  onChange={(e) => setAmount(sanitize(e.target.value))}
                  style={{ fontSize: amountSize(amount) }}
                  className="pswap__amount pswap__input"
                />
                <TokenSelect
                  token={payT}
                  open={picker === "pay"}
                  onToggle={() => setPicker(picker === "pay" ? null : "pay")}
                  onClose={() => setPicker(null)}
                  onPick={(s) => pick("pay", s)}
                  balances={balances}
                />
              </div>
              <FooterRow
                left={<UsdValue value={payUsd} change={payT.change} />}
                right={
                  <>
                    You have <Roll className="pswap__have">{fmtBalance(balances[pay])}</Roll>
                    <motion.button
                      type="button"
                      whileHover={{ scale: 1.06 }}
                      whileTap={{ scale: 0.9 }}
                      transition={morph}
                      onClick={() => setAmount(toInput(balances[pay]))}
                      disabled={balances[pay] === 0}
                      className="pswap__max"
                    >
                      MAX
                    </motion.button>
                  </>
                }
              />
            </Panel>
          </motion.div>

          {/* the flip button sits on the seam between the two panels */}
          <div className="pswap__seam">
            <motion.button
              type="button"
              aria-label="Switch pay and receive"
              onClick={flip}
              initial={{ scale: 0.4, opacity: 0 }}
              animate={{ scale: 1, opacity: 1, transition: { ...morph, delay: 0.25 } }}
              whileHover={{ scale: 1.08 }}
              whileTap={{ scale: 0.9 }}
              className="pswap__flip"
            >
              <motion.span animate={{ rotate: flips * 180 }} transition={morph} className="pswap__flipIcon">
                {/* lucide: arrow-down-up */}
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                  <path d="m3 16 4 4 4-4" />
                  <path d="M7 20V4" />
                  <path d="m21 8-4-4-4 4" />
                  <path d="M17 4v16" />
                </svg>
              </motion.span>
            </motion.button>
          </div>

          <motion.div variants={rise} className="pswap__slot" data-raised={picker === "receive" || undefined}>
            <Panel label="Receive">
              <div className="pswap__row">
                <div
                  aria-label="Receive amount"
                  aria-live="polite"
                  style={{ fontSize: amountSize("~" + outText) }}
                  className="pswap__amount pswap__out"
                  data-empty={out === 0 || undefined}
                >
                  <span>~</span>
                  <RollingNumber value={outText} />
                </div>
                <TokenSelect
                  token={receiveT}
                  open={picker === "receive"}
                  onToggle={() => setPicker(picker === "receive" ? null : "receive")}
                  onClose={() => setPicker(null)}
                  onPick={(s) => pick("receive", s)}
                  balances={balances}
                />
              </div>
              <FooterRow
                left={<UsdValue value={receiveUsd} change={receiveT.change} />}
                right={
                  <>
                    You have <Roll className="pswap__have">{fmtBalance(balances[receive])}</Roll>
                  </>
                }
              />
            </Panel>
          </motion.div>

          <motion.div variants={rise}>
            <button type="button" aria-expanded={details} onClick={() => setDetails(!details)} className="pswap__rate">
              <span className="pswap__rateText">
                <Swap key={`${pay}-${receive}`} distance={12}>
                  {`1 ${pay} = ${fmtRate(rate)} ${receive}`}
                </Swap>
              </span>
              <motion.span animate={{ rotate: details ? 180 : 0 }} transition={morph} className="pswap__rateChevron">
                <ChevronDown />
              </motion.span>
            </button>

            <AnimatePresence initial={false}>
              {details && (
                <motion.div
                  key="details"
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: "auto", opacity: 1, transition: { ...morph, opacity: fade(0.05) } }}
                  exit={{ height: 0, opacity: 0, transition: { ...morph, opacity: fade() } }}
                  className="pswap__drawer"
                >
                  <dl className="pswap__details">
                    {[
                      ["Price impact", `${receiveT.change.toFixed(2)}%`],
                      ["Minimum received", `${fmtOut(out * 0.995)} ${receive}`],
                      ["Slippage tolerance", "0.5%"],
                      ["Network fee", value > 0 ? "~$2.14" : "—"],
                      ["Route", `${pay} → ${receive}`],
                    ].map(([k, v], i) => (
                      <motion.div
                        key={k}
                        initial={{ opacity: 0, y: -4 }}
                        animate={{ opacity: 1, y: 0, transition: { ...morph, delay: 0.04 + i * 0.03 } }}
                        className="pswap__detail"
                      >
                        <dt>{k}</dt>
                        <dd>{v}</dd>
                      </motion.div>
                    ))}
                  </dl>
                </motion.div>
              )}
            </AnimatePresence>
          </motion.div>

          <motion.div variants={rise}>
            <LiquidButton disabled={!ready && status === "idle"} busy={status !== "idle"} success={status === "done"} onClick={submit}>
              <span className="pswap__label">
                <Swap key={label} distance={14}>
                  <span className="pswap__labelInner">
                    {status === "pending" && (
                      /* lucide: loader-circle */
                      <svg className="pswap__spin" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.25} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                        <path d="M21 12a9 9 0 1 1-6.219-8.56" />
                      </svg>
                    )}
                    {status === "done" && <CheckIcon className="pswap__done" />}
                    {label}
                  </span>
                </Swap>
              </span>
            </LiquidButton>
          </motion.div>
        </motion.div>
      </LayoutGroup>
    </div>
  );
}

function Tabs({ mode, onChange }: { mode: Mode; onChange: (m: Mode) => void }) {
  return (
    <div role="tablist" aria-label="Action" className="pswap__tabs">
      {(Object.keys(modes) as Mode[]).map((m) => (
        <motion.button
          key={m}
          type="button"
          role="tab"
          whileTap={{ scale: 0.94 }}
          transition={morph}
          aria-selected={m === mode}
          onClick={() => onChange(m)}
          className="pswap__tab"
        >
          {m === mode && <motion.span layoutId="pswap-tab" transition={morph} className="pswap__tabPill" />}
          <span className="pswap__tabText">{m}</span>
        </motion.button>
      ))}
    </div>
  );
}

function Panel({ label, children }: { label: string; children: ReactNode }) {
  return (
    <section className="pswap__panel">
      <h2 className="pswap__panelLabel">{label}</h2>
      {children}
    </section>
  );
}

function FooterRow({ left, right }: { left: ReactNode; right: ReactNode }) {
  return (
    <div className="pswap__foot">
      <div>{left}</div>
      <div className="pswap__footRight">{right}</div>
    </div>
  );
}

function UsdValue({ value, change }: { value: number; change: number }) {
  return (
    <span className="pswap__usd">
      <RollingNumber value={usd(value)} />
      <span className="pswap__faint">
        ({change > 0 ? "+" : ""}
        {change.toFixed(2)}%)
      </span>
    </span>
  );
}

function TokenSelect({
  token,
  open,
  onToggle,
  onClose,
  onPick,
  balances,
}: {
  token: SwapCardToken;
  open: boolean;
  onToggle: () => void;
  onClose: () => void;
  onPick: (symbol: string) => void;
  balances: Record<string, number>;
}) {
  const ref = useRef<HTMLDivElement>(null);

  /* open with the current token in view, even when it sits below the fold */
  const centreCurrent = (list: HTMLUListElement | null) => {
    /* measure the <li>: its offset is relative to the list, the button's isn't mid-animation */
    const current = list?.querySelector<HTMLElement>('[aria-selected="true"]')?.closest("li");
    if (list && current) list.scrollTop = current.offsetTop - (list.clientHeight - current.offsetHeight) / 2;
  };

  /* Escape or a press anywhere else closes the list */
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    const onDown = (e: PointerEvent) => !ref.current?.contains(e.target as Node) && onClose();
    window.addEventListener("keydown", onKey);
    window.addEventListener("pointerdown", onDown);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("pointerdown", onDown);
    };
  }, [open, onClose]);

  return (
    <div ref={ref} className="pswap__select">
      {/* a layout id per token: when the sides flip, each pill glides to the other panel */}
      <motion.button
        type="button"
        layoutId={`pswap-pill-${token.symbol}`}
        transition={morph}
        aria-haspopup="listbox"
        aria-expanded={open}
        onClick={onToggle}
        whileTap={{ scale: 0.95 }}
        className="pswap__pill"
        style={{ borderRadius: 999 }}
      >
        <motion.span layout="position" transition={morph} className="pswap__pillToken">
          <TokenIcon token={token} size={20} />
          {token.symbol}
        </motion.span>
        <motion.span layout="position" animate={{ rotate: open ? 180 : 0 }} transition={morph} className="pswap__pillChevron">
          <ChevronDown />
        </motion.span>
      </motion.button>

      <AnimatePresence>
        {open && (
          <motion.ul
            ref={centreCurrent}
            role="listbox"
            aria-label="Select token"
            initial={{ opacity: 0, scale: 0.9, y: -6, filter: "blur(4px)" }}
            animate={{ opacity: 1, scale: 1, y: 0, filter: "blur(0px)", transition: { ...morph, opacity: fade() } }}
            exit={{ opacity: 0, scale: 0.94, y: -4, filter: "blur(4px)", transition: { duration: 0.14 } }}
            style={{ originX: 1, originY: 0 }}
            className="pswap__list"
          >
            {tokens.map((t, i) => (
              <motion.li key={t.symbol} initial={{ opacity: 0, x: 8 }} animate={{ opacity: 1, x: 0, transition: { ...morph, delay: 0.03 + i * 0.025 } }}>
                <button
                  type="button"
                  role="option"
                  aria-selected={t.symbol === token.symbol}
                  onClick={() => onPick(t.symbol)}
                  className="pswap__option"
                >
                  <TokenIcon token={t} size={24} />
                  <span className="pswap__optionName">
                    <span className="pswap__optionSymbol">{t.symbol}</span>
                    <span className="pswap__optionFull">{t.name}</span>
                  </span>
                  <span className="pswap__optionBalance">{balances[t.symbol] ? fmtBalance(balances[t.symbol]) : ""}</span>
                  {t.symbol === token.symbol && <CheckIcon className="pswap__optionCheck" />}
                </button>
              </motion.li>
            ))}
          </motion.ul>
        )}
      </AnimatePresence>
    </div>
  );
}

/* text that rolls up when it changes; give it a new key to trigger the roll */
function Swap({ distance, children }: { distance: number; children: ReactNode }) {
  return (
    <motion.span
      initial={{ opacity: 0, y: distance }}
      animate={{ opacity: 1, y: 0, transition: { ...morph, opacity: fade() } }}
      className="pswap__swap"
    >
      {children}
    </motion.span>
  );
}

/* a short label that rolls whenever its text changes */
function Roll({ children, className = "" }: { children: string; className?: string }) {
  return (
    <span className={"pswap__roll " + className}>
      <Swap key={children} distance={10}>
        {children}
      </Swap>
    </span>
  );
}

/* an odometer: every character that changes slides out the top while its
   replacement rises from below; the unchanged ones stay put */
function RollingNumber({ value }: { value: string }) {
  const chars = value.split("");
  return (
    <span className="pswap__odometer">
      <AnimatePresence initial={false} mode="popLayout">
        {chars.map((c, i) => (
          <motion.span
            key={`${chars.length - i}:${c}`}
            layout="position"
            initial={{ y: "80%", opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: "-80%", opacity: 0 }}
            transition={{ ...morph, opacity: fade() }}
            className="pswap__digit"
          >
            {c}
          </motion.span>
        ))}
      </AnimatePresence>
    </span>
  );
}

/* lucide: chevron-down */
function ChevronDown() {
  return (
    <svg className="pswap__chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="m6 9 6 6 6-6" />
    </svg>
  );
}

/* lucide: check */
function CheckIcon({ className }: { className: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M20 6 9 17l-5-5" />
    </svg>
  );
}

/* round coin marks, drawn inline so nothing has to load */
function TokenIcon({ token, size = 22 }: { token: SwapCardToken; size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 32 32" aria-hidden="true" className="pswap__coin">
      <circle cx="16" cy="16" r="16" fill={token.color} />
      <Glyph symbol={token.symbol} />
    </svg>
  );
}

function Glyph({ symbol }: { symbol: string }) {
