    case "USDT":
      return (
        <g fill="#fff">
          <path d="M8.5 8.6h15v3.3h-5.6v11.6h-3.8V11.9H8.5z" />
          <ellipse cx="16" cy="15.4" rx="7.4" ry="1.9" fill="none" stroke="#fff" strokeWidth="1.5" />
        </g>
      );
    case "ETH":
    case "stETH":
      return (
        <g fill="#fff">
          <path d="M16 5.5v7.8l6.6 2.9z" fillOpacity=".6" />
          <path d="M16 5.5 9.4 16.2l6.6-2.9z" />
          <path d="M16 21.3v5.2l6.6-9.2z" fillOpacity=".6" />
          <path d="M16 26.5v-5.2l-6.6-4z" />
          <path d="M16 20.1l6.6-3.9L16 13.3z" fillOpacity=".2" />
          <path d="M9.4 16.2l6.6 3.9v-6.8z" fillOpacity=".6" />
        </g>
      );
    case "BTC":
      return (
        <text x="16" y="22" textAnchor="middle" fontSize="17" fontWeight="700" fill="#fff" fontFamily="system-ui">
          ₿
        </text>
      );
    case "DAI":
      return (
        <text x="16" y="21.5" textAnchor="middle" fontSize="14" fontWeight="800" fill="#fff" fontFamily="system-ui">
          D
        </text>
      );
    default:
      return (
        <text x="16" y="22" textAnchor="middle" fontSize="17" fontWeight="700" fill="#fff" fontFamily="system-ui">
          $
        </text>
      );
  }
}

/* ── the liquid button ───────────────────────────────────────────────────── */

/* soft pools of light drifting across the button, like light through water */
const blobs = [
  { w: 120, h: 60, top: -16, dur: 5.5, delay: 0, color: "rgb(170 225 255 / 0.95)" },
  { w: 95, h: 50, top: 8, dur: 7, delay: -2.5, color: "rgb(125 205 255 / 0.85)" },
  { w: 135, h: 68, top: -6, dur: 8.5, delay: -5, color: "rgb(200 238 255 / 0.7)" },
];

/* tiny glints that twinkle on the surface */
const sparks = Array.from({ length: 14 }, (_, i) => ({
  left: (i * 37) % 100,
  top: 18 + ((i * 53) % 64),
  dur: 1.6 + (i % 5) * 0.35,
  delay: (i * 0.29) % 2,
}));

/* specks thrown out of the button when a swap lands */
const burst = Array.from({ length: 14 }, (_, i) => {
  const angle = (i / 14) * Math.PI * 2;
  const reach = 1 + (i % 3) * 0.22;
  return { x: Math.cos(angle) * 190 * reach, y: Math.sin(angle) * 44 * reach, size: 3 + (i % 3) };
});

type Ripple = { id: number; x: number; y: number };

/* kept light: a thin inner highlight and a short, soft drop */
const restShadow =
  "inset 0 1px 0 rgb(255 255 255 / 0.3), inset 0 -1px 2px rgb(10 40 160 / 0.2), 0 3px 8px -4px rgb(47 100 245 / 0.35)";
const hoverShadow =
  "inset 0 1px 0 rgb(255 255 255 / 0.36), inset 0 -1px 2px rgb(10 40 160 / 0.2), 0 4px 12px -5px rgb(47 100 245 / 0.45)";

function LiquidButton({
  children,
  disabled,
  busy,
  success,
  onClick,
}: {
  children: ReactNode;
  disabled: boolean;
  busy: boolean;
  success: boolean;
  onClick: () => void;
}) {
  const reduce = useReducedMotion();
  const [scope, animate] = useAnimate<HTMLDivElement>();
  const [ripples, setRipples] = useState<Ripple[]>([]);
  const [hover, setHover] = useState(false);
  const [bursts, setBursts] = useState(0);
  const nextId = useRef(0);

  /* a soft highlight that follows the pointer across the glass */
  const mx = useMotionValue(-200);
  const my = useMotionValue(-200);
  const glow = useMotionTemplate`radial-gradient(110px circle at ${mx}px ${my}px, rgb(255 255 255 / 0.28), transparent 70%)`;

  useEffect(() => {
    if (success && !reduce) setBursts((n) => n + 1);
  }, [success, reduce]);

  const interactive = !disabled && !busy;

  const onPointerDown = (e: ReactPointerEvent<HTMLButtonElement>) => {
    if (!interactive) return;
    const r = e.currentTarget.getBoundingClientRect();
    const id = nextId.current++;
    setRipples((list) => [...list, { id, x: e.clientX - r.left, y: e.clientY - r.top }]);
  };

  const onPointerMove = (e: ReactPointerEvent<HTMLButtonElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    mx.set(e.clientX - r.left);
    my.set(e.clientY - r.top);
  };

  const handleClick = () => {
    if (busy) return;
    if (disabled) {
      /* a quick "no" shake instead of a dead click */
      if (!reduce) animate(scope.current, { x: [0, -7, 7, -5, 5, -2, 0] }, { duration: 0.42, ease: "easeOut" });
      return;
    }
    onClick();
  };

  return (
    <div ref={scope} className="pswap__go">
      {/* success: a ring pulses out and specks fly from the centre */}
      {bursts > 0 && (
        <span key={bursts} aria-hidden="true" className="pswap__burst">
          <motion.span
            className="pswap__burstRing"
            initial={{ opacity: 0.7, scale: 1 }}
            animate={{ opacity: 0, scale: 1.16 }}
            transition={{ duration: 0.7, ease: "easeOut" }}
          />
          <span className="pswap__burstCore">
            {burst.map((b, i) => (
              <motion.span
                key={i}
                className="pswap__speck"
                style={{
                  width: b.size,
                  height: b.size,
                  marginLeft: -b.size / 2,
                  marginTop: -b.size / 2,
                  background: i % 2 ? "#7cc8ff" : "#4d82ff",
                }}
                initial={{ x: 0, y: 0, opacity: 1, scale: 1 }}
                animate={{ x: b.x, y: b.y, opacity: 0, scale: 0.3 }}
                transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
              />
            ))}
          </span>
        </span>
      )}

      <motion.button
        type="button"
        onClick={handleClick}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onHoverStart={() => setHover(true)}
        onHoverEnd={() => setHover(false)}
        aria-disabled={disabled || busy}
        aria-busy={busy}
        animate={{
          filter: disabled ? "saturate(0.25) brightness(1.08)" : "saturate(1) brightness(1)",
          boxShadow: hover && interactive ? hoverShadow : restShadow,
        }}
        transition={{ type: "spring", visualDuration: 0.25, bounce: 0.3 }}
        className="pswap__button"
        data-state={disabled ? "disabled" : busy ? "busy" : "ready"}
        style={{ boxShadow: restShadow }}
      >
        <span aria-hidden="true" className="pswap__water">
          {blobs.map((b, i) => (
            <motion.span
              /* re-keyed on busy so the new pace takes effect at once */
              key={`${i}-${busy}`}
              className="pswap__blob"
              style={{
                width: b.w,
                height: b.h,
                top: b.top,
                left: -b.w,
                background: `radial-gradient(closest-side, ${b.color}, transparent)`,
              }}
              animate={{ x: ["0%", "480%"] }}
              transition={{
                duration: busy ? b.dur / 3 : b.dur,
                delay: busy ? i * -0.4 : b.delay,
                repeat: Infinity,
                ease: "easeInOut",
              }}
            />
          ))}
          {sparks.map((s, i) => (
            <motion.span
              key={`s${i}`}
              className="pswap__spark"
              style={{ left: `${s.left}%`, top: `${s.top}%` }}
              animate={{ opacity: [0, 0.9, 0], scale: [0.4, 1.2, 0.4] }}
              transition={{ duration: s.dur, delay: s.delay, repeat: Infinity, ease: "easeInOut" }}
            />
          ))}
        </span>

        {/* the pointer-follow highlight */}
        <motion.span
          aria-hidden="true"
          className="pswap__glow"
          style={{ background: glow }}
          initial={false}
          animate={{ opacity: hover && interactive ? 1 : 0 }}
          transition={fade()}
        />

        {/* loading: a glossy band sweeps across while the swap is in flight */}
        <AnimatePresence>
          {busy && !success && (
            <motion.span
              key="sweep"
              aria-hidden="true"
              className="pswap__sweep"
              style={{ skewX: -12 }}
              initial={{ x: "-120%", opacity: 0 }}
              animate={{ x: "320%", opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={{ x: { duration: 1, repeat: Infinity, ease: "easeInOut" }, opacity: fade() }}
            />
          )}
        </AnimatePresence>

        {/* click ripples, spreading from where the pointer landed */}
        {ripples.map((r) => (
          <motion.span
            key={r.id}
            aria-hidden="true"
            className="pswap__ripple"
            style={{ left: r.x - 10, top: r.y - 10 }}
            initial={{ scale: 0, opacity: 1 }}
            animate={{ scale: 34, opacity: 0 }}
            transition={{ duration: 0.75, ease: [0.16, 1, 0.3, 1] }}
            onAnimationComplete={() => setRipples((list) => list.filter((x) => x.id !== r.id))}
          />
        ))}

        <motion.span
          className="pswap__buttonText"
          initial={false}
          animate={{ scale: success ? [1, 1.08, 1] : 1 }}
          transition={success ? { duration: 0.45, ease: "easeOut" } : morph}
        >
          {children}
        </motion.span>
      </motion.button>
    </div>
  );
}

/* ===========================================================================
   Swap Card.

   Two panels, a flip button on the seam between them and a liquid button
   under them. Everything is themed through the tokens below; --pswap-page is
   the field the card sits on, which the flip button's ring is cut from.
=========================================================================== */

.pswap {
  --pswap-page: #eaecef;
  --pswap-card: #ffffff;
  --pswap-ink: #1b1d22;
  --pswap-muted: #8a8f99;
  --pswap-faint: #a9adb5;
  --pswap-chip: #f2f3f5;
  --pswap-chip-hover: #e8e9ed;
  --pswap-accent: #2f6bff;
  --pswap-accent-soft: #e8f0ff;
  --pswap-list-shadow: 0 0 0 1px rgb(0 0 0 / 0.05), 0 16px 32px -12px rgb(0 0 0 / 0.25);

  display: flex;
  justify-content: center;
  width: 100%;
  color: var(--pswap-ink);
  font-family: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

.pswap[data-theme="dark"] {
  --pswap-page: #0e0f12;
  --pswap-card: #17191d;
  --pswap-ink: #f3f4f6;
  --pswap-muted: #8b909a;
  --pswap-faint: #5f646e;
  --pswap-chip: #23262c;
  --pswap-chip-hover: #2c3037;
  --pswap-accent: #6b97ff;
  --pswap-accent-soft: rgb(107 151 255 / 0.16);
  --pswap-list-shadow: 0 0 0 1px rgb(255 255 255 / 0.06), 0 16px 32px -12px rgb(0 0 0 / 0.6);
}

.pswap *,
.pswap *::before,
.pswap *::after {
  box-sizing: border-box;
}

.pswap button {
  margin: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  -webkit-tap-highlight-color: transparent;
}

.pswap :is(button, input):focus-visible {
  outline: 2px solid var(--pswap-accent);
  outline-offset: 2px;
}

.pswap__card {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 340px;
}

/* --- tabs ------------------------------------------------------------------- */

.pswap__tabsRow {
  display: flex;
  justify-content: center;
  margin-bottom: 10px;
}

.pswap__tabs {
  display: flex;
  gap: 4px;
}

.pswap .pswap__tab {
  position: relative;
  height: 28px;
  padding: 0 19px;
  border-radius: 999px;
  color: var(--pswap-muted);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: color 0.2s ease;
}

.pswap .pswap__tab:hover,
.pswap .pswap__tab[aria-selected="true"] {
  color: var(--pswap-ink);
}

.pswap__tabPill {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  background: var(--pswap-card);
  box-shadow:
    0 1px 2px rgb(0 0 0 / 0.06),
    0 2px 8px -2px rgb(0 0 0 / 0.06);
}

.pswap__tabText {
  position: relative;
}

/* --- panels ----------------------------------------------------------------- */

.pswap__slot {
  position: relative;
  z-index: 0;
}

/* the panel whose token list is open sits over the other one */
.pswap__slot[data-raised] {
  z-index: 30;
}

.pswap__panel {
  padding: 14px 16px;
  border-radius: 18px;
  background: var(--pswap-card);
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.03);
  transition: background-color 0.3s ease;
}

.pswap__panelLabel {
  margin: 0 0 12px;
  color: var(--pswap-muted);
  font-size: 13px;
  font-weight: 400;
  line-height: 1.4;
}

.pswap__row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.pswap__amount {
  flex: 1 1 0;
  min-width: 0;
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.035em;
  transition: font-size 0.2s ease;
}

.pswap__input {
  width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--pswap-ink);
  font-family: inherit;
  caret-color: var(--pswap-accent);
  outline: none;
}

.pswap .pswap__input:focus-visible {
  outline: none;
}

.pswap__input::placeholder {
  color: var(--pswap-faint);
  opacity: 1;
}

.pswap__out {
  display: flex;
  align-items: center;
  color: var(--pswap-ink);
}

.pswap__out[data-empty] {
  color: var(--pswap-faint);
}

.pswap__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 16px;
  color: var(--pswap-muted);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  line-height: 1.4;
}

.pswap__footRight {
  display: flex;
  align-items: center;
}

.pswap__usd {
  display: flex;
  align-items: center;
  gap: 6px;
}

.pswap__faint,
.pswap__have {
  color: var(--pswap-faint);
}

.pswap__have {
  margin-left: 4px;
}

.pswap .pswap__max {
  margin-left: 6px;
  padding: 3px 4px;
  border-radius: 4px;
  background: var(--pswap-accent-soft);
  color: var(--pswap-accent);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.025em;
  line-height: 1;
  cursor: pointer;
}

.pswap .pswap__max:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}

/* --- the flip button on the seam ----------------------------------------- */

.pswap__seam {
  position: relative;
  z-index: 20;
  height: 6px;
}

.pswap .pswap__flip {
  position: absolute;
  top: 50%;
  left: 50%;
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  translate: -50% -50%;
  border: 4px solid var(--pswap-page);
  border-radius: 999px;
  background: var(--pswap-card);
  color: var(--pswap-ink);
  cursor: pointer;
  transition: background-color 0.3s ease, border-color 0.3s ease;
}

.pswap__flipIcon {
  display: grid;
  place-items: center;
}

.pswap__flipIcon svg {
  width: 16px;
  height: 16px;
}

/* --- token picker ------------------------------------------------------------ */

.pswap__select {
  position: relative;
  flex: none;
}

.pswap .pswap__pill {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 4px 10px 4px 6px;
  background: var(--pswap-chip);
  color: var(--pswap-ink);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.15s ease;
}

.pswap .pswap__pill:hover {
  background: var(--pswap-chip-hover);
}

.pswap__pillToken {
  display: flex;
  align-items: center;
  gap: 8px;
}

.pswap__pillChevron {
  display: grid;
  color: var(--pswap-muted);
}

.pswap__chevron {
  display: block;
  width: 14px;
  height: 14px;
}

.pswap__coin {
  display: block;
  flex: none;
}

.pswap__list {
  position: absolute;
  top: 38px;
  right: 0;
  z-index: 50;
  width: 224px;
  max-height: 196px;
  margin: 0;
  padding: 6px;
  overflow-y: auto;
  overscroll-behavior: contain;
  border-radius: 16px;
  background: var(--pswap-card);
  box-shadow: var(--pswap-list-shadow);
  list-style: none;
  scrollbar-width: thin;
  scrollbar-color: var(--pswap-chip-hover) transparent;
}

.pswap__list::-webkit-scrollbar {
  width: 6px;
}

.pswap__list::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: var(--pswap-chip-hover);
}

.pswap .pswap__option {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 6px 8px;
  border-radius: 12px;
  text-align: left;
  cursor: pointer;
  transition: background-color 0.15s ease;
}

.pswap .pswap__option:hover,
.pswap .pswap__option:focus-visible {
  background: var(--pswap-chip);
  outline: none;
}

.pswap__optionName {
  flex: 1;
  line-height: 1.25;
}

.pswap__optionSymbol {
  display: block;
  color: var(--pswap-ink);
  font-size: 13px;
  font-weight: 500;
}

.pswap__optionFull {
  display: block;
  color: var(--pswap-muted);
  font-size: 11px;
}

.pswap__optionBalance {
  color: var(--pswap-muted);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.pswap__optionCheck {
  width: 16px;
  height: 16px;
  color: var(--pswap-accent);
}

/* --- rate line and details ------------------------------------------------------ */

.pswap .pswap__rate {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  margin-top: 6px;
  padding: 8px 14px;
  border-radius: 12px;
  color: var(--pswap-muted);
  font-size: 11px;
  cursor: pointer;
}

.pswap__rateText {
  position: relative;
  height: 14px;
  overflow: hidden;
  line-height: 14px;
}

.pswap__rateChevron {
  display: grid;
  place-items: center;
}

.pswap__rateChevron svg {
  transition: color 0.15s ease;
}

.pswap .pswap__rate:hover .pswap__rateChevron svg {
  color: var(--pswap-ink);
}

.pswap__drawer {
  overflow: hidden;
}

.pswap__details {
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 2px 14px 10px;
  font-size: 11.5px;
  line-height: 1.4;
}

.pswap__detail {
  display: flex;
  justify-content: space-between;
}

.pswap__detail dt {
  color: var(--pswap-muted);
}

.pswap__detail dd {
  margin: 0;
  color: var(--pswap-ink);
  font-variant-numeric: tabular-nums;
}

/* --- rolling text --------------------------------------------------------------- */

.pswap__swap {
  display: block;
  white-space: nowrap;
}

.pswap__roll {
  position: relative;
  display: inline-block;
  overflow: hidden;
  vertical-align: bottom;
}

.pswap__odometer {
  position: relative;
  display: inline-flex;
  overflow: hidden;
  padding: 0.12em 0;
  font-variant-numeric: tabular-nums;
}

.pswap__digit {
  display: inline-block;
}

/* --- the liquid button -------------------------------------------------------------- */

.pswap__go {
  position: relative;
  margin-top: 2px;
}

.pswap__burst {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.pswap__burstRing {
  position: absolute;
  inset: 0;
  border: 2px solid #4d82ff;
  border-radius: 999px;
}

.pswap__burstCore {
  position: absolute;
  top: 50%;
  left: 50%;
}

.pswap__speck {
  position: absolute;
  border-radius: 999px;
}

.pswap .pswap__button {
  position: relative;
  display: block;
  width: 100%;
  height: 46px;
  overflow: hidden;
  border-radius: 999px;
  background: linear-gradient(180deg, #4d82ff 0%, #2f64f5 100%);
  color: #ffffff;
  font-size: 15px;
  font-weight: 400;
  cursor: pointer;
  /* the round shape holds its overflow clip through the transforms inside it */
  isolation: isolate;
}

.pswap .pswap__button[data-state="disabled"] {
  cursor: not-allowed;
}

.pswap .pswap__button[data-state="busy"] {
  cursor: progress;
}

.pswap__water {
  position: absolute;
  inset: 0;
  mix-blend-mode: screen;
  pointer-events: none;
}

.pswap__blob {
  position: absolute;
  border-radius: 999px;
  filter: blur(10px);
}

.pswap__spark {
  position: absolute;
  width: 2px;
  height: 2px;
  border-radius: 999px;
  background: #ffffff;
}

.pswap__glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.pswap__sweep {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 33.333%;
  background: linear-gradient(90deg, transparent, rgb(255 255 255 / 0.38), transparent);
  pointer-events: none;
}

.pswap__ripple {
  position: absolute;
  width: 20px;
  height: 20px;
  border-radius: 999px;
  background: radial-gradient(closest-side, rgb(255 255 255 / 0.55), rgb(255 255 255 / 0));
  pointer-events: none;
}

.pswap__buttonText {
  position: relative;
  display: block;
}

.pswap__label {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 20px;
  overflow: hidden;
  line-height: 20px;
}

.pswap__labelInner {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.pswap__spin,
.pswap__done {
  width: 15px;
  height: 15px;
}

.pswap__spin {
  animation: pswap-spin 1s linear infinite;
}

@keyframes pswap-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .pswap__spin {
    animation-duration: 2.4s;
  }
}

