"use client";

import { useEffect, useRef } from "react";
import { animate, motionValue } from "motion/react";
import "./joystick.css";

/**
 * Joystick — a pixel-art arcade stick you can grab and throw.
 *
 * The stick is rasterised every frame onto a 64 × 52 canvas rather than drawn
 * from a sprite, so every tilt angle stays crisp, outlined and dithered like
 * hand-made pixel art, then scaled up by whole pixels. It sits in an octagonal
 * restrictor gate: drag it and it tracks the hand with a little mass, let go
 * and the return spring overshoots and settles like a real stick. Four
 * microswitches click as it crosses into each direction, the shaft thocks on
 * the gate, and the spring twangs on release — all synthesised, with haptics
 * on phones and rumble on gamepads.
 *
 * Drag it, or focus it and use the arrow keys or WASD; a connected gamepad's
 * stick or d-pad drives it too.
 */

export type JoystickDirection = "up" | "down" | "left" | "right";

export type JoystickProps = {
  /** The size of one art pixel, in CSS pixels. It shrinks to fit a narrow container. */
  pixel?: number;
  /** Microswitch clicks, the gate thock and the spring's twang. */
  sound?: boolean;
  theme?: "light" | "dark";
  /** Take keyboard focus on mount, so the arrow keys work straight away. */
  autoFocus?: boolean;
  /** Fired as the stick moves: x and y in −1…1, +x right and +y toward the player. */
  onMove?: (x: number, y: number) => void;
  /** Fired as each microswitch makes (true) and breaks (false). */
  onSwitch?: (direction: JoystickDirection, on: boolean) => void;
};

/* ── the art: a 64 × 52 canvas ────────────────────────────────────────────── */

const W = 64;
const H = 52;

/* RGBA bytes, little-endian, for a Uint32Array over ImageData */
const hex = (h: string) => {
  const n = parseInt(h.slice(1), 16);
  return ((255 << 24) | ((n & 255) << 16) | (n & 0xff00) | (n >> 16)) >>> 0;
};

const C = {
  out: hex("#17161c"),
  white: hex("#f7f7f5"),
  g1: hex("#d9dadc"),
  g2: hex("#b2b4b9"),
  g3: hex("#85878e"),
  r0: hex("#5c0b13"),
  r1: hex("#981520"),
  r2: hex("#cf222d"),
  r3: hex("#ea4850"),
  r4: hex("#ff8b90"),
  r5: hex("#ffe1e2"),
};

const PIVOT = { x: 32, y: 40 };
/** Pivot to ball centre, in art pixels. */
const STICK = 17;
/** Chosen so the circle rasterises without single-pixel nubs. */
const BALL_R = 9;
/** About 30°. */
const MAX_TILT = 0.52;
/** The camera looks down about 22°. */
const PITCH = 0.38;
const PLATE = { rx: 13.5, ry: 4.2 };

type Inside = (x: number, y: number) => boolean;
const ellipse =
  (cx: number, cy: number, rx: number, ry: number): Inside =>
  (x, y) =>
    ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 <= 1;
const dither = (x: number, y: number, a: number) => (((x + y) & 1) === 1 ? a : -a);

function createRenderer(canvas: HTMLCanvasElement) {
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext("2d")!;
  const img = ctx.createImageData(W, H);
  const px = new Uint32Array(img.data.buffer);
  const mask = new Uint8Array(W * H);

  /* fill a shape, optionally wrapping it in a 1px dark outline first */
  function shape(inside: Inside, color: number | ((x: number, y: number) => number), outline = true) {
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) mask[y * W + x] = inside(x + 0.5, y + 0.5) ? 1 : 0;

    if (outline) {
      for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
          const i = y * W + x;
          if (mask[i]) continue;
          if ((x > 0 && mask[i - 1]) || (x < W - 1 && mask[i + 1]) || (y > 0 && mask[i - W]) || (y < H - 1 && mask[i + W]))
            px[i] = C.out;
        }
      }
    }

    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const i = y * W + x;
        if (mask[i]) px[i] = typeof color === "function" ? color(x, y) : color;
      }
    }
  }

  /** jx, jy inside the gate (about −1…1); +x is right, +y toward the player. */
  function draw(jx: number, jy: number) {
    px.fill(0);
    const { x: Px, y: Py } = PIVOT;

    /* the stick's 3D direction, onto the screen */
    let dx = Math.tan(jx * MAX_TILT);
    let dy = 1;
    let dz = Math.tan(jy * MAX_TILT);
    const n = Math.hypot(dx, dy, dz);
    dx /= n;
    dy /= n;
    dz /= n;
    const bx = Px + STICK * dx;
    const by = Py + STICK * (-dy * Math.cos(PITCH) + dz * Math.sin(PITCH));
    /* nearer is a touch bigger */
    const R = BALL_R * (1 + dz * 0.1);

    /* the plate: its rim for thickness, then its top */
    shape(ellipse(Px, Py + 2, PLATE.rx, PLATE.ry), (x) => (x > Px + 6 ? C.g3 : C.g2));
    const plate = ellipse(Px, Py, PLATE.rx, PLATE.ry);
    shape(plate, (x, y) => {
      const s = ((x - Px) / PLATE.rx) * 0.6 + ((y - Py) / PLATE.ry) * 0.8 + dither(x, y, 0.06);
      return s > 0.55 ? C.g1 : C.white;
    });

    /* the ball's shadow on the plate */
    const shadow = ellipse(Px + (bx - Px) * 0.9, Py + dz * 1.5, 5.5, 1.7);
    shape((x, y) => shadow(x, y) && plate(x, y), C.g1, false);

    /* the dust washer and the shaft's hole */
    shape(ellipse(Px, Py, 4.6, 1.6), C.g2, false);
    shape(ellipse(Px, Py, 2.2, 0.9), C.g3, false);

    /* the shaft */
    const vx = bx - Px;
    const vy = by - Py;
    const len2 = vx * vx + vy * vy || 1;
    const len = Math.sqrt(len2);
    shape(
      (x, y) => {
        const t = Math.max(0, Math.min(1, ((x - Px) * vx + (y - Py) * vy) / len2));
        return Math.hypot(x - (Px + vx * t), y - (Py + vy * t)) <= 1.75;
      },
      (x, y) => {
        /* positive is to the right of the shaft */
        const side = -((x + 0.5 - Px) * vy - (y + 0.5 - Py) * vx) / len;
        return side > 0.55 ? C.g2 : C.white;
      },
    );

    /* the ball, banded and dithered */
    shape(
      (x, y) => (x - bx) ** 2 + (y - by) ** 2 <= R * R,
      (x, y) => {
        const nx = (x + 0.5 - bx) / R;
        const ny = (y + 0.5 - by) / R;
        const nz = Math.sqrt(Math.max(0, 1 - nx * nx - ny * ny));
        const l = -0.42 * nx - 0.62 * ny + 0.66 * nz;
        if (l > 0.955) return C.r5;
        const d = l + dither(x, y, 0.05);
        if (d > 0.84) return C.r4;
        if (d > 0.6) return C.r3;
        if (d > 0.22) return C.r2;
        if (d > -0.12) return C.r1;
        return C.r0;
      },
    );

    ctx.putImageData(img, 0, 0);
  }

  return { draw };
}

/* ── the gate and the springs ─────────────────────────────────────────────── */

/* the octagonal restrictor gate, its flat sides facing the eight directions */
const OCT = Math.PI / 8;
function clampToGate(x: number, y: number): [number, number] {
  const r = Math.hypot(x, y);
  if (r === 0) return [0, 0];
  const a = Math.atan2(y, x);
  const m = ((((a + OCT) % (2 * OCT)) + 2 * OCT) % (2 * OCT)) - OCT;
  const max = 1 / Math.cos(m) - 0.0001;
  return r > max ? [(x / r) * max, (y / r) * max] : [x, y];
}

/* held, it tracks the hand almost 1:1 with a little mass */
const HOLD = { type: "spring", stiffness: 1500, damping: 50, mass: 0.45 } as const;
/* let go, the return spring overshoots and settles like a real stick */
const RETURN = { type: "spring", stiffness: 540, damping: 10, mass: 0.55 } as const;
const RETURN_REDUCED = { type: "spring", stiffness: 500, damping: 40 } as const;

/** Switch "make" travel. */
const ON = 0.42;
/** Switch "break" travel — lower than make, so a stick resting on the line never chatters. */
const OFF = 0.3;

const KEYMAP: Record<string, JoystickDirection> = {
  ArrowUp: "up",
  KeyW: "up",
  ArrowDown: "down",
  KeyS: "down",
  ArrowLeft: "left",
  KeyA: "left",
  ArrowRight: "right",
  KeyD: "right",
};

/* ── component ────────────────────────────────────────────────────────────── */

export default function Joystick({
  pixel = 8,
  sound = true,
  theme = "light",
  autoFocus = false,
  onMove,
  onSwitch,
}: JoystickProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  /* read live inside the engine, so changing them never rebuilds it */
  const soundRef = useRef(sound);
  const muteRef = useRef<(muted: boolean) => void>(() => {});
  const onMoveRef = useRef(onMove);
  const onSwitchRef = useRef(onSwitch);
  const pixelRef = useRef(pixel);
  const fitRef = useRef<() => void>(() => {});
  onMoveRef.current = onMove;
  onSwitchRef.current = onSwitch;

  useEffect(() => {
    soundRef.current = sound;
    muteRef.current(!sound);
  }, [sound]);

  useEffect(() => {
    pixelRef.current = pixel;
    fitRef.current();
  }, [pixel]);

  useEffect(() => {
    const root = rootRef.current!;
    const stage = stageRef.current!;
    const canvas = canvasRef.current!;
    const cleanups: (() => void)[] = [];
    let alive = true;
    const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

    /* ── sound: synthesised with Web Audio, no files ── */
    const sfx = (() => {
      const VOLUME = 0.22;
      let ctx: AudioContext | null = null;
      let bus: GainNode | null = null;
      let noise: AudioBuffer | null = null;
      let muted = !soundRef.current;

      /*
       * Building the engine costs the main thread a noticeable slice, and built
       * inside the first grab it would stall that grab's first frames. So it is
       * built in idle time once the stick is on screen — suspended, if the page
       * has not seen a gesture yet — and the grab only has to resume it.
       */
      function build() {
        if (ctx) return;
        const AC = window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
        if (!AC) return;
        ctx = new AC();
        const comp = ctx.createDynamicsCompressor();
        comp.threshold.value = -18;
        comp.ratio.value = 6;
        bus = ctx.createGain();
        bus.gain.value = muted ? 0 : VOLUME;
        bus.connect(comp).connect(ctx.destination);
        noise = ctx.createBuffer(1, ctx.sampleRate / 2, ctx.sampleRate);
        const d = noise.getChannelData(0);
        for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
      }
      function unlock() {
        if (!ctx) build();
        if (ctx?.state === "suspended") void ctx.resume();
      }
      function warm() {
        if (alive) build();
      }
      const ready = () => !muted && ctx && bus && noise && ctx.state === "running";

      function tone({
        type = "square" as OscillatorType,
        freq,
        to,
        t,
        dur,
        gain,
        release = 0.03,
      }: {
        type?: OscillatorType;
        freq: number;
        to?: number;
        t: number;
        dur: number;
        gain: number;
        release?: number;
      }) {
        const o = ctx!.createOscillator();
        o.type = type;
        o.frequency.setValueAtTime(freq, t);
        if (to) o.frequency.exponentialRampToValueAtTime(to, t + dur);
        const g = ctx!.createGain();
        g.gain.setValueAtTime(0, t);
        g.gain.linearRampToValueAtTime(gain, t + 0.003);
        g.gain.setValueAtTime(gain, Math.max(t + 0.004, t + dur - release));
        g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
        o.connect(g).connect(bus!);
        o.start(t);
        o.stop(t + dur + 0.02);
        return o;
      }

      function hit({
        t,
        dur,
        gain,
        type = "highpass" as BiquadFilterType,
        freq = 6000,
        q = 0.8,
      }: {
        t: number;
        dur: number;
        gain: number;
        type?: BiquadFilterType;
        freq?: number;
        q?: number;
      }) {
        const src = ctx!.createBufferSource();
        src.buffer = noise;
        const f = ctx!.createBiquadFilter();
        f.type = type;
        f.frequency.value = freq;
        f.Q.value = q;
        const g = ctx!.createGain();
        g.gain.setValueAtTime(gain, t);
        g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
        src.connect(f).connect(g).connect(bus!);
        src.start(t, Math.random() * 0.3);
        src.stop(t + dur + 0.02);
      }

      return {
        unlock,
        warm,
        setMuted(value: boolean) {
          muted = value;
          if (ctx && bus) bus.gain.setTargetAtTime(value ? 0 : VOLUME, ctx.currentTime, 0.02);
        },
        /* microswitch: a crisp click on make, a softer one on break */
        click(make: boolean) {
          if (!ready()) return;
          const t = ctx!.currentTime;
          hit({ t, dur: make ? 0.016 : 0.01, gain: make ? 0.5 : 0.22, freq: make ? 4200 : 6000 });
          tone({ freq: make ? 2400 : 3200, to: make ? 1700 : 2500, t, dur: 0.012, gain: make ? 0.06 : 0.03, release: 0.008 });
        },
        /* the shaft bottoming out on the gate */
        thock() {
          if (!ready()) return;
          const t = ctx!.currentTime;
          tone({ freq: 130, to: 60, t, dur: 0.06, gain: 0.14 });
          hit({ t, dur: 0.045, gain: 0.3, type: "lowpass", freq: 900 });
        },
        /* the return spring's twang on release */
        boing(strength = 1) {
          if (!ready() || strength < 0.2) return;
          const t = ctx!.currentTime;
          const o = tone({ type: "triangle", freq: 300, to: 150, t, dur: 0.24, gain: 0.12 * strength, release: 0.18 });
          const lfo = ctx!.createOscillator();
          const depth = ctx!.createGain();
          lfo.frequency.value = 22;
          depth.gain.setValueAtTime(40, t);
          depth.gain.exponentialRampToValueAtTime(1, t + 0.24);
          lfo.connect(depth).connect(o.frequency);
          lfo.start(t);
          lfo.stop(t + 0.28);
        },
        /* a soft tick as the ball is grabbed */
        tick() {
          if (!ready()) return;
          hit({ t: ctx!.currentTime, dur: 0.02, gain: 0.18, type: "bandpass", freq: 2500, q: 2 });
        },
        close: () => void ctx?.close().catch(() => {}),
      };
    })();
    muteRef.current = sfx.setMuted;
    cleanups.push(sfx.close);

    /* any gesture on the page counts; iOS only unlocks audio on touchend or click */
    (["pointerdown", "touchend", "click", "keydown"] as const).forEach((type) => {
      document.addEventListener(type, sfx.unlock, { capture: true, passive: true });
      cleanups.push(() => document.removeEventListener(type, sfx.unlock, { capture: true }));
    });

    const ric = (window as Window & { requestIdleCallback?: (cb: () => void, o?: { timeout: number }) => number })
      .requestIdleCallback;
    if (ric) {
      const id = ric(sfx.warm, { timeout: 2000 });
      cleanups.push(() => window.cancelIdleCallback?.(id));
    } else {
      const id = window.setTimeout(sfx.warm, 120);
      cleanups.push(() => clearTimeout(id));
    }

    /* ── haptics, best effort: vibrate on Android, the switch-input tap on iOS 18+, rumble on gamepads ── */
    const haptics = (() => {
      const ua = navigator.userAgent;
      const isIOS = /iP(hone|ad|od)/.test(ua) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
      const canVibrate = typeof navigator.vibrate === "function";
      let iosLabel: HTMLLabelElement | null = null;
      if (isIOS) {
        iosLabel = document.createElement("label");
        iosLabel.setAttribute("aria-hidden", "true");
        iosLabel.style.cssText = "position:fixed;left:-9999px;top:0;opacity:0;pointer-events:none";
        const input = document.createElement("input");
        input.type = "checkbox";
        input.setAttribute("switch", "");
        input.tabIndex = -1;
        iosLabel.append(input);
        document.body.append(iosLabel);
        cleanups.push(() => iosLabel?.remove());
      }
      /* browsers ignore vibration until there has been a gesture */
      let unlocked = false;
      return {
        unlock() {
          unlocked = true;
        },
        pulse(ms = 10, power = 0.5) {
          if (!unlocked) return;
          try {
            if (canVibrate) navigator.vibrate(ms);
            else iosLabel?.click();
          } catch {
            /* unsupported — nothing to feel */
          }
          for (const pad of navigator.getGamepads?.() ?? []) {
            const actuator = (pad as (Gamepad & { vibrationActuator?: { playEffect?: (t: string, p: object) => Promise<unknown> } }) | null)
              ?.vibrationActuator;
            actuator
              ?.playEffect?.("dual-rumble", {
                duration: Math.max(ms, 20),
                strongMagnitude: power * 0.6,
                weakMagnitude: power,
              })
              .catch(() => {});
          }
        },
      };
    })();

    const unlock = () => {
      sfx.unlock();
      haptics.unlock();
    };

    /* ── the stick ── */
    const jx = motionValue(0);
    const jy = motionValue(0);
    const moveTo = (x: number, y: number, transition: typeof HOLD | typeof RETURN | typeof RETURN_REDUCED) => {
      animate(jx, x, transition);
      animate(jy, y, transition);
    };
    cleanups.push(() => {
      jx.stop();
      jy.stop();
      jx.destroy();
      jy.destroy();
    });

    /* ── rendering: whole art pixels, as large as the container allows ── */
    const renderer = createRenderer(canvas);
    let px = pixelRef.current;
    /* the stick plus four art pixels of air on each side, inside the parent's content box */
    function fit() {
      const parent = root.parentElement;
      let room = W * pixelRef.current;
      if (parent) {
        const cs = getComputedStyle(parent);
        room = parent.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
      }
      px = Math.max(2, Math.min(pixelRef.current, Math.floor(room / (W + 8))));
      root.style.setProperty("--pjoy-px", `${px}px`);
    }
    fitRef.current = fit;
    fit();
    if (root.parentElement && typeof ResizeObserver !== "undefined") {
      const ro = new ResizeObserver(fit);
      ro.observe(root.parentElement);
      cleanups.push(() => ro.disconnect());
    }

    let drawQueued = 0;
    function requestDraw() {
      if (drawQueued) return;
      drawQueued = requestAnimationFrame(() => {
        drawQueued = 0;
        renderer.draw(jx.get(), jy.get());
      });
    }
    cleanups.push(() => cancelAnimationFrame(drawQueued));
    renderer.draw(0, 0);

    /* ── microswitches and the gate: sound, haptics and events ── */
    const sw: Record<JoystickDirection, boolean> = { up: false, down: false, left: false, right: false };
    let atGate = false;

    function check(key: JoystickDirection, travel: number) {
      if (!sw[key] && travel > ON) {
        sw[key] = true;
        sfx.click(true);
        haptics.pulse(9, 0.35);
        onSwitchRef.current?.(key, true);
      } else if (sw[key] && travel < OFF) {
        sw[key] = false;
        sfx.click(false);
        haptics.pulse(4, 0.15);
        onSwitchRef.current?.(key, false);
      }
    }

    function onStickChange() {
      requestDraw();
      const x = jx.get();
      const y = jy.get();
      check("right", x);
      check("left", -x);
      check("down", y);
      check("up", -y);
      onMoveRef.current?.(x, y);

      const r = Math.hypot(x, y);
      if (!atGate && r > 0.97) {
        atGate = true;
        sfx.thock();
        haptics.pulse(16, 0.8);
        if (!reduce) {
          animate(
            stage,
            { x: [0, (x / r) * px * 0.6, 0], y: [0, (y / r) * px * 0.6, 0] },
            { duration: 0.12, ease: "easeOut" },
          );
        }
      } else if (atGate && r < 0.85) {
        atGate = false;
      }
    }
    cleanups.push(jx.on("change", onStickChange), jy.on("change", onStickChange));

    function letGo() {
      const strength = Math.min(1, Math.hypot(jx.get(), jy.get()));
      moveTo(0, 0, reduce ? RETURN_REDUCED : RETURN);
      sfx.boing(strength);
      if (strength > 0.3) haptics.pulse(12, 0.4);
    }

    /* ── input: one source at a time ── */
    let source: "pointer" | "keys" | "pad" | null = null;

    /* pointer */
    let grabX = 0;
    let grabY = 0;
    let base: [number, number] = [0, 0];
    let pointerId = -1;

    const onDown = (e: PointerEvent) => {
      if (e.button !== 0 && e.pointerType === "mouse") return;
      unlock();
      if (source && source !== "pointer") return;
      source = "pointer";
      pointerId = e.pointerId;
      stage.setPointerCapture(e.pointerId);
      grabX = e.clientX;
      grabY = e.clientY;
      base = [jx.get(), jy.get()];
      sfx.tick();
      haptics.pulse(5, 0.1);
    };
    const onMovePointer = (e: PointerEvent) => {
      if (source !== "pointer" || e.pointerId !== pointerId) return;
      /* the ball travels about nine art pixels to the gate */
      const throwPx = 9 * px;
      const [x, y] = clampToGate(base[0] + (e.clientX - grabX) / throwPx, base[1] + (e.clientY - grabY) / throwPx);
      moveTo(x, y, HOLD);
    };
    const release = (e: PointerEvent) => {
      if (source !== "pointer" || e.pointerId !== pointerId) return;
      source = null;
      pointerId = -1;
      letGo();
    };
    stage.addEventListener("pointerdown", onDown);
    stage.addEventListener("pointermove", onMovePointer);
    stage.addEventListener("pointerup", release);
    stage.addEventListener("pointercancel", release);
    stage.addEventListener("lostpointercapture", release);
    cleanups.push(() => {
      stage.removeEventListener("pointerdown", onDown);
      stage.removeEventListener("pointermove", onMovePointer);
      stage.removeEventListener("pointerup", release);
      stage.removeEventListener("pointercancel", release);
      stage.removeEventListener("lostpointercapture", release);
    });

    /*
     * The focus ring is for keyboard users: the browser's own guess at
     * :focus-visible shows it after a grab too, so the last kind of input
     * decides instead.
     */
    const byKeys = () => (root.dataset.input = "keys");
    const byPointer = () => (root.dataset.input = "pointer");
    document.addEventListener("keydown", byKeys, { capture: true, passive: true });
    document.addEventListener("pointerdown", byPointer, { capture: true, passive: true });
    cleanups.push(() => {
      document.removeEventListener("keydown", byKeys, { capture: true });
      document.removeEventListener("pointerdown", byPointer, { capture: true });
    });

    /* keyboard — only while the stick has focus, so it never takes the page's arrow keys */
    const held = new Set<JoystickDirection>();
    function applyKeys() {
      const x = (held.has("right") ? 1 : 0) - (held.has("left") ? 1 : 0);
      const y = (held.has("down") ? 1 : 0) - (held.has("up") ? 1 : 0);
      if (x === 0 && y === 0) {
        if (source === "keys") {
          source = null;
          letGo();
        }
        return;
      }
      if (source && source !== "keys") return;
      source = "keys";
      const r = Math.hypot(x, y);
      moveTo(x / r, y / r, HOLD);
    }
    const onKeyDown = (e: KeyboardEvent) => {
      const dir = KEYMAP[e.code];
      if (!dir || e.metaKey || e.ctrlKey || e.altKey) return;
      e.preventDefault();
      unlock();
      if (e.repeat) return;
      held.add(dir);
      applyKeys();
    };
    const onKeyUp = (e: KeyboardEvent) => {
      const dir = KEYMAP[e.code];
      if (!dir) return;
      held.delete(dir);
      applyKeys();
    };
    const onBlur = () => {
      held.clear();
      applyKeys();
    };
    root.addEventListener("keydown", onKeyDown);
    root.addEventListener("keyup", onKeyUp);
    root.addEventListener("blur", onBlur);
    cleanups.push(() => {
      root.removeEventListener("keydown", onKeyDown);
      root.removeEventListener("keyup", onKeyUp);
      root.removeEventListener("blur", onBlur);
    });

    /* gamepad — polled only while one is connected */
    let padRaf = 0;
    let padActive = false;
    function pollPad() {
      padRaf = 0;
      const pad = [...(navigator.getGamepads?.() ?? [])].find(Boolean);
      if (!pad || !alive) return;
      const b = (i: number) => pad.buttons[i]?.pressed;
      let x = pad.axes[0] ?? 0;
      let y = pad.axes[1] ?? 0;
      if (b(12) || b(13) || b(14) || b(15)) {
        x = (b(15) ? 1 : 0) - (b(14) ? 1 : 0);
        y = (b(13) ? 1 : 0) - (b(12) ? 1 : 0);
      }
      if (Math.hypot(x, y) > 0.15) {
        if (!source || source === "pad") {
          source = "pad";
          padActive = true;
          moveTo(...clampToGate(x, y), HOLD);
        }
      } else if (padActive) {
        padActive = false;
        if (source === "pad") source = null;
        letGo();
      }
      padRaf = requestAnimationFrame(pollPad);
    }
    const startPad = () => {
      if (!padRaf) padRaf = requestAnimationFrame(pollPad);
    };
    window.addEventListener("gamepadconnected", startPad);
    if ([...(navigator.getGamepads?.() ?? [])].some(Boolean)) startPad();
    cleanups.push(() => {
      window.removeEventListener("gamepadconnected", startPad);
      cancelAnimationFrame(padRaf);
    });

    /* ── entrance ── */
    if (!reduce) {
      animate(stage, { opacity: [0, 1] }, { duration: 0.25 });
      animate(stage, { y: [-6 * px, 0] }, { type: "spring", stiffness: 420, damping: 14 });
    }

    if (autoFocus) root.focus({ preventScroll: true });

    return () => {
      alive = false;
      cleanups.forEach((fn) => fn());
    };
    // the engine is built once; props it needs later are read through refs
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div
      ref={rootRef}
      className="pjoy"
      data-theme={theme}
      tabIndex={0}
      role="application"
      aria-label="Arcade joystick. Drag the ball, or use the arrow keys."
    >
      <div ref={stageRef} className="pjoy__stage">
        <canvas ref={canvasRef} className="pjoy__canvas" width={W} height={H} />
      </div>
    </div>
  );
}

/* ===========================================================================
   Joystick — a pixel-art arcade stick.

   One unit, --pjoy-px: the size of one art pixel on screen, set by the
   component to the largest whole pixel its container has room for. The canvas
   is 64 × 52 art pixels and is drawn at exactly that multiple, so the art never
   blurs between pixels.
=========================================================================== */

.pjoy {
  --pjoy-px: 8px;
  --pjoy-glow: #b4c9e0;
  --pjoy-ink: #1b2440;

  position: relative;
  display: inline-grid;
  place-items: center;
  /* room round the stick for the pool of light and the gate's knock */
  padding: calc(var(--pjoy-px) * 4);
  background: radial-gradient(closest-side at 50% 52%, var(--pjoy-glow), transparent 78%);
  outline: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.3s ease;
}

/* at night: navy, with the light pooled a shade brighter */
.pjoy[data-theme="dark"] {
  --pjoy-glow: #2d3750;
  --pjoy-ink: #e8edf7;
}

.pjoy[data-input="keys"]:focus-visible {
  outline: 3px dashed var(--pjoy-ink);
  outline-offset: -3px;
}

.pjoy__stage {
  cursor: grab;
  touch-action: none;
  will-change: transform;
}
.pjoy__stage:active {
  cursor: grabbing;
}

.pjoy__canvas {
  display: block;
  width: calc(var(--pjoy-px) * 64);
  height: calc(var(--pjoy-px) * 52);
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}

"use client";

import type React from "react";
import { useEffect, useRef, useState } from "react";
import { animate, useReducedMotion } from "motion/react";
import "./weather.css";

/* ------------------------------------------------------------------ props -- */

export type WeatherCondition = "clear" | "partly" | "rain";

export type WeatherDay = {
  /** Short day name, as it reads in the forecast. */
  day: string;
  condition: WeatherCondition;
  /** What the main panel says once this day is picked. */
  label: string;
  low: number;
  high: number;
};

export type WeatherProps = {
  /** The city on the square, compact card. */
  city?: string;
  /** The city once the card has opened out into the forecast. */
  forecastCity?: string;
  /** Five days works best; the first is the one shown on arrival. */
  days?: WeatherDay[];
  /** Start opened out rather than as the square. */
  defaultExpanded?: boolean;
  /** "light" sits on a pale page; "dark" swaps the shell and forecast to graphite for a dark one. */
  theme?: "light" | "dark";
  /** Fired when a day is picked from the forecast. */
  onSelect?: (day: WeatherDay, index: number) => void;
};

/* ------------------------------------------------------------------- data -- */

const DAYS: WeatherDay[] = [
  { day: "Mon", condition: "clear", label: "Clear sky", low: 8, high: 24 },
  { day: "Tue", condition: "partly", label: "Partly cloudy", low: 11, high: 25 },
  { day: "Wed", condition: "rain", label: "Rain showers", low: 13, high: 22 },
  { day: "Thu", condition: "partly", label: "Partly cloudy", low: 12, high: 23 },
  { day: "Fri", condition: "partly", label: "Partly cloudy", low: 12, high: 23 },
];

/*
 * The main panel takes the colour of the day on show. The hues live in the
 * stylesheet as tokens, so each theme can tune them for its own ground.
 */
const PANEL: Record<WeatherCondition, string> = {
  clear: "var(--pwx-clear)",
  partly: "var(--pwx-partly)",
  rain: "var(--pwx-rain)",
};

/* strong ease-out, for anything entering */
const EASE_OUT = [0.23, 1, 0.32, 1] as const;

/* ------------------------------------------------------------------ icons -- */

/* the forecast's icons are in colour; the panel's are one ink, since they sit on colour */
function Rays({ mono }: { mono?: boolean }) {
  const lines = mono
    ? [
        [16, 1.9, 16, 6.4], [16, 25.6, 16, 30.1], [1.9, 16, 6.4, 16], [25.6, 16, 30.1, 16],
        [6, 6, 9.2, 9.2], [22.8, 22.8, 26, 26], [6, 26, 9.2, 22.8], [22.8, 9.2, 26, 6],
      ]
    : [
        [16, 2.4, 16, 6.2], [16, 25.8, 16, 29.6], [2.4, 16, 6.2, 16], [25.8, 16, 29.6, 16],
        [6.4, 6.4, 9.1, 9.1], [22.9, 22.9, 25.6, 25.6], [6.4, 25.6, 9.1, 22.9], [22.9, 9.1, 25.6, 6.4],
      ];
  return (
    <g className="pwx__rays" stroke={mono ? "currentColor" : "#FFC800"} strokeWidth="2.6" strokeLinecap="round">
      {lines.map(([x1, y1, x2, y2], i) => (
        <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} />
      ))}
    </g>
  );
}

const CLOUD = "a5.3 5.3 0 0 1-.5-10.6 7 7 0 0 1 13.2 1.6 4.6 4.6 0 0 1-.9 9z";

function Icon({ kind, mono }: { kind: WeatherCondition; mono?: boolean }) {
  const sun = mono ? "currentColor" : "#FFC800";
  if (kind === "clear") {
    return (
      <svg viewBox="0 0 32 32" className="pwx__icon" aria-hidden="true">
        <circle cx="16" cy="16" r={mono ? 6.1 : 6.4} fill={sun} />
        <Rays mono={mono} />
      </svg>
    );
  }
  if (kind === "partly") {
    return (
      <svg viewBox="0 0 32 32" className="pwx__icon" aria-hidden="true">
        <g
          transform={mono ? "translate(-2.5 -4) scale(0.8)" : "translate(-2.5 -3.5) scale(0.82)"}
          style={{ transformOrigin: "16px 16px" }}
        >
          <circle cx="16" cy="16" r={mono ? 6.1 : 6.4} fill={sun} />
          <Rays mono={mono} />
        </g>
        <path d={`M12.6 27.4${CLOUD}`} fill={mono ? "currentColor" : "#4DA6FF"} />
      </svg>
    );
  }
  const top = mono ? 22.4 : 22.8;
  const drop = mono ? 25.2 : 25.4;
  return (
    <svg viewBox="0 0 32 32" className="pwx__icon" aria-hidden="true">
      <path d={`M11.6 ${top}${CLOUD}`} fill={mono ? "currentColor" : "#8E8E93"} />
      <g stroke={mono ? "currentColor" : "#4DA6FF"} strokeWidth="2.4" strokeLinecap="round">
        <line x1="12.6" y1={drop} x2="11.6" y2={drop + 3} />
        <line x1="17.4" y1={drop} x2="16.4" y2={drop + 3} />
        <line x1="22.2" y1={drop} x2="21.2" y2={drop + 3} />
      </g>
    </svg>
  );
}

/* --------------------------------------------------------------- odometer -- */

/**
 * The temperature. Each digit is a 0–9 strip in a clipping box; a new reading
 * only translates the strips, so the number rolls to its digits rather than
 * ticking through every value — and a second change mid-roll retargets from
 * wherever the strip has got to.
 */
function Odometer({ value, instant }: { value: number; instant: boolean }) {
  const digits = String(value).split("");
  return (
    <span className="pwx__odometer" data-instant={instant ? "true" : "false"} aria-label={`${value} degrees`}>
      {digits.map((digit, i) => (
        <span className="pwx__digit" key={`${digits.length}-${i}`} aria-hidden="true">
          <span
            className="pwx__strip"
            style={{ "--d": digit, "--n": i } as React.CSSProperties}
          >
            {Array.from({ length: 10 }, (_, d) => (
              <span key={d}>{d}</span>
            ))}
          </span>
        </span>
      ))}
    </span>
  );
}

/* -------------------------------------------------------------- component -- */

/**
 * A weather widget that opens out into a five-day forecast.
 *
 * One card, two states. Compact it is a square panel; opened, the panel shrinks
 * into a black shell and a dark forecast slides out beside it. Every dimension
 * is a custom property, so the two states — and the phone layout, where the
 * forecast stacks underneath — are the same few transitions with different
 * numbers, and a toggle mid-flight retargets instead of restarting.
 */
export default function Weather({
  city = "Los Angeles",
  forecastCity = "Amsterdam",
  days = DAYS,
  defaultExpanded = false,
  theme = "light",
  onSelect,
}: WeatherProps) {
  const reduced = useReducedMotion();
  const rootRef = useRef<HTMLDivElement>(null);
  const [expanded, setExpanded] = useState(defaultExpanded);
  const [picked, setPicked] = useState(0);
  const [pressed, setPressed] = useState(false);
  /* the label on show, which trails the pick so the old one can blur out first */
  const [label, setLabel] = useState(days[0]?.label ?? "");
  const [swapping, setSwapping] = useState(false);
  /* the strips start at 0 and roll up to the first reading once the card lands */
  const [temp, setTemp] = useState(0);
  const [instant, setInstant] = useState(true);

  const day = days[picked] ?? days[0];

  /* the entrance: up and in, then the odometer rolls to its first reading */
  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const first = days[0]?.high ?? 0;
    if (reduced) {
      setTemp(first);
      return;
    }
    const anim = animate(
      el,
      { opacity: [0, 1], transform: ["translateY(10px) scale(0.97)", "translateY(0px) scale(1)"] },
      { duration: 0.3, ease: EASE_OUT },
    );
    /* the inline transform is cleared once it lands, so hover and press own it again */
    anim.finished.then(() => {
      el.style.transform = "";
      el.style.opacity = "";
    });
    /* let the zeroed strips paint, then allow the roll */
    const frame = requestAnimationFrame(() => setInstant(false));
    const roll = setTimeout(() => setTemp(first), 120);
    return () => {
      anim.stop();
      cancelAnimationFrame(frame);
      clearTimeout(roll);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* label: out fast, in behind the icon */
  const swapTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => () => clearTimeout(swapTimer.current), []);

  function toggle() {
    setExpanded((open) => !open);
  }

  function pick(i: number) {
    if (i === picked) return;
    const next = days[i];
    setPicked(i);
    setTemp(next.high);
    clearTimeout(swapTimer.current);
    if (reduced) {
      setLabel(next.label);
    } else {
      setSwapping(true);
      swapTimer.current = setTimeout(() => {
        setLabel(next.label);
        setSwapping(false);
      }, 130);
    }
    onSelect?.(next, i);
  }

  return (
    <div
      ref={rootRef}
      className="pwx"
      data-theme={theme}
      data-state={expanded ? "expanded" : "compact"}
      data-condition={day.condition}
      data-pressed={pressed ? "true" : "false"}
      onPointerDown={() => setPressed(true)}
      onPointerUp={() => setPressed(false)}
      onPointerCancel={() => setPressed(false)}
      onPointerLeave={() => setPressed(false)}
    >
      {/* ── the main panel: tap it to open or close the forecast ── */}
      <div
        className="pwx__main"
        role="button"
        tabIndex={0}
        aria-expanded={expanded}
        aria-label={expanded ? "Collapse forecast" : "Expand forecast"}
        style={{ backgroundColor: PANEL[day.condition] }}
        onClick={toggle}
        onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            toggle();
          }
        }}
      >
        <div className="pwx__content">
          <div className="pwx__condition">
            {(["clear", "partly", "rain"] as const).map((kind) => (
              <span className="pwx__condIcon" data-cond-icon={kind} key={kind} aria-hidden="true">
                <Icon kind={kind} mono />
              </span>
            ))}
            <span className="pwx__condText" data-swapping={swapping ? "true" : "false"}>
              {label}
            </span>
          </div>

          <div className="pwx__temp">
            <Odometer value={temp} instant={instant || !!reduced} />
            <span aria-hidden="true">°</span>
          </div>

          <div className="pwx__city">
            <span className="pwx__cityLabel" data-city="compact" aria-hidden={expanded}>
              {city}
            </span>
            <span className="pwx__cityLabel" data-city="expanded" aria-hidden={!expanded}>
              {forecastCity}
            </span>
          </div>
        </div>
      </div>

      {/* ── the dark forecast, parked outside the card until it opens ── */}
      <div className="pwx__forecast" aria-hidden={!expanded}>
        {days.map((d, i) => (
          <button
            type="button"
            className="pwx__row"
            key={`${d.day}-${i}`}
            style={{ "--i": i } as React.CSSProperties}
            aria-pressed={i === picked}
            tabIndex={expanded ? 0 : -1}
            onClick={(event) => {
              event.stopPropagation();
              pick(i);
            }}
          >
            <span className="pwx__day">{d.day}</span>
            <span className="pwx__rowIcon">
              <Icon kind={d.condition} />
            </span>
            <span className="pwx__low">{d.low}</span>
            <span className="pwx__high">{d.high}</span>
          </button>
        ))}
      </div>
    </div>
  );
}

/* ===========================================================================
   Weather — a square widget that opens out into a five-day forecast.

   Every dimension is a custom property, so compact, expanded and the phone
   layout (where the forecast stacks underneath instead of beside) are the
   same transitions with different numbers. State lives in data attributes,
   so a toggle mid-flight retargets from wherever things are.
=========================================================================== */

.pwx {
  /* light: the panel colours, the black shell and the forecast drawn on it */
  --pwx-clear: #ffe500;
  --pwx-partly: #9ed0ff;
  --pwx-rain: #aab7c4;
  --pwx-shell: #000000;
  --pwx-shell-edge: transparent;
  --pwx-panel: #1c1c1e;
  --pwx-low: #5b5b60;
  --pwx-high: #8e8e93;
  --pwx-focus: rgba(0, 0, 0, 0.35);
  /* strong custom curves: the built-in easings are too weak */
  --pwx-out: cubic-bezier(0.23, 1, 0.32, 1);
  --pwx-drawer: cubic-bezier(0.32, 0.72, 0, 1);
  /* a small overshoot, enough to feel alive and not enough to wobble */
  --pwx-bounce: cubic-bezier(0.34, 1.26, 0.44, 1);

  --card-w: 210px;
  --card-h: 210px;
  --card-r: 36px;
  --main-w: 210px;
  --main-h: 210px;
  --main-x: 0px;
  --main-y: 0px;
  --main-r: 36px;
  --content-scale: 0.636;
  --dark-w: 240px;
  --dark-h: 224px;
  --dark-x: 210px; /* parked outside the card */
  --dark-y: 14px;
  --dur: 380ms;

  position: relative;
  display: block;
  width: var(--card-w);
  height: var(--card-h);
  overflow: hidden;
  border-radius: var(--card-r);
  /*
   * Compact, the main panel covers the card exactly — painting the black shell
   * underneath would leave a dark fringe along the rounded edge, so the shell
   * is only painted while expanded. It flips at the very end of the collapse,
   * by which point the panel already covers it.
   */
  background: transparent;
  color: #000;
  text-align: left;
  font-family: "Inter Tight", "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  contain: layout paint;
  touch-action: manipulation;
  user-select: none;
  transition:
    width var(--dur) var(--pwx-bounce),
    height var(--dur) var(--pwx-bounce),
    border-radius var(--dur) var(--pwx-drawer),
    background-color 1ms linear var(--dur),
    box-shadow 1ms linear var(--dur),
    transform 120ms var(--pwx-out);
}

.pwx[data-state="expanded"] {
  --card-w: 540px;
  --card-h: 252px;
  --card-r: 36px;
  --main-w: 260px;
  --main-h: 224px;
  --main-x: 14px;
  --main-y: 14px;
  --main-r: 26px;
  --content-scale: 0.678;
  --dark-x: 286px;
  --dark-y: 14px;
  --dur: 460ms;
  background: var(--pwx-shell);
  box-shadow: inset 0 0 0 1px var(--pwx-shell-edge);
  transition:
    width var(--dur) var(--pwx-bounce),
    height var(--dur) var(--pwx-bounce),
    border-radius var(--dur) var(--pwx-drawer),
    background-color 1ms linear,
    box-shadow 1ms linear,
    transform 120ms var(--pwx-out);
}

/*
 * Dark: the same card for a dark page. A pure-black shell would vanish into
 * it, so the shell is graphite with a hairline edge, the forecast is lifted a
 * step above it, and the panel hues take their dark-mode values — a touch
 * warmer and deeper, so they glow rather than glare.
 */
.pwx[data-theme="dark"] {
  --pwx-clear: #ffd60a;
  --pwx-partly: #82c3ff;
  --pwx-rain: #98a6b5;
  --pwx-shell: #161618;
  --pwx-shell-edge: rgba(255, 255, 255, 0.08);
  --pwx-panel: #242427;
  --pwx-low: #6e6e74;
  --pwx-high: #a1a1a7;
  --pwx-focus: rgba(0, 0, 0, 0.45);
}

.pwx *,
.pwx *::before,
.pwx *::after {
  box-sizing: border-box;
}

/* ── the main panel ── */

.pwx__main {
  position: absolute;
  top: 0;
  left: 0;
  width: var(--main-w);
  height: var(--main-h);
  border-radius: var(--main-r);
  background: var(--pwx-clear);
  transform: translate3d(var(--main-x), var(--main-y), 0);
  cursor: pointer;
  outline: none;
  touch-action: manipulation;
  /* the colour change takes plain ease; the morph keeps its own curves */
  transition:
    background-color 280ms ease,
    width var(--dur) var(--pwx-bounce),
    height var(--dur) var(--pwx-bounce),
    border-radius var(--dur) var(--pwx-drawer),
    transform var(--dur) var(--pwx-bounce);
}
.pwx__main:focus-visible {
  box-shadow: inset 0 0 0 3px var(--pwx-focus);
}

/* the content keeps its compact layout and is scaled — no font-size or padding animates */
.pwx__content {
  display: flex;
  width: 330px;
  height: 330px;
  flex-direction: column;
  justify-content: space-between;
  padding: 44px 36px 36px;
  transform-origin: top left;
  transform: scale(var(--content-scale));
  transition: transform var(--dur) var(--pwx-bounce);
}

.pwx__icon {
  display: block;
  width: 26px;
  height: 26px;
}

/* ── the temperature odometer ── */

.pwx__temp {
  display: flex;
  align-items: flex-start;
  font-size: 112px;
  font-weight: 500;
  line-height: 0.86;
  letter-spacing: -0.045em;
  font-variant-numeric: tabular-nums;
}

.pwx__odometer {
  display: flex;
}

.pwx__digit {
  display: block;
  height: 0.86em;
  overflow: hidden;
  /* tracking lives between the columns: inside a clipping box it would shave each glyph */
  letter-spacing: normal;
}
.pwx__digit + .pwx__digit {
  margin-left: -0.045em;
}

.pwx__strip {
  display: block;
  transform: translateY(calc(var(--d) * -10%));
  transition: transform 420ms var(--pwx-bounce) calc(var(--n) * 45ms);
}
.pwx__strip > span {
  display: block;
  height: 0.86em;
}
.pwx__odometer[data-instant="true"] .pwx__strip {
  transition: none;
}

/* ── the city ── */

.pwx__city {
  position: relative;
  height: 34px;
}
.pwx__cityLabel {
  position: absolute;
  bottom: 0;
  left: 0;
  font-size: 31px;
  font-weight: 600;
  letter-spacing: -0.03em;
  line-height: 1;
  white-space: nowrap;
  /* the outgoing one leaves fast and the incoming one waits: two words never overlap legibly */
  opacity: 1;
  filter: blur(0);
  transition:
    opacity 120ms var(--pwx-out),
    filter 120ms var(--pwx-out);
}
.pwx__cityLabel[data-city="expanded"],
.pwx[data-state="expanded"] .pwx__cityLabel[data-city="compact"] {
  opacity: 0;
  filter: blur(4px);
}
.pwx[data-state="expanded"] .pwx__cityLabel[data-city="expanded"],
.pwx[data-state="compact"] .pwx__cityLabel[data-city="compact"] {
  opacity: 1;
  filter: blur(0);
  transition:
    opacity 200ms var(--pwx-out) 150ms,
    filter 200ms var(--pwx-out) 150ms;
}

/* ── the forecast ── */

.pwx__forecast {
  position: absolute;
  top: 0;
  left: 0;
  display: flex;
  width: var(--dark-w);
  height: var(--dark-h);
  flex-direction: column;
  justify-content: space-between;
  padding: 18px 16px;
  border-radius: 26px;
  background: var(--pwx-panel);
  opacity: 0;
  transform: translate3d(var(--dark-x), var(--dark-y), 0);
  transition:
    opacity 140ms var(--pwx-out),
    width var(--dur) var(--pwx-bounce),
    height var(--dur) var(--pwx-bounce),
    transform var(--dur) var(--pwx-bounce);
}
.pwx[data-state="expanded"] .pwx__forecast {
  opacity: 1;
  transition:
    opacity 200ms var(--pwx-out) 120ms,
    width var(--dur) var(--pwx-bounce),
    height var(--dur) var(--pwx-bounce),
    transform var(--dur) var(--pwx-bounce);
}

.pwx__row {
  display: flex;
  width: 100%;
  align-items: center;
  margin: 0 -6px;
  padding: 3px 6px;
  border: 0;
  border-radius: 10px;
  color: #fff;
  background: transparent;
  font: inherit;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.5;
  font-variant-numeric: tabular-nums;
  text-align: left;
  cursor: pointer;
  outline: none;
  touch-action: manipulation;
  opacity: 0;
  transform: translate3d(10px, 0, 0);
  transition:
    opacity 120ms var(--pwx-out),
    transform 120ms var(--pwx-out),
    background-color 160ms ease;
}
.pwx__row[aria-pressed="false"] {
  color: #d1d1d6;
}
.pwx__row[aria-pressed="true"] {
  background: rgba(255, 255, 255, 0.09);
}
.pwx__row:focus-visible {
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.35);
}
@media (hover: hover) and (pointer: fine) {
  .pwx__row[aria-pressed="false"]:hover {
    background: rgba(255, 255, 255, 0.05);
  }
}

.pwx__day {
  width: 52px;
}
.pwx__rowIcon {
  display: flex;
  width: 36px;
  justify-content: center;
}
.pwx__low {
  width: 32px;
  margin-left: auto;
  color: var(--pwx-low);
  text-align: right;
}
.pwx__high {
  width: 44px;
  color: var(--pwx-high);
  text-align: right;
}

/* in on expand, 40ms apart; out together on collapse */
.pwx[data-state="expanded"] .pwx__row {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition:
    opacity 260ms var(--pwx-out) calc(160ms + var(--i) * 40ms),
    transform 260ms var(--pwx-bounce) calc(160ms + var(--i) * 40ms),
    background-color 160ms ease;
}

/* ── the condition: three stacked icons, one on show ── */

.pwx__condition {
  position: relative;
  display: flex;
  height: 30px;
  align-items: center;
  padding-left: 38px;
}
.pwx__condIcon {
  position: absolute;
  left: 0;
  display: block;
  width: 26px;
  height: 26px;
  opacity: 0;
  transform: scale(0.9);
  filter: blur(3px);
  transition:
    opacity 120ms var(--pwx-out),
    transform 120ms var(--pwx-out),
    filter 120ms var(--pwx-out);
}
.pwx__condText {
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1;
  white-space: nowrap;
  transition:
    opacity 120ms var(--pwx-out),
    filter 120ms var(--pwx-out);
}
.pwx__condText[data-swapping="true"] {
  opacity: 0;
  filter: blur(4px);
}
.pwx[data-condition="clear"] .pwx__condIcon[data-cond-icon="clear"],
.pwx[data-condition="partly"] .pwx__condIcon[data-cond-icon="partly"],
.pwx[data-condition="rain"] .pwx__condIcon[data-cond-icon="rain"] {
  opacity: 1;
  transform: scale(1);
  filter: blur(0);
  transition:
    opacity 200ms var(--pwx-out) 130ms,
    transform 240ms var(--pwx-drawer) 130ms,
    filter 200ms var(--pwx-out) 130ms;
}

/* ── press and hover ── */

/* a deliberate press is slower; the release snaps back at 120ms */
.pwx[data-pressed="true"] {
  transform: scale(0.985);
  transition:
    width var(--dur) var(--pwx-bounce),
    height var(--dur) var(--pwx-bounce),
    border-radius var(--dur) var(--pwx-drawer),
    transform 180ms var(--pwx-out);
}
@media (hover: hover) and (pointer: fine) {
  .pwx:hover {
    transform: translateY(-2px);
  }
  .pwx[data-pressed="true"]:hover {
    transform: translateY(-2px) scale(0.985);
  }
}

/* constant decorative motion is linear */
.pwx__rays {
  transform-box: fill-box;
  transform-origin: center;
  animation: pwx-spin 24s linear infinite;
}
@keyframes pwx-spin {
  to {
    transform: rotate(360deg);
  }
}

/* ── phone: the forecast stacks underneath and slides up instead of out ── */

@media (max-width: 580px) {
  .pwx {
    --card-w: 210px;
    --card-h: 210px;
    --main-w: 210px;
    --main-h: 210px;
    --content-scale: 0.636;
    --dark-w: 186px;
    --dark-h: 214px;
    --dark-x: 12px;
    --dark-y: 210px; /* parked just under the card */
  }
  .pwx[data-state="expanded"] {
    --card-w: 210px;
    --card-h: 440px;
    --main-w: 186px;
    --main-h: 186px;
    --main-x: 12px;
    --main-y: 12px;
    --main-r: 26px;
    --content-scale: 0.56;
    --dark-x: 12px;
    --dark-y: 210px;
  }
  /* a 44px touch target per row */
  .pwx__row {
    margin: 0 -8px;
    padding: 6px 8px;
  }
  .pwx__forecast {
    padding: 14px 16px;
  }
}

/* gentler, not still: keep the fades, drop the movement and the morph */
@media (prefers-reduced-motion: reduce) {
  .pwx__rays {
    animation: none;
  }
  .pwx,
  .pwx__main,
  .pwx__content,
  .pwx__forecast,
  .pwx__row,
  .pwx[data-state="expanded"] .pwx__forecast,
  .pwx[data-state="expanded"] .pwx__row {
    transition: opacity 200ms ease;
  }
  .pwx:hover,
  .pwx[data-pressed="true"],
  .pwx[data-pressed="true"]:hover {
    transform: translate3d(0, 0, 0);
  }
  .pwx__strip {
    transition: none;
  }
}

"use client";

import { useEffect, useRef } from "react";
import { animate, hover, press, stagger } from "motion/react";
import "./recorder.css";

/* ------------------------------------------------------------------ props -- */

export type RecorderProps = {
  /** How wide the card is drawn, in px. It shrinks further to fit a small screen. */
  size?: number;
  /** Tactile clicks on every press and a tick as you scrub, synthesised at play time. */
  sound?: boolean;
  /** Take the keyboard as soon as it mounts, so Space and S work straight away. */
  autoFocus?: boolean;
  /** "dark" graphite, or "light" porcelain. The red key is the same in both. */
  theme?: "light" | "dark";
  /** Fired when a take is saved, with its length in seconds. */
  onSave?: (seconds: number) => void;
};

type Mode = "idle" | "recording" | "paused" | "saved" | "playing";

/* ---------------------------------------------------------------- motion -- */

const PRESS = { type: "spring", stiffness: 1100, damping: 42, mass: 0.5 } as const;
const RELEASE = { type: "spring", stiffness: 600, damping: 15, mass: 0.6 } as const;
const SPRING = { type: "spring", stiffness: 420, damping: 32 } as const;
const SOFT = { type: "spring", stiffness: 170, damping: 22 } as const;
const ROLL = { type: "spring", stiffness: 420, damping: 34, mass: 0.8 } as const;
const MORPH = { type: "spring", stiffness: 460, damping: 24 } as const;

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
const pad2 = (n: number) => String(n).padStart(2, "0");

/* ---------------------------------------------------------------- geometry -- */

/* the card is authored at 700 × 700 and scaled to fit */
const SIZE = 700;

/** A radius-200 superellipse (n = 4), measured off the reference. */
function squirclePath(w: number, h: number, r: number, inset = 0, steps = 28) {
  const pts: string[] = [];
  const centers = [
    [w - r, r],
    [r, r],
    [r, h - r],
    [w - r, h - r],
  ];
  centers.forEach(([cx, cy], q) => {
    for (let i = 0; i <= steps; i++) {
      const t = ((q + i / steps) * Math.PI) / 2;
      const c = Math.cos(t);
      const s = Math.sin(t);
      const x = cx + r * Math.sign(c) * Math.sqrt(Math.abs(c));
      const y = cy - r * Math.sign(s) * Math.sqrt(Math.abs(s));
      pts.push(`${(x + inset).toFixed(2)} ${(y + inset).toFixed(2)}`);
    }
  });
  return `M${pts.join("L")}Z`;
}

const CLIP = `path("${squirclePath(SIZE, SIZE, 200)}")`;
const RIM = squirclePath(SIZE - 2, SIZE - 2, 199, 1);

/* the waveform */
const BAR_DT = 0.1; // seconds per bar
const PITCH = 10;
const HEAD_X = 380;
const BAR_OFFSET = 11.5;
const MIN_H = 4;
const MAX_H = 340;
const COLLAPSE_MS = 460;
const RIPPLE_MS = 700;

const LABELS: Record<Mode, string> = { idle: "READY", recording: "REC", paused: "PAUSED", saved: "SAVED", playing: "PLAY" };
/* the status dot's fill per mode; recording and paused fall back to the red gradient in the stylesheet */
const DOT_COLOR: Record<Mode, string> = {
  idle: "var(--prec-dot-idle)",
  recording: "",
  paused: "",
  saved: "var(--prec-dot-saved)",
  playing: "var(--prec-dot-play)",
};
const MAIN_GLYPH = { idle: "rec", recording: "pause", paused: "rec", saved: "play", playing: "pause" } as const;
const SIDE_GLYPH = { idle: "stop", recording: "stop", paused: "stop", saved: "clear", playing: "stop" } as const;
const MAIN_LABEL: Record<Mode, string> = {
  idle: "Record",
  recording: "Pause",
  paused: "Resume recording",
  saved: "Play",
  playing: "Pause playback",
};

/* a damped spring from 0 → 1 as a bar is born */
const grow = (age: number) => (age >= 0.7 ? 1 : Math.max(0, 1 - Math.exp(-age * 14) * Math.cos(age * 20)));

/* -------------------------------------------------------------- component -- */

/**
 * A voice recorder card — no microphone.
 *
 * The input is a generated voice-like signal, and playback is a silent, timed
 * replay of the same take. Record, pause and resume on the red key; stop saves
 * the take, and on a saved take the side key becomes hold-to-clear. Drag the
 * waveform, scroll over the card or use the arrow keys to scrub.
 *
 * The waveform is a fixed pool of bars that scroll under a fixed playhead, all
 * drawn from one frame loop, so nothing is created or destroyed while it runs.
 */
export default function Recorder({ size = 360, sound = true, autoFocus = false, theme = "dark", onSave }: RecorderProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const fitRef = useRef<HTMLDivElement>(null);
  const frameRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const waveRef = useRef<HTMLDivElement>(null);
  const barsRef = useRef<HTMLDivElement>(null);
  const dotsRef = useRef<HTMLDivElement>(null);
  const playheadRef = useRef<HTMLDivElement>(null);
  const recDotRef = useRef<HTMLSpanElement>(null);
  const labelRef = useRef<HTMLDivElement>(null);
  const timerRef = useRef<HTMLDivElement>(null);
  const sideRef = useRef<HTMLButtonElement>(null);
  const mainRef = useRef<HTMLButtonElement>(null);
  const holdRef = useRef<SVGRectElement>(null);
  const glyphRefs = useRef<Record<string, HTMLElement | SVGSVGElement | null>>({});

  /* read at play time, so the prop can change without rebuilding the card */
  const soundRef = useRef(sound);
  soundRef.current = sound;
  const onSaveRef = useRef(onSave);
  onSaveRef.current = onSave;

  useEffect(() => {
    const root = rootRef.current!;
    const fit = fitRef.current!;
    const frame = frameRef.current!;
    const card = cardRef.current!;
    const wave = waveRef.current!;
    const barsEl = barsRef.current!;
    const dotsEl = dotsRef.current!;
    const playhead = playheadRef.current!;
    const recDot = recDotRef.current!;
    const labelWrap = labelRef.current!;
    const timerEl = timerRef.current!;
    const kSide = sideRef.current!;
    const kMain = mainRef.current!;
    const holdRect = holdRef.current!;
    const G = glyphRefs.current as Record<string, HTMLElement>;
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let alive = true;
    const cleanups: (() => void)[] = [];
    const listen = <K extends keyof HTMLElementEventMap>(
      el: HTMLElement | Window,
      type: K | string,
      fn: (e: never) => void,
      opts?: AddEventListenerOptions,
    ) => {
      el.addEventListener(type, fn as EventListener, opts);
      cleanups.push(() => el.removeEventListener(type, fn as EventListener, opts));
    };
    const timers = new Set<ReturnType<typeof setTimeout>>();
    const later = (ms: number, fn: () => void) => {
      const id = setTimeout(() => {
        timers.delete(id);
        fn();
      }, ms);
      timers.add(id);
      return id;
    };

    /*
     * ── size: a compact card, shrinking further to fit ──
     * It measures the box it was put in rather than the window, so it fits a
     * sidebar or a stage as well as a page.
     */
    const host = root.parentElement ?? root;
    function fitToViewport() {
      const cs = getComputedStyle(host);
      const inner = host.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
      const room = Math.min(inner > 0 ? inner : window.innerWidth, window.innerWidth - 32);
      const s = Math.min(size / SIZE, room / SIZE, (window.innerHeight - 48) / SIZE);
      frame.style.transform = `scale(${s})`;
      fit.style.width = `${SIZE * s}px`;
      fit.style.height = `${SIZE * s}px`;
    }
    fitToViewport();
    listen(window, "resize", fitToViewport);
    if (typeof ResizeObserver !== "undefined") {
      const observer = new ResizeObserver(fitToViewport);
      observer.observe(host);
      cleanups.push(() => observer.disconnect());
    }

    /* ── state: idle → recording ⇄ paused → saved ⇄ playing ── */
    const S = { mode: "idle" as Mode, elapsed: 0, cursor: 0, nextBarAt: BAR_DT, view: 0 };
    let samples: { h: number; t: number }[] = [];

    /* ── tactile sound (Web Audio, made on the first press) ── */
    let ctx: AudioContext | undefined;
    let noiseBuf: AudioBuffer | undefined;
    function click(kind: "down" | "up" | "tick" = "down", gain = 1) {
      if (!soundRef.current) return;
      try {
        const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
        ctx ??= new Ctx();
        if (ctx.state === "suspended") void ctx.resume();
      } catch {
        return;
      }
      if (!noiseBuf) {
        noiseBuf = ctx.createBuffer(1, Math.floor(ctx.sampleRate * 0.03), ctx.sampleRate);
        const d = noiseBuf.getChannelData(0);
        for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / d.length, 4);
      }
      const t = ctx.currentTime;
      const src = ctx.createBufferSource();
      src.buffer = noiseBuf;
      const bp = ctx.createBiquadFilter();
      bp.type = "bandpass";
      bp.frequency.value = kind === "down" ? 2200 : kind === "tick" ? 5200 : 3400;
      bp.Q.value = 0.9;
      const g = ctx.createGain();
      g.gain.value = (kind === "down" ? 0.45 : kind === "tick" ? 0.08 : 0.24) * gain;
      src.connect(bp).connect(g).connect(ctx.destination);
      src.start(t);
      if (kind === "down") {
        const o = ctx.createOscillator();
        const og = ctx.createGain();
        o.frequency.setValueAtTime(150, t);
        o.frequency.exponentialRampToValueAtTime(50, t + 0.05);
        og.gain.setValueAtTime(0.12 * gain, t);
        og.gain.exponentialRampToValueAtTime(0.0001, t + 0.06);
        o.connect(og).connect(ctx.destination);
        o.start(t);
        o.stop(t + 0.07);
      }
    }
    const haptic = (ms = 8) => navigator.vibrate?.(ms);

    /* ── timer: HH:MM:SS, the digits roll and soften through a blur ── */
    timerEl.replaceChildren();
    const slots: HTMLSpanElement[] = [];
    "00:00:00".split("").forEach((ch) => {
      const el = document.createElement("span");
      if (ch === ":") {
        el.className = "prec__colon";
        el.textContent = ":";
        timerEl.append(el);
        return;
      }
      el.className = "prec__slot";
      el.innerHTML = "<span>0</span>";
      el.dataset.v = "0";
      timerEl.append(el);
      slots.push(el);
    });

    function setDigit(slot: HTMLSpanElement, ch: string, dir: number) {
      if (slot.dataset.v === ch) return;
      slot.dataset.v = ch;
      if (reduceMotion) {
        slot.innerHTML = `<span>${ch}</span>`;
        return;
      }
      const h = slot.offsetHeight || 58;
      const prev = slot.lastElementChild as HTMLElement | null;
      const next = document.createElement("span");
      next.textContent = ch;
      slot.append(next);
      animate(next, { y: [dir * h * 0.75, 0], opacity: [0, 1], filter: ["blur(5px)", "blur(0px)"] }, ROLL);
      if (prev) animate(prev, { y: -dir * h * 0.75, opacity: 0, filter: "blur(5px)" }, ROLL).then(() => prev.remove());
    }

    let lastSec = -1;
    function renderTimer(sec: number) {
      const s = Math.floor(sec + 1e-6);
      if (s === lastSec) return;
      const dir = s >= lastSec ? 1 : -1;
      lastSec = s;
      const str = pad2(Math.floor(s / 3600) % 100) + pad2(Math.floor(s / 60) % 60) + pad2(s % 60);
      str.split("").forEach((ch, i) => setDigit(slots[i], ch, dir));
    }

    /* ── waveform: pooled bars that scroll under a fixed playhead ── */
    barsEl.replaceChildren();
    dotsEl.replaceChildren();
    const POOL = Math.ceil(SIZE / PITCH) + 12;
    const pool = Array.from({ length: POOL }, () => {
      const el = document.createElement("span");
      el.className = "prec__bar";
      el.style.opacity = "0";
      barsEl.append(el);
      return { el, on: false, tf: "", op: -1, used: false };
    });

    const dots: { el: HTMLSpanElement; x: number; a: number }[] = [];
    for (let x = 392; x <= 672; x += 9) {
      const d = document.createElement("span");
      d.className = "prec__dot";
      d.style.left = `${x}px`;
      dotsEl.append(d);
      dots.push({ el: d, x, a: 1 });
    }

    const fx = { collapseAt: 0, rippleAt: 0 };

    function targetHead() {
      return S.mode === "recording" || S.mode === "paused" ? S.elapsed : S.cursor;
    }

    function renderWave(now: number) {
      const hIdx = S.view / BAR_DT;
      const n = samples.length;
      const reviewing = S.mode === "saved" || S.mode === "playing";
      const kFrom = Math.max(0, Math.floor(hIdx - HEAD_X / PITCH) - 2);
      const kTo = Math.min(n - 1, Math.ceil(hIdx + (SIZE - HEAD_X) / PITCH) + 2);
      const collapseP = fx.collapseAt ? (now - fx.collapseAt) / COLLAPSE_MS : 0;
      const rippleP = fx.rippleAt ? (now - fx.rippleAt) / RIPPLE_MS : 0;
      if (rippleP > 1) fx.rippleAt = 0;

      for (const p of pool) p.used = false;
      let lastX = -Infinity;

      for (let k = kFrom; k <= kTo; k++) {
        const x = HEAD_X - BAR_OFFSET - (hIdx - (k + 1)) * PITCH;
        if (x < -4 || x > SIZE) continue;
        const s = samples[k];
        let h = s.h * grow((now - s.t) / 1000);
        if (collapseP) {
          const d = Math.abs(HEAD_X - x) / HEAD_X;
          const local = clamp(collapseP * 1.7 - d * 0.7, 0, 1);
          h *= 1 - local * local * (3 - 2 * local);
        }
        if (rippleP) {
          const u = rippleP * 1.6 - (HEAD_X - x) / HEAD_X;
          if (u > 0 && u < 1) h *= 1 + 0.16 * Math.sin(Math.PI * u);
        }
        /* played and unplayed crossfade over about a bar and a half instead of flipping */
        const ahead = reviewing ? clamp((x - HEAD_X + 6) / 15, 0, 1) : 0;
        const op = 1 - 0.72 * ahead;
        const p = pool[k % POOL];
        p.used = true;
        lastX = Math.max(lastX, x);
        const tf = `translate3d(${x.toFixed(2)}px,5px,0) scaleY(${(Math.max(h, 0) / MAX_H).toFixed(4)})`;
        if (p.tf !== tf) {
          p.el.style.transform = tf;
          p.tf = tf;
        }
        if (Math.abs(p.op - op) > 0.004 || !p.on) {
          p.el.style.opacity = op.toFixed(3);
          p.op = op;
          p.on = true;
        }
      }
      for (const p of pool) {
        if (!p.used && p.on) {
          p.el.style.opacity = "0";
          p.on = false;
          p.op = -1;
        }
      }
      /* the dotted track fades out where audio takes its place */
      const edge = Math.max(HEAD_X + 6, lastX + 6);
      for (const d of dots) {
        const a = clamp((d.x - edge) / 10, 0, 1);
        if (Math.abs(a - d.a) > 0.01) {
          d.a = a;
          d.el.style.opacity = a.toFixed(2);
        }
      }
    }

    function collapseWave() {
      if (!samples.length || reduceMotion) {
        samples = [];
        return Promise.resolve();
      }
      fx.collapseAt = performance.now();
      return new Promise<void>((r) =>
        later(COLLAPSE_MS, () => {
          samples = [];
          fx.collapseAt = 0;
          r();
        }),
      );
    }

    /* generated "speech": words with a rise-and-fall envelope, then pauses */
    const voice = { i: 0, len: 0, peak: 0, speaking: false };
    function nextHeight() {
      if (voice.i >= voice.len) {
        voice.speaking = !voice.speaking;
        voice.i = 0;
        voice.len = voice.speaking ? 4 + Math.floor(Math.random() * 7) : 2 + Math.floor(Math.random() * 5);
        voice.peak = 0.55 + Math.random() * 0.45;
      }
      const u = (voice.i + 0.5) / voice.len;
      voice.i++;
      if (!voice.speaking) return MIN_H + Math.random() * 8;
      const env = Math.pow(Math.sin(Math.PI * u), 0.6);
      const a = clamp(env * voice.peak * (0.55 + Math.random() * 0.45), 0.02, 1);
      return MIN_H + Math.pow(a, 1.3) * (MAX_H - MIN_H);
    }

    /* ── status, glyph morphs, indicators ── */
    labelWrap.replaceChildren();
    const firstLabel = document.createElement("span");
    firstLabel.className = "prec__labelText";
    firstLabel.textContent = "READY";
    labelWrap.append(firstLabel);
    let currentLabel = "READY";
    function setLabel(text: string) {
      if (text === currentLabel) return;
      currentLabel = text;
      const prev = labelWrap.lastElementChild as HTMLElement | null;
      const next = document.createElement("span");
      next.className = "prec__labelText";
      next.textContent = text;
      labelWrap.append(next);
      if (reduceMotion) {
        prev?.remove();
        return;
      }
      animate(next, { y: [20, 0], opacity: [0, 1], filter: ["blur(4px)", "blur(0px)"] }, SPRING);
      if (prev) animate(prev, { y: -20, opacity: 0, filter: "blur(4px)" }, { duration: 0.2, ease: [0.4, 0, 1, 1] }).then(() => prev.remove());
    }

    let flashTimer: ReturnType<typeof setTimeout> | null = null;
    function flash(text: string, ms = 1100) {
      if (flashTimer) clearTimeout(flashTimer);
      setLabel(text);
      flashTimer = later(ms, () => {
        flashTimer = null;
        setLabel(LABELS[S.mode]);
      });
    }
    const refreshLabel = () => !flashTimer && setLabel(LABELS[S.mode]);

    let dotBlink: { stop: () => void } | undefined;
    let timerBlink: { stop: () => void } | undefined;
    function refreshIndicators() {
      dotBlink?.stop();
      timerBlink?.stop();
      recDot.style.background = DOT_COLOR[S.mode];
      if (reduceMotion) return;
      animate(recDot, { scale: [0.6, 1] }, RELEASE);
      animate(timerEl, { opacity: 1 }, { duration: 0.2 });
      if (S.mode === "recording") {
        dotBlink = animate(recDot, { opacity: [1, 0.2, 1] }, { duration: 1.2, repeat: Infinity, ease: "easeInOut" });
      } else {
        animate(recDot, { opacity: S.mode === "paused" ? 0.55 : 1 }, { duration: 0.2 });
      }
      if (S.mode === "paused") {
        timerBlink = animate(timerEl, { opacity: [1, 0.3, 1] }, { duration: 1.2, repeat: Infinity, ease: "easeInOut" });
      }
    }

    const shown: { main: string; side: string } = { main: "rec", side: "stop" };
    function morph(group: "main" | "side", next: string) {
      if (shown[group] === next) return;
      const out = G[shown[group]];
      const inn = G[next];
      shown[group] = next;
      if (reduceMotion) {
        out.style.opacity = "0";
        inn.style.opacity = "1";
        return;
      }
      animate(out, { opacity: 0, scale: 0.5, rotate: -25, filter: "blur(3px)" }, { duration: 0.16, ease: [0.4, 0, 1, 1] });
      animate(inn, { opacity: [0, 1], scale: [0.5, 1], rotate: [25, 0], filter: ["blur(3px)", "blur(0px)"] }, MORPH);
    }

    function refreshControls() {
      morph("main", MAIN_GLYPH[S.mode]);
      morph("side", SIDE_GLYPH[S.mode]);
      const sideOn = S.mode !== "idle";
      kSide.disabled = !sideOn;
      animate(kSide.querySelector(".prec__glyphs")!, { opacity: sideOn ? 1 : 0.35 }, { duration: 0.25 });
      kMain.setAttribute("aria-label", MAIN_LABEL[S.mode]);
      kSide.setAttribute("aria-label", S.mode === "saved" ? "Hold to clear the recording" : "Stop");
      kSide.title = S.mode === "saved" ? "Hold to clear  (hold S)" : "Stop  (S)";
      wave.style.cursor = S.mode === "saved" || S.mode === "playing" ? "grab" : "default";
    }

    function setMode(mode: Mode) {
      S.mode = mode;
      refreshLabel();
      refreshIndicators();
      refreshControls();
    }

    /* ── actions ── */
    function wiggle(el: HTMLElement) {
      if (!reduceMotion) animate(el, { x: [0, -6, 6, -4, 4, 0] }, { duration: 0.36, ease: "easeOut" });
    }

    function startTake() {
      Object.assign(S, { elapsed: 0, cursor: 0, nextBarAt: BAR_DT, view: 0 });
      samples = [];
      voice.i = voice.len = 0;
      voice.speaking = false;
      setMode("recording");
    }

    function saveTake() {
      S.cursor = S.elapsed;
      fx.rippleAt = performance.now();
      setMode("saved");
      onSaveRef.current?.(S.elapsed);
    }

    let playStart = 0;
    let playFrom = 0;
    function startPlayback() {
      if (S.elapsed <= 0) return;
      /* from the end, rewind — the waveform glides back rather than jumping */
      if (S.cursor >= S.elapsed - 0.05) S.cursor = 0;
      playFrom = S.cursor;
      playStart = performance.now();
      setMode("playing");
    }

    async function clearTake() {
      setMode("idle");
      flash("CLEARED", 1000);
      await collapseWave();
      Object.assign(S, { elapsed: 0, cursor: 0, view: 0 });
    }

    const actions = {
      main() {
        switch (S.mode) {
          case "idle":
            return startTake();
          case "recording":
            return setMode("paused");
          case "paused":
            return setMode("recording");
          case "saved":
            return startPlayback();
          case "playing":
            return setMode("saved");
        }
      },
      side() {
        switch (S.mode) {
          case "recording":
          case "paused":
            return saveTake();
          case "playing":
            S.cursor = S.elapsed;
            return setMode("saved");
        }
      },
    };

    /* ── press physics ── */
    function down(btn: HTMLElement, scale: number) {
      btn.classList.add("is-down");
      animate(btn, { scale }, PRESS);
      animate(btn.querySelector(".prec__glyphs")!, { scale: 0.88 }, PRESS);
      click("down");
      haptic();
    }
    function up(btn: HTMLElement) {
      btn.classList.remove("is-down");
      animate(btn, { scale: 1 }, RELEASE);
      animate(btn.querySelector(".prec__glyphs")!, { scale: 1 }, RELEASE);
      click("up");
    }

    cleanups.push(
      press(kMain, (el) => {
        down(el as HTMLElement, 0.93);
        actions.main();
        return () => up(el as HTMLElement);
      }),
    );

    /* the side key taps to stop; on a saved take it becomes hold-to-clear */
    type Hold = { anim: ReturnType<typeof animate>; done?: boolean };
    let hold: Hold | null = null;
    let holdShown = 0;
    const setHold = (v: number) => (holdRect.style.strokeDashoffset = String(1 - (holdShown = v)));
    function holdStart() {
      if (S.mode !== "saved") return false;
      const h = {} as Hold;
      h.anim = animate(holdShown, 1, { duration: 0.7 * (1 - holdShown), ease: "linear", onUpdate: setHold });
      h.anim.then(() => {
        if (hold !== h || !alive) return;
        h.done = true;
        haptic(18);
        click("down", 1.2);
        animate(holdShown, 0, { duration: 0.35, delay: 0.15, onUpdate: setHold });
        void clearTake();
      });
      hold = h;
      return true;
    }
    function holdEnd() {
      const h = hold;
      hold = null;
      if (!h || h.done) return;
      h.anim.stop();
      animate(holdShown, 0, { ...SPRING, onUpdate: setHold });
      flash("HOLD", 1000);
    }
    cleanups.push(
      press(kSide, (el) => {
        const btn = el as HTMLButtonElement;
        if (btn.disabled) {
          wiggle(btn);
          return;
        }
        down(btn, 0.95);
        const holding = holdStart();
        if (!holding) actions.side();
        return () => {
          up(btn);
          if (holding) holdEnd();
        };
      }),
    );

    [kMain, kSide].forEach((btn) =>
      cleanups.push(
        hover(btn, (el) => {
          const b = el as HTMLButtonElement;
          if (!b.classList.contains("is-down") && !b.disabled) animate(b, { scale: 1.03 }, SPRING);
          return () => {
            if (!b.classList.contains("is-down")) animate(b, { scale: 1 }, SPRING);
          };
        }),
      ),
    );

    /* ── scrubbing: drag the waveform or scroll over the card ── */
    const canScrub = () => S.mode === "saved" || S.mode === "playing";
    let lastTickIdx = -1;
    function scrubBy(sec: number) {
      S.cursor = clamp(S.cursor + sec, 0, S.elapsed);
      if (S.mode === "playing") {
        playFrom = S.cursor;
        playStart = performance.now();
      }
      const idx = Math.floor(S.cursor / BAR_DT);
      if (idx !== lastTickIdx) {
        lastTickIdx = idx;
        click("tick");
      }
    }

    let drag: { x: number; was: boolean } | null = null;
    listen(wave, "pointerdown", (e: PointerEvent) => {
      if (!canScrub()) return;
      wave.setPointerCapture(e.pointerId);
      wave.style.cursor = "grabbing";
      drag = { x: e.clientX, was: S.mode === "playing" };
      if (drag.was) setMode("saved");
    });
    listen(wave, "pointermove", (e: PointerEvent) => {
      if (!drag) return;
      const scale = frame.getBoundingClientRect().width / SIZE;
      const dx = (e.clientX - drag.x) / scale;
      drag.x = e.clientX;
      scrubBy((-dx / PITCH) * BAR_DT);
    });
    const endDrag = () => {
      if (!drag) return;
      const { was } = drag;
      drag = null;
      wave.style.cursor = canScrub() ? "grab" : "default";
      if (was && S.cursor < S.elapsed - 0.05) startPlayback();
    };
    listen(wave, "pointerup", endDrag);
    listen(wave, "pointercancel", endDrag);

    listen(
      card,
      "wheel",
      (e: WheelEvent) => {
        if (!canScrub()) return;
        e.preventDefault();
        scrubBy((e.deltaY + e.deltaX) * 0.004);
      },
      { passive: false },
    );

    /*
     * The keyboard: Space records, pauses and plays, S stops (hold it to clear
     * a saved take), and the arrows scrub. It listens on the card rather than
     * on the whole page, so it never swallows a Space meant to scroll.
     */
    listen(root, "keydown", (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      const k = e.key.toLowerCase();
      if (k === "arrowleft" || k === "arrowright") {
        if (!canScrub()) return;
        e.preventDefault();
        scrubBy(k === "arrowleft" ? -1 : 1);
        return;
      }
      if (k !== " " && k !== "s") return;
      e.preventDefault();
      if (e.repeat) return;
      if (k === " ") {
        down(kMain, 0.93);
        actions.main();
        later(110, () => up(kMain));
      } else if (kSide.disabled) {
        wiggle(kSide);
      } else {
        down(kSide, 0.95);
        if (!holdStart()) {
          actions.side();
          later(110, () => up(kSide));
        }
      }
    });
    listen(root, "keyup", (e: KeyboardEvent) => {
      if (e.key.toLowerCase() === "s" && hold) {
        up(kSide);
        holdEnd();
      }
    });

    /* ── the frame loop ── */
    let raf = 0;
    let last = performance.now();
    function tick(now: number) {
      if (!alive) return;
      const dt = Math.min(0.25, Math.max(0, (now - last) / 1000));
      last = now;

      if (S.mode === "recording") {
        S.elapsed += dt;
        while (S.elapsed >= S.nextBarAt) {
          samples.push({ h: nextHeight(), t: now });
          S.nextBarAt += BAR_DT;
        }
      } else if (S.mode === "playing") {
        S.cursor = clamp(playFrom + (now - playStart) / 1000, 0, S.elapsed);
        if (S.cursor >= S.elapsed) {
          S.cursor = S.elapsed;
          setMode("saved");
        }
      }

      /* the waveform follows the head with feed-forward and a critically damped
         correction: exact while moving, and a glide across any jump */
      const target = targetHead();
      const moving = S.mode === "recording" || S.mode === "playing" ? 1 : 0;
      S.view += moving * dt;
      S.view += (target - S.view) * (1 - Math.exp(-dt * (reduceMotion ? 1e3 : 9)));

      renderWave(now);
      renderTimer(target);
      raf = requestAnimationFrame(tick);
    }

    /* ── boot ── */
    renderTimer(0);
    setMode("idle");

    if (reduceMotion) {
      card.style.opacity = "1";
    } else {
      animate(card, { opacity: [0, 1], y: [28, 0], scale: [0.94, 1] }, SOFT);
      animate([kSide, kMain], { opacity: [0, 1], scale: [0.6, 1] }, { delay: stagger(0.08, { startDelay: 0.22 }), ...RELEASE });
      animate([recDot, labelWrap, timerEl], { opacity: [0, 1], x: [-12, 0] }, { delay: stagger(0.06, { startDelay: 0.28 }), ...SPRING });
      animate(
        dots.map((d) => d.el),
        { opacity: [0, 1], scaleY: [0, 1] },
        { delay: stagger(0.016, { startDelay: 0.32 }), duration: 0.35 },
      );
      animate(playhead, { scaleY: [0, 1] }, { delay: 0.28, ...SPRING });
    }

    if (autoFocus) root.focus({ preventScroll: true });

    raf = requestAnimationFrame((t) => {
      last = t;
      raf = requestAnimationFrame(tick);
    });

    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      timers.forEach(clearTimeout);
      if (flashTimer) clearTimeout(flashTimer);
      dotBlink?.stop();
      timerBlink?.stop();
      cleanups.forEach((fn) => fn());
      void ctx?.close().catch(() => {});
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [size]);

  const glyph = (name: string) => (el: HTMLElement | SVGSVGElement | null) => {
    glyphRefs.current[name] = el;
  };

  return (
    <div ref={rootRef} className="prec" data-theme={theme} tabIndex={-1} aria-label="Voice recorder">
      <div ref={fitRef} className="prec__fit">
        <div ref={frameRef} className="prec__frame">
          <div ref={cardRef} className="prec__card" style={{ clipPath: CLIP }}>
            <div className="prec__bg" />

            {/* ── the waveform ── */}
            <div ref={waveRef} className="prec__wave" aria-hidden="true">
              <div ref={barsRef} className="prec__bars" />
              <div ref={dotsRef} className="prec__dots" />
              {/* progressive glass: each layer blurs harder and covers less, toward the edge */}
              <div className="prec__edge prec__edge--l">
                <i /><i /><i /><i /><i /><i />
              </div>
              <div className="prec__edge prec__edge--r">
                <i /><i /><i /><i /><i /><i />
              </div>
              <div ref={playheadRef} className="prec__playhead" />
            </div>

            {/* ── status and timer ── */}
            <span ref={recDotRef} className="prec__recDot" />
            <div ref={labelRef} className="prec__label" aria-live="polite" />
            <div ref={timerRef} className="prec__timer" aria-label="Elapsed time" />

            {/* ── controls ── */}
            <button ref={sideRef} type="button" className="prec__side" aria-label="Stop" title="Stop  (S)">
              <svg className="prec__hold" width="107" height="171" viewBox="0 0 107 171" aria-hidden="true">
                <rect
                  ref={holdRef}
                  x="2"
                  y="2"
                  width="103"
                  height="167"
                  rx="51.5"
                  fill="none"
                  stroke="#f2322f"
                  strokeWidth="3"
                  strokeLinecap="round"
                  pathLength={1}
                  strokeDasharray="1"
                  strokeDashoffset="1"
                />
              </svg>
              <span className="prec__glyphs">
                <span ref={glyph("stop")} className="prec__glyph prec__stop" />
                <svg
                  ref={glyph("clear")}
                  className="prec__glyph prec__clear"
                  style={{ opacity: 0 }}
                  width="40"
                  height="40"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  aria-hidden="true"
                >
                  <path d="M12 4A8.6 8.6 0 1 1 4.55 8.3" />
                  <path d="M1.52 8.45 5 7.52 5.93 11" />
                </svg>
              </span>
            </button>

            <button ref={mainRef} type="button" className="prec__main" aria-label="Record" title="Record  (Space)">
              <span className="prec__glyphs">
                <span ref={glyph("rec")} className="prec__glyph prec__recGlyph" />
                <span ref={glyph("pause")} className="prec__glyph prec__pause" style={{ opacity: 0 }}>
                  <span />
                  <span />
                </span>
                <svg
                  ref={glyph("play")}
                  className="prec__glyph"
                  style={{ opacity: 0 }}
                  width="40"
                  height="44"
                  viewBox="0 0 40 44"
                  aria-hidden="true"
                >
                  <path
                    d="M8 5.6v32.8c0 2.3 2.5 3.7 4.5 2.5l26-16.4a2.9 2.9 0 0 0 0-5L12.5 3.1C10.5 1.9 8 3.3 8 5.6Z"
                    fill="#f6e2e1"
                  />
                </svg>
              </span>
            </button>

            {/* a continuous-curvature rim, drawn from the same path as the clip */}
            <svg className="prec__rim" width="700" height="700" viewBox="0 0 700 700" aria-hidden="true">
              <defs>
                <linearGradient id="prec-rim" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0" className="prec__rimStop prec__rimStop--0" />
                  <stop offset="0.25" className="prec__rimStop prec__rimStop--1" />
                  <stop offset="1" className="prec__rimStop prec__rimStop--2" />
                </linearGradient>
              </defs>
              <path d={RIM} fill="none" stroke="url(#prec-rim)" strokeWidth="2" />
            </svg>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ===========================================================================
   Recorder — a dark voice-recorder card with a scrolling waveform.

   Authored at 700 × 700 and scaled as one piece, so every position below is
   in that grid. The card's outline is a radius-200 superellipse, applied as a
   clip-path from the component, with a rim stroked from the same path.
=========================================================================== */

.prec {
  /* dark: graphite, white bars, frosted edges */
  --prec-bg:
    linear-gradient(90deg, rgba(0, 0, 0, 0.17) 0%, rgba(0, 0, 0, 0) 45%),
    linear-gradient(180deg, #262626 0%, #222222 45%, #1f1f1f 100%);
  --prec-bar: linear-gradient(180deg, #c4bade 0%, #eeebf8 7%, #fbfbfb 22%, #fbfbfb 78%, #eeebf8 93%, #c4bade 100%);
  --prec-track: #8f8f8f;
  --prec-tint-l: 29, 29, 29;
  --prec-tint-r: 35, 35, 35;
  --prec-sheen: rgba(255, 255, 255, 0.025);
  --prec-sheen-2: rgba(255, 255, 255, 0.015);
  --prec-playhead-ring: rgba(0, 0, 0, 0.55);
  --prec-label: #dedede;
  --prec-timer: #ececec;
  --prec-dot-idle: #5b5b5b;
  --prec-dot-saved: #bdbdbd;
  --prec-dot-play: #f2f2f2;
  --prec-side: linear-gradient(180deg, rgba(255, 255, 255, 0.1) 0%, rgba(255, 255, 255, 0.075) 100%);
  --prec-side-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.07), inset 0 -1px 0 rgba(0, 0, 0, 0.25);
  --prec-side-down: linear-gradient(180deg, rgba(255, 255, 255, 0.06) 0%, rgba(255, 255, 255, 0.05) 100%);
  --prec-side-down-shadow: inset 0 3px 8px rgba(0, 0, 0, 0.35), inset 0 -1px 0 rgba(255, 255, 255, 0.04);
  --prec-stop: linear-gradient(180deg, #e3dfde 0%, #d6d1d0 100%);
  --prec-stop-shadow: 0 1px 2px rgba(0, 0, 0, 0.25);
  --prec-clear: #e6e1e0;
  --prec-focus: rgba(255, 255, 255, 0.35);
  --prec-rim: #ffffff;
  --prec-rim-a: 0.32;
  --prec-rim-b: 0.04;

  display: grid;
  place-items: center;
  outline: none;
  -webkit-font-smoothing: antialiased;
}

.prec *,
.prec *::before,
.prec *::after {
  box-sizing: border-box;
}

.prec__fit {
  position: relative;
}

.prec__frame {
  position: absolute;
  top: 0;
  left: 0;
  width: 700px;
  height: 700px;
  transform-origin: top left;
}

.prec__card {
  position: absolute;
  inset: 0;
  isolation: isolate;
  opacity: 0;
}

.prec__bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: var(--prec-bg);
}

/*
 * Light: porcelain. The bars turn graphite and keep their lavender tips, the
 * glass edges are re-tinted to the paler card so the waveform still dissolves
 * into it, and the side key becomes a pressed-in well. The red key, the
 * playhead and the recording dot are the same in both — they are the product.
 */
.prec[data-theme="light"] {
  --prec-bg:
    linear-gradient(90deg, rgba(0, 0, 0, 0.035) 0%, rgba(0, 0, 0, 0) 45%),
    linear-gradient(180deg, #fbfbfa 0%, #f5f5f4 45%, #efefee 100%);
  --prec-bar: linear-gradient(180deg, #8d82b4 0%, #3b3848 7%, #242426 22%, #242426 78%, #3b3848 93%, #8d82b4 100%);
  --prec-track: #b9b9b9;
  --prec-tint-l: 238, 238, 237;
  --prec-tint-r: 246, 246, 245;
  --prec-sheen: rgba(255, 255, 255, 0.35);
  --prec-sheen-2: rgba(255, 255, 255, 0.2);
  --prec-playhead-ring: rgba(255, 255, 255, 0.9);
  --prec-label: #3d3d3d;
  --prec-timer: #1d1d1d;
  --prec-dot-idle: #c4c4c4;
  --prec-dot-saved: #6f6f6f;
  --prec-dot-play: #1d1d1d;
  --prec-side: linear-gradient(180deg, rgba(0, 0, 0, 0.065) 0%, rgba(0, 0, 0, 0.045) 100%);
  --prec-side-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.06), inset 0 -1px 0 rgba(255, 255, 255, 0.9);
  --prec-side-down: linear-gradient(180deg, rgba(0, 0, 0, 0.1) 0%, rgba(0, 0, 0, 0.08) 100%);
  --prec-side-down-shadow: inset 0 3px 8px rgba(0, 0, 0, 0.16), inset 0 -1px 0 rgba(255, 255, 255, 0.7);
  --prec-stop: linear-gradient(180deg, #3a3a3a 0%, #262626 100%);
  --prec-stop-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
  --prec-clear: #2c2c2c;
  --prec-focus: rgba(0, 0, 0, 0.25);
  --prec-rim: #000000;
  --prec-rim-a: 0.1;
  --prec-rim-b: 0.05;
}

/* ── the waveform ── */

.prec__wave {
  position: absolute;
  top: 60px;
  right: 0;
  left: 0;
  height: 350px;
  touch-action: none;
  user-select: none;
}

.prec__bars {
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.prec__dots {
  position: absolute;
  inset: 0;
}

.prec__bar {
  position: absolute;
  top: 0;
  left: 0;
  width: 3px;
  height: 340px;
  border-radius: 2px;
  /* a solid body with faint lavender tips */
  background: var(--prec-bar);
  transform-origin: 50% 50%;
  will-change: transform;
}

.prec__dot {
  position: absolute;
  top: 173px;
  width: 3px;
  height: 4px;
  border-radius: 2px;
  background: var(--prec-track);
}

/*
 * Progressive glass edges: six stacked backdrop blurs, each stronger than the
 * last but masked to a narrower band, so the blur ramps up toward the edge
 * instead of stepping. A tint on top lets the bars dissolve into it.
 */
.prec__edge {
  --to: to right; /* from the edge inward */
  --tint: var(--prec-tint-l);
  position: absolute;
  top: -30px;
  bottom: -30px;
  width: 190px;
  pointer-events: none;
}
.prec__edge--l {
  left: 0;
}
.prec__edge--r {
  right: 0;
  --to: to left;
  --tint: var(--prec-tint-r);
}
.prec__edge > i {
  position: absolute;
  inset: 0;
  -webkit-mask-image: linear-gradient(var(--to), #000 var(--a), transparent var(--b));
  mask-image: linear-gradient(var(--to), #000 var(--a), transparent var(--b));
}
.prec__edge > i:nth-child(1) { --a: 45%; --b: 100%; backdrop-filter: blur(1px); }
.prec__edge > i:nth-child(2) { --a: 32%; --b: 82%; backdrop-filter: blur(2.5px); }
.prec__edge > i:nth-child(3) { --a: 22%; --b: 64%; backdrop-filter: blur(5px); }
.prec__edge > i:nth-child(4) { --a: 12%; --b: 46%; backdrop-filter: blur(9px) saturate(120%); }
.prec__edge > i:nth-child(5) { --a: 5%; --b: 30%; backdrop-filter: blur(16px) saturate(130%); }
/* the last layer: the frosted tint and a faint sheen */
.prec__edge > i:nth-child(6) {
  --a: 0%;
  --b: 100%;
  background:
    linear-gradient(180deg, var(--prec-sheen), rgba(255, 255, 255, 0) 40%, var(--prec-sheen-2)),
    linear-gradient(var(--to), rgba(var(--tint), 0.6) 0%, rgba(var(--tint), 0.28) 35%, rgba(var(--tint), 0) 100%);
  -webkit-mask-image: linear-gradient(180deg, transparent 0%, #000 14%, #000 86%, transparent 100%);
  mask-image: linear-gradient(180deg, transparent 0%, #000 14%, #000 86%, transparent 100%);
}
@supports not (backdrop-filter: blur(1px)) {
  .prec__edge > i:nth-child(6) {
    background: linear-gradient(var(--to), rgba(var(--tint), 0.92), rgba(var(--tint), 0));
  }
}

