}
/* a mono colon is a full cell; pull the neighbours in so it sits centred */
.prec__colon {
  display: inline-block;
  width: 0.6em;
  height: 1.05em;
  margin-inline: -0.115em;
  text-align: center;
}

/* ── controls ── */

.prec__side,
.prec__main {
  position: absolute;
  padding: 0;
  border: 0;
  border-radius: 999px;
  outline: none;
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  transition:
    background 140ms ease,
    box-shadow 140ms ease;
}

.prec__glyphs {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
}
.prec__glyph {
  position: absolute;
}

.prec__side {
  top: 469px;
  left: 349px;
  width: 107px;
  height: 171px;
  background: var(--prec-side);
