}
.prec__side:disabled {
  cursor: default;
}
.prec__side:focus-visible {
  box-shadow: 0 0 0 3px var(--prec-focus);
}

.prec__hold {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.prec__stop {
  width: 41px;
  height: 41px;
  border-radius: 9px;
  background: var(--prec-stop);
  box-shadow: var(--prec-stop-shadow);
}
.prec__clear {
  color: var(--prec-clear);
}

/* the solid red key: a lit top and a shaded base, no outer shadow */
.prec__main {
  top: 472px;
  left: 472px;
  width: 163px;
  height: 163px;
  background:
    radial-gradient(120% 90% at 50% 0%, rgba(255, 255, 255, 0.16) 0%, rgba(255, 255, 255, 0) 55%),
    linear-gradient(180deg, #f5423f 0%, #ee302d 55%, #dd2522 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    inset 0 -2px 4px rgba(110, 0, 0, 0.2);
}
.prec__main.is-down {
  background:
    radial-gradient(120% 90% at 50% 0%, rgba(255, 255, 255, 0.06) 0%, rgba(255, 255, 255, 0) 55%),
    linear-gradient(180deg, #df2c29 0%, #e3302d 100%);
  box-shadow:
    inset 0 3px 8px rgba(80, 0, 0, 0.4),
    inset 0 -1px 0 rgba(255, 255, 255, 0.08);
}
.prec__main:focus-visible {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    0 0 0 3px var(--prec-focus);
}

.prec__recGlyph {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  background: #f6e2e1;
}
.prec__pause {
  display: flex;
  gap: 10px;
}
.prec__pause > span {
  display: block;
  width: 12px;
  height: 36px;
  border-radius: 4px;
  background: #f3dedd;
}

.prec__rim {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
/* the rim catches light from above: bright on the dark card, a soft line on the light one */
.prec__rimStop {
  stop-color: var(--prec-rim);
}
.prec__rimStop--0 {
  stop-opacity: var(--prec-rim-a);
}
.prec__rimStop--1 {
  stop-opacity: var(--prec-rim-b);
}
.prec__rimStop--2 {
  stop-opacity: 0;
}

@media (prefers-reduced-motion: reduce) {
  .prec *,
  .prec *::before,
  .prec *::after {
    transition-duration: 0.01ms !important;
  }
}

